quests[28170] = { id = 28170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrecken der Nacht", description = "Mein Freund Uchek ist schon in der Höhle. Wir haben da drin drei Schreine aufgebaut. Ihr müsst nur die bösen Geister aus ihnen vertreiben, Mann.\n\nGeht in die Höhle hier und redet mit Uchek. Er versetzt Euch in Trance und in das Reich der Geister. Seid vorsichtig! Wenn Ihr ein Geistungeheuer seht, keine Panik. Lasst das Licht der Seelen für 'nen Moment oder zwei darauf scheinen und das Licht wird sie für immer verscheuchen. Das Licht wird für Eure Sicherheit sorgen. Jetzt geht und säubert die drei Schreine.", sourceObjective = "Sprecht mit Uchek im Rachen. Benutzt das Licht der Seelen aus dem Reich der Geister heraus, um Eure Sicherheit zu gewährleisten, wenn Ihr die drei Schreine in der Höhle besucht.", completion = "Seht Ihr? Man muss keine Angst vor den Toten haben. Ihr habt das Licht in die Dunkelheit getragen, Mann, und nicht mal geblinzelt.\n\nJetzt können wir diese Höhle als Operationsbasis für das nördliche Hochland nutzen. Ihr seid doch der Beste, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28171] = { id = 28171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... und der Himmel färbte sich rot", description = "Da Todesschwinge anderweitig abgelenkt ist, stellt sich uns eine düstere und schwere Aufgabe, in der uns die Königin höchstpersönlich leiten wird. Der schwarze Drachenschwarm muss getilgt werden.\n\nEure Hilfe würde ich gern in Anspruch nehmen, wenn Ihr denn zur Verfügung steht. Sobald Ihr bereit seid, werde ich Euch mit der nächsten Angriffswelle losschicken.", sourceObjective = "Schließt Euch dem Angriff gegen den schwarzen Drachenschwarm an.", completion = "Offensichtlich seid Ihr immer noch bei uns. Ich weiß das irgendwie zu schätzen.\n\nDanke.", sourceObjectiveStatus = "unverified-source-field" }
quests[28172] = { id = 28172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unschuldig", description = "Die Schwarzfelsorcs in der Steppe dienen einem finsteren Meister, der abartige Experimente an lebenden Wesen durchführt, um seine eigene Menagerie der Monstrositäten zu schaffen. Viele seiner Testobjekte sind so verderbt wie ihr Meister, aber ein paar davon sind vollkommen unschuldig.\n\nIn den Schlupfhügeln im Süden ketten sie Jungdrachen am Boden fest, um sie für solche Experimente vorzubereiten. Das lasse ich nicht zu. Zerbrecht ihre Fesseln und bringt die Brutlinge zu mir... in Sicherheit.", sourceObjective = "Beschafft einen befreiten roten Welpling, einen befreiten grünen Welpling, einen befreiten blauen Welpling und einen befreiten bronzefarbenen Welpling.", progress = "Ich hoffe, wir kommen nicht zu spät.", completion = "Ich werde mich darum kümmern, dass diese Drachen versorgt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28173] = { id = 28173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarz vor Augen", description = "Die Zwielichtdrachenjäger haben teuflische Werkzeuge angewendet, um unsere Drachen vom Himmel zu holen. Haken, die sich tief in die Schuppen bohrten und es den Anhängern des Zwielichts gestatteten, unsere Angehörigen gefahrlos zu Boden zu zerren.\n\nWir befinden uns jenseits aller Aussicht auf Frieden. Ohne Hoffnung, daß sie sich rückbesinnen werden. Die Vernichtung, der sie sich so leidenschaftlich hingeben, ist die einzige Gnade, die wir dem schwarzen Schwarm noch gewähren können.\n\nBenutzt diese Haken, um die Obsidianflammenschwingen südlich von hier zu töten. Richtig angewendet, verschaffen sie Euch in der Luft reichlich Bewegungsfreiheit", sourceObjective = "Benutzt die Wyrmjägerhaken, um 8 Obsidianflammenschwingen zu erreichen und tötet diese dann.", completion = "Ihr scheint diese verstörenden Werkzeuge mit Leichtigkeit einzusetzen.\n\nEs tröstet mich zu wissen, dass einige Werkzeuge des Bösen am Ende dazu benutzt werden können, um Leben zu retten. Alles erfüllt einen Zweck.", sourceObjectiveStatus = "unverified-source-field" }
quests[28174] = { id = 28174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennende Rache", description = "Die Schwarzfelsorcs geben nicht auf. Sie schwärmen über die Schlachtfelder im Osten, bereit, jeden Moment zuzuschlagen.\n\nSie haben mein Heimatland bereits einmal angegriffen. Ich bin hier um sicherzustellen, dass das nicht noch einmal geschieht.\n\nWenn Ihr auch nur im Entferntesten etwas für die Menschheit übrig habt, macht Ihr dasselbe. Also beweist Euch. Begebt Euch nach Süden zu den Schlupfhügeln und tötet ihre Jungdrachenbändiger und die ausgeschlüpften schwarzen Drachen. Beweist mir, dass Ihr für diesen Krieg bereit seid.", sourceObjective = "Tötet 5 Jungdrachenbändiger des Schwarzfels und 5 Flammenschuppenbrutlinge.", completion = "Ihr seid also dabei?\n\nGut.", sourceObjectiveStatus = "unverified-source-field" }
quests[28175] = { id = 28175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht in der Dunkelheit", description = "Der große versteinerte Baum, der sich vor uns im Süden befindet, war einst ein Leuchtfeuer von großem Leben. Unser Leuchtfeuer. Wir haben diesen Wald an den schwarzen Schwarm verloren und seitdem ist er verdorben und versteinert. Es ist fast nicht rückgängig zu machen.\n\nAber noch ist nicht alle Hoffnung verloren. Ich habe ein mächtiges Werkzeug hergebracht, um den Heilungsprozess zu beginnen. Mit viel Zeit und Glück kann der Baum vielleicht noch gerettet werden - und mit ein wenig Anstrengung von Euch vielleicht.\n\nNehmt das hier, Alexstraszas Träne, und benutzt sie im hohlen Inneren des Baums.", sourceObjective = "Benutzt Alexstraszas Träne in der Aushöhlung unter dem Obsidianbaum.", progress = "Der schwarze Schwarm wird wahrscheinlich nie wieder rehabilitiert, aber auch nach all ihrer Zerstörung gibt es immer noch Hoffnung auf neues Leben.", completion = "Ihr habt heute etwas Wunderbares begonnen, mitten in all dem Blutvergießen.\n\nEs mag viele Jahre dauern, aber dieses Verwüstete Land wird wiederhergestellt werden. Es wird wieder wunderschön sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[28176] = { id = 28176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Folgt den Jungen heim", description = "Im südwestlichen Teil des Obsidianwalds werdet Ihr einige Gelege schwarzer Eier finden. Viele Eier können jederzeit zum Schlüpfen gebracht werden, wenn die richtige Flamme sie ein wenig wärmt. Wenn die Welpen schlüpfen, werden sie einen Schrei ausstoßen und nach ihrer Mutter suchen.\n\nKeine Angst, wenn die Auslöschung sich auf die Welpen ausweiten sollte, werde ich Euch diese Aufgabe nicht aufzwingen. Ich möchte nur, dass Ihr sie heraus lasst und ihnen nach Hause folgt, wenn sie ihre Mutter suchen. Mit ihr müssen wir uns auseinandersetzen.", sourceObjective = "Benutzt die Flamme der Mutter auf Obsidianeiern, um Welpen hervorzubringen. Folgt diesen Jungen zum Hort ihrer Mutter.", progress = "Kein schwarzer, brutfähiger Drache darf am Leben bleiben.", completion = "Lirastrasza hat mich bereits in der Annahme zum Hort vorausgeschickt, dass der Schwarzdrache, den wir suchen, vielleicht noch hier ist. Den Jungen nach zu urteilen, hat sie wohl recht gehabt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28177] = { id = 28177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstockung", description = "Wenn wir einen Krieg gegen den Schwarzfelsklan führen wollen, müssen wir vorausplanen. Mein Oberst hat bereits einen Plan geschmiedet - jetzt wird es Zeit, ihn in die Tat umzusetzen.\n\nIch brauche Skorpidstachel... die schärfsten, die Ihr finden könnt. Skorpide befinden sich überall in der Steppe, aber die meisten befinden sich in der Schlucht im Westen.\n\nZerbrecht Euch nicht den Kopf darüber, wofür sie sind. Das werdet Ihr noch früh genug herausfinden.", sourceObjective = "Besorgt 5 rasiermesserscharfe Skorpidstachel.", progress = "Schon zurück?", completion = "Man kann diese Skorpiden leicht unterschätzen. Ihr habt Glück, dass Ihr nicht an einem dieser Stachel steckt. Oder vielleicht seid Ihr einfach nur gut.\n\nIch füge sie dem Vorratslager hinzu. Wir sind noch nicht fertig, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28178] = { id = 28178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein zukünftiges Projekt", description = "Wir werden Worgbälge brauchen und zwar viele. Es spielt keine Rolle, ob sie zerrissen, verbrannt oder blutig sind. Hauptsache es sind genügend.\n\nWahrscheinlich ist es sogar besser, wenn sie ein wenig ramponiert aussehen.\n\nWorgs findet Ihr im Westen und im Osten.", sourceObjective = "Besorgt 11 Glutworgbälge.", progress = "Dann schauen wir uns die Bälge mal an.", completion = "Glaubt mir, {name}... Ich kann es genauso wenig wie Ihr abwarten, bis wir endlich zum Töten kommen. Aber wir müssen uns an den Plan halten. Das Jüngste Gericht kommt früh genug.\n\nIch werde diese Bälge hier aufbewahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[28179] = { id = 28179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlammschlacht", description = "Ich hoffe, Ihr habt keine Angst davor, Euch schmutzig zu machen. Aber wenn ich Euch so ansehe, dürfte das kein Problem sein.\n\nIm Norden am Rand der Lava findet Ihr dunkle Schlammhaufen. Den Schlamm brauche ich.\n\nAm besten stellt Ihr keine Fragen und konzentriert Eure Bemühungen darauf, Befehle zu befolgen, {name}.", sourceObjective = "Besorgt 9 Haufen obsidiandurchsetzten Schlamm.", progress = "Ihr solltet Euch vor den Obsidianelementaren hüten. Sie schleichen sich gerne an.", completion = "Das ist genau das, was wir brauchen!\n\nKeine Sorge, {name}... Das Orctöten wird noch früh genug kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28180] = { id = 28180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sand, der Apfelwein und die Kugel", description = "Oberst Trottmann wartet auf uns im Osten. Bevor wir uns auf den Weg machen, sollten wir allerdings noch etwas mehr Zeug zusammensuchen. Diesmal werdet Ihr es einem Hexenmeister mit Namen Gorzeeki Wildaug abnehmen.\n\nWahrscheinlich findet Ihr ihn im Nordwesten in der Nähe des Altars der Stürme. Sagt ihm, dass er uns helfen wird. Wir brauchen den Sand, den Apfelwein und die Kugel.\n\nEr weiß schon, was das bedeutet.", sourceObjective = "Sprecht mit Gorzeeki Wildaug in der Nähe des Altars der Stürme.", completion = "Bah! Wer seid Ihr?\n\nOh, also hat Keeshan Euch geschickt? Gut. Würde es Euch etwas ausmachen, wenn Ihr eine Weile hier bleibt? Nichts großes... Ihr müsst nur ein paar Hexenmeister für mich töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28181] = { id = 28181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexenmeister haben das beste Zeug", description = "Keeshan sagte, er braucht Vorräte? Ich habe reichlich Vorräte! Das Problem ist nur, dass diese Hexenmeister mich aus meinem Zuhause geworfen haben und mich nicht wieder hineinlassen.\n\n<Gorzeeki mustert Euch.>\n\nIhr könntet vielleicht hineingelangen. Geht nach Norden und holt mir meinen Schlummersand, mein Teufelskarussellstöffsche und eine klare Glaskugel. Ich bin mir ziemlich sicher, dass es das ist, was er haben will.\n\nOh, und falls Ihr aus Versehen ein paar dieser Orcs tötet, während Ihr da oben seid, wäre ich bestimmt nicht traurig.", sourceObjective = "Besorgt eine Handvoll Schlummersand, einen Krug Teufelskarussellstöffsche und eine lupenreine Glaskugel.", progress = "Mal sehen, ob Ihr alles bekommen habt.", completion = "Ich hoffe, dass ist das, wonach Keeshan gesucht hat. Im Moment kann ich jedenfalls nicht viel damit anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28182] = { id = 28182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenboxen", description = "Ner'gosh der Schatten ist der Anführer dieser Hexenmeister, die sich nördlich von uns befinden. Er ist der Fiesling, der mich aus meinem Haus vertrieben hat, als diese Schwarzfelsorcs aufgetaucht sind. Nun, eigentlich sind sie alle Fieslinge, aber er ist der fieseste.\n\nWenn ich jemals in die Nähe des Altars zurückkehren möchte, muss Ner'gosh verschwinden.", sourceObjective = "Tötet Ner'gosh den Schatten.", completion = "So wie ich diese Orcs kenne, wird bald ein anderer seinen Platz einnehmen. Ich werde versuchen, mich zurück in den Altar zu schleichen, bevor das passiert.\n\nHabt Dank, mein Bester.", sourceObjectiveStatus = "unverified-source-field" }
quests[28183] = { id = 28183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Keeshan", description = "Ich schätze, ich bin hier mit Euch fertig. Ich werde diese anderen Orcs davonscheuchen, sobald ich den Mut dazu gefunden habe.\n\nHier, vergesst Eure Vorräte nicht.", sourceObjective = "Bringt die Hexenmeisterausrüstung zurück zu John J. Keeshan am Flammensternposten in der Brennenden Steppe.", progress = "Sieht aus, als wärt Ihr mit Gorzeeki gut zurecht gekommen.", completion = "<Keeshan wirft einen Blick in die Kiste.>\n\nGut, gut, gut. Wir können weiter. Unser Krieg führt uns nach Osten, weg vom Schwarzfels... fürs Erste.", sourceObjectiveStatus = "unverified-source-field" }
quests[28184] = { id = 28184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meißelgriff, das Herz der Steppe", description = "Wir sind auf dem Weg nach Meißelgriff, das sich genau im Herzen dieser Steppe befindet. Wir treffen uns dort mit der Thoriumbruderschaft und außerdem mit Trottmann.\n\nSeid Ihr mit der Bruderschaft vertraut? Diese Dunkeleisenzwerge haben mir mehr als einmal geholfen. Wir brauchen ihre Hilfe vielleicht erneut.\n\nWir kommen auf unserem Weg dorthin durch den Schwarzzahnunterschlupf. Was haltet Ihr davon, wenn wir unterwegs ein paar Orcs töten? Ich werde in diesem Lager langsam ein wenig unruhig.", sourceObjective = "Tötet 15 beliebige Schwarzfelstruppen auf Eurem Weg nach Meißelgriff.", completion = "Ihr müsst mich entschuldigen, aber wir empfangen derzeit keine Besucher. Ich bitte Euch, Meißelgriff auf demselben Weg wieder zu verlassen, den Ihr gekommen seid.\n\nOh, Keeshan... Seid Ihr das?", sourceObjectiveStatus = "unverified-source-field" }
quests[28185] = { id = 28185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Svarnos", description = "Ihr habt bei der Eroberung der Insel ausgezeichnete Arbeit geleistet, {class}. Jetzt, wo wir die Insel in Besitz genommen haben, müssen wir diese Zellenblocks für Gefangene herrichten. Der D-Block erweist sich als besonders schwer zu säubern. Unglücklicherweise wird er von zahlreichen Dämonen und Ähnlichem heimgesucht.\n\nWir konnten die Dämonen etwas dezimieren, aber ein großer Kernhund hat sich aus seiner Zelle freigekämpft und richtet dort unten Chaos und Verwüstung an. Ihr müsst ihn töten und mir sein Halsband bringen.", sourceObjective = "Ihr müsst Svarnos im D-Block töten und mit seinem verfluchten Halsband zurückkehren. Svarnos hält sich im D-Block auf, direkt nordwestlich der Baradinfestung.", progress = "Ist der Kernhund tot?", completion = "Svarnos ist endlich tot? Sieht so aus, als ob wir uns zu guter Letzt an die Arbeit machen können, den Zellenblock herzurichten. Habt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28186] = { id = 28186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfluchte Fesseln", description = "Wart Ihr schon im D-Block, {name}? Jedes Mal wenn wir den verseuchten Zellenblock leerräumen, scheinen diese Dämonen ziemlich schnell zurückzukehren. Wir haben herausgefunden, dass sie sich mithilfe der verfluchten Fesseln regenerieren, die in dieser Gegend verstreut herumliegen. Und da kommt Ihr ins Spiel, {name}.\n\nIhr müsst so viele dieser Fesseln wie möglich einsammeln und zu mir bringen. Wir werden sie dann unverzüglich zerstören.", sourceObjective = "Ihr wurdet gebeten, 8 verfluchte Fesseln aus dem D-Block zu beschaffen, der direkt nordwestlich der Baradinfestung liegt.", progress = "Habt Ihr viele Fesseln gefunden? Den Berichten zufolge liegen sie dort überall verstreut herum.", completion = "Die Fesseln! Wir werden sofort mit der Zerstörungsprozedur dieser Fesseln beginnen, {name}. Habt Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28187] = { id = 28187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Um Haaresbreite!", description = "Also gut, {race}! Aus Spaß ist gerade Ernst geworden!\n\nJemand glaubt wohl, dass er mich so leicht loswerden kann, wie?\n\nDas werden wir ja sehen! Nichts kann diese Arbeit aufhalten! Nichts!\n\n<Schnottz sieht auf das Feuer, das sich überall ausbreitet.>\n\nWir sollten vermutlich von hier verschwinden.\n\nBeeilung! Keine Zeit verschwenden!", sourceObjective = "Sprecht mit Kommandant Schnottz, wenn Ihr bereit seid, ihn aus dem brennenden Gebäude zu geleiten.", completion = "In Zeiten wie diesen, stellt man fest, wer seine wahren Freunde sind...", sourceObjectiveStatus = "unverified-source-field" }
quests[28188] = { id = 28188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangenenaufstand", description = "Die Insel gehört uns. Jetzt müssen wir unsere Anlagen hier einsatzbereit machen. Wir haben einen aufgegebenen Zellenblock südwestlich von hier gefunden und wir müssen ihn auskundschaften, {name}.\n\nBerichten zufolge ist er voller Gefangener, die dort drinnen seit Jahren festsitzen. Tut, was immer ihr müsst, um den Ort zu säubern. Meldet Euch bei mir, wenn Ihr fertig seid.", sourceObjective = "Ihr wurdet beauftragt, 10 beliebige Gefangene im Loch zu töten, das südwestlich der Baradinfestung liegt.", completion = "Ihr habt das Gebiet gesäubert? Es sieht so aus, als ob Ihr Euch als nützlicher erweist, als wir dachten, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28189] = { id = 28189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Richtige tun", description = "Euch bietet sich ein entsetzlicher Anblick. Jemand hat alle Menschen bis zum Hals eingegraben, sodass sie aussehen wie eingepflanzt. Die Ghule, die anscheinend dieses Feld von menschlichen Keimlingen pflegen, springen in regelmäßigen Abständen zum nächstgelegenen Menschen und fressen seine Kopf!\n\nIhr könnt dies hier und jetzt beenden. Nehmt diese Schaufel und \"rettet\" die Menschen.\n\nTut das Richtige.", sourceObjective = "\"Rettet\" 15 menschliche Keimlinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[28190] = { id = 28190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der besudelte Schlamm", description = "Dies alles begann mit Winna Hazzard. Sie war eine Apothekerin der Verlassenen im Blutgiftposten, die Methoden erforschte, wie man den dämonischen Schlamm gegen die Allianz einsetzen könnte.\n\nWir haben sie davor gewarnt, sie würde zu weit gehen, aber sie wollte nicht hören. Und wir haben nicht schnell genug gehandelt. Jetzt sind sie und jeder andere im Blutgiftposten nichts weiter als hirnlose Schleimkreaturen...\n\nDie widerlichen Schlämme, die sie verwendet hat, streifen noch immer in der Nähe der Tümpel im Süden umher. Ich flehe Euch an, {class}, zerstört sie, sodass sie nicht weiterhin so viel Böses verbreiten können.", sourceObjective = "Vernichtet 8 besudelte Schlämme.", progress = "Schon allein der Gedanke an diese ekelerregenden Kreaturen macht mich krank! Urgh...", completion = "Mein Zorn wird durch diese Neuigkeiten gemildert... Vielleicht wird es mir jetzt leichter fallen, mich zu erholen und zu genesen.\n\nUnd vielleicht wird sich mein Magen ebenfalls beruhigen. Urgh...", sourceObjectiveStatus = "unverified-source-field" }
quests[28191] = { id = 28191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein passendes Ende", description = "Die Obsidianwyrmkin sind überall über die Landschaft südlich von uns verstreut. Sie sind nicht in der Lage, uns zurückzuschlagen, aber man kann nie wissen, welche neuen Gefahren die Schlacht mit sich bringt.\n\nIch will, dass Ihr die Wyrmkin angreift. Vernichtet sie, sodass wir damit fortfahren können, dieses Land von der verunreinigenden Anwesenheit des schwarzen Drachenschwarms zu befreien.", sourceObjective = "Tötet 10 Obsidianwyrmkin.", completion = "Ihr habt Euch als ein wichtiger Verbündeter erwiesen. Nach unserer ersten Begegnung hätte ich niemals damit gerechnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[28192] = { id = 28192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niemand kommt hier lebend heraus", description = "Dieser Hof ist abgeriegelt! Nichts und niemand kommt hier heraus! Wir analysieren noch immer die Lage und versuchen, herauszufinden, was genau geschehen ist. Aber meiner Theorie nach aßen die Arbeiter die Pilze und sind irgendwie zu abscheulichen, untoten Monstern mutiert. Ich meine, wie sonst könnte so etwas passiert sein? Dies ist nur ein Hof! Wir produzieren hier Pilze! Und Schlamm! Ja, Schlamm!\n\nSeht Euch um, {class}, denn jetzt wo Ihr hier seid, könnt Ihr nicht fort, bis diese Angelegenheit geklärt ist.\n\nSeht selbst!", sourceObjective = "Schätzt die Situation auf den Schlickfeldern ein.", completion = "Wie Ihr sehen könnt, sie sind alle zu Monstern geworden! Die meisten meiner Wachen starben und diejenigen, die es geschafft haben, zu entfliehen, verteidigen jetzt die Barrikaden, um zu verhindern, dass diese möglicherweise gefährlichen Kreaturen herauskommen.\n\nWir brauchen Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[28193] = { id = 28193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgeriegelt!", description = "Das Gebäude ist nicht von alleine explodiert!\n\nJemand hat versucht, mich abzumurksen und Ihr werdet nicht ruhen, bis ich herausgefunden habe wer!\n\nBleibt bei den Gästen. Mischt Euch unter sie, beobachtet ihr Verhalten und dann meldet Euch wieder bei mir.\n\nWenn sie irgendetwas wissen sollten, werde ich sie verhören lassen!\n\nWegtreten!", sourceObjective = "Kommandant Schnottz will, dass Ihr die Gäste in Schnottz' Landeplatz überwacht.", completion = "Sie wissen nichts, sagt Ihr?\n\nAlso gut. Die Suche geht weiter...", sourceObjectiveStatus = "unverified-source-field" }
quests[28194] = { id = 28194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die große Flucht", description = "Bitte, {class}! Wir brauchen Eure Hilfe!\n\nWir werden gegen unseren Willen in diesem Gebäude gefangen gehalten. Und da der Kommandant so schlecht gelaunt scheint, wissen wir nicht, was er uns antun wird.\n\nWenn Ihr uns ein paar Uniformen ergattern könntet, können wir uns davon schleichen.\n\nWir hätten niemals hierher kommen sollen. Das ist mir jetzt klar.\n\nWenn Ihr uns helft, zu fliehen, werde ich die WAHRHEIT über das aufschreiben, was hier passiert ist.\n\nDie Männer auf den Schiffen tragen alle die Kleidung, die wir benötigen.", sourceObjective = "Der produktive Schriftsteller in Schnottz' Landeplatz will, dass Ihr 6 frische Seemannsuniformen von Seemännern von Schnottz einsammelt.", progress = "Wart Ihr in der Lage, uns ein paar Uniformen zu besorgen, {race}?", completion = "Die sind perfekt, {class}.\n\nWünscht uns Glück!", sourceObjectiveStatus = "unverified-source-field" }
quests[28195] = { id = 28195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Botschaft senden", description = "Ich habe meine Augen und Ohren in jedem Winkel dieser Gegend, {race}.\n\nIch habe gehört, was unter meinen Truppen getuschelt wird. Ich war diesem erbärmlichen Verhalten gegenüber äußerst tolerant – bis jetzt!\n\nIch werde eine Botschaft an jeden in meinen Reihen senden. Zwietracht wird nicht länger geduldet! \n\nIhr sollt die Kapitäne auf den Schiffen in meiner Anlegestelle töten. Sie sind von der besonders entrüsteten Sorte.\n\nWenn das vollbracht ist, werde ich die Ohren weiter spitzen und entscheiden, was als Nächstes zu tun ist. \n\nWegtreten!", sourceObjective = "Kommandant Schnottz will, dass Ihr Kapitän Margun, Kapitän Cork und Kapitän Kronkh tötet.", completion = "Sehr gut, {race}...", sourceObjectiveStatus = "unverified-source-field" }
quests[28196] = { id = 28196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf um das Hügelland", description = "Das Tagebuch beschreibt die letzten 62 Tage aus Amtmann Horatio Weißross' Leben. Es enthält vernichtende Behauptungen gegen Aufseher Stillwasser und seine Taten auf den Schlickfeldern.\n\nIhr solltet es dem Aufseher zeigen. Er wird für das, was in diesem Tagebuch beschrieben steht, zweifellos eine Erklärung haben.", sourceObjective = "Bringt \"Kampf um das Hügelland\" zu Aufseher Stillwasser bei den Schlickfeldern im Vorgebirge des Hügellands.", progress = "Was ist das?", completion = "<Aufseher Stillwasser blättert durch das Tagebuch und liest leise.>\n\nGeschwafel eines Verrückten! Er hatte offensichtlich zu viele Pilze gegessen. Es ist gut, dass Ihr mir das gebracht habt, {name}. Ich werde es eigenhändig verbrennen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28197] = { id = 28197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diskretion ist der Schlüssel", description = "Wir müssen alle Beweise vernichten, {name}! Sagte ich Beweise? Ich meinte natürlich verrückte Untote! Auf jeden Fall ist Vorsicht die Mutter der Porzellankiste. Wir dürfen nicht zulassen, dass diese wilden Untoten aus den Schlickfeldern entkommen und niemand außerhalb dieser Anlage darf wissen, was hier geschehen ist!\n\nGenau südöstlich von hier liegt das, was mal der Pilzhof war. Dort findet Ihr einen wiederbelebten Feind namens Bürger Wilkes mit seinem Kollegen Amtmann Horatio Weißross. Sie haben meinen Wachen einige Probleme bereitet. Findet sie und tötet sie!", sourceObjective = "Tötet Bürger Wilkes und Amtmann Horatio Weißross.", completion = "Gut gemacht! Wilkes wurde gehängt, nachdem wir herausgefunden haben, dass er massenhaft von diesen Pilzen und andere hochgiftige Substanzen zu sich genommen hat. Nach seinem Tod wurde er als untoter Geist wiedergeboren. Viele meiner Wachen fielen Wilkes zum Opfer, bevor er davonrannte und sich versteckte. Wir fürchten, dass so etwas noch einmal passieren könnte und verbrannten deshalb den Amtmann, bis nur noch Knochen von ihm übrig waren!\n\nWarum sie freiwillig, giftige Substanzen zu sich genommen haben? Ich habe keine Ahnung! Dies ist ein gewöhnlicher Hof, mein Herr, nichts weiter!", sourceObjectiveStatus = "unverified-source-field" }
quests[28198] = { id = 28198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das schwächste Glied", description = "Man sagt, eine Kette sei immer so stark wie das schwächste Glied.\n\nIch unterschreibe diese Theorie und baue sie sogar noch weiter aus.\n\nAnstatt das schwächste Glied zu entfernen, muss man es... stärken. \n\nDie anderen Glieder werden ihre Leistungen aus Angst erhöhen, dass sie selbst das schwächste Glied werden.\n\nIm Falle meiner Armee, hat unser schwächstes Glied einen Namen. Salhet.\n\nIhr findet ihn beim Üben am Fuße dieser Stufen.\n\nFangt bei ihm mit etwas Leichtem an. Die Hyänen auf den Hügeln im Westen vielleicht.", sourceObjective = "Sprecht mit Salhet am Außenposten der Legion von Ramkahen in Uldum.", completion = "Es ist eine große Ehre, Euch kennen zu lernen, {name}! Ich habe viel von Euch gehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[28199] = { id = 28199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Wissenschaft!", description = "Proben... jaaa... brauche Proben! Diese, öhm, Experimente... Ich meine, diese unglücklichen Arbeiter müssen untersucht werden.\n\nReist nach Südosten zum ersten Hof und tötet die auferstandenen Ghule. Ihr müsst aus ihren verfaulten Körpern Fleischproben entnehmen. Bringt diese zu mir!\n\n<Arnauld reibt sich die Hände und lacht wie wahnsinnig - ohne erkennbaren Grund.>\n\nMuss forschen!", sourceObjective = "Beschafft 6 Fleischproben.", progress = "Für die Wissenschaft!", completion = "Diese Proben werden uns ein besseres Verständnis dieser hirnlosen Untoten geben. Nehmt diese Münzen als Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[28200] = { id = 28200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versorgungslücke", description = "Ihr habt sicher bemerkt, dass wir für eine Schlacht eher leidlich gerüstet sind. \n\nDie Stämme der Tol'vir standen Jahrtausende lang vor keiner Auseinandersetzung dieses Ausmaßes.\n\nSämtliche Kampfprotokolle, welche die Titanen unseren Vorfahren einprogrammierten, sind aber noch vorhanden. Manche sind Teil unserer Instinkte, andere werden als Tradition weitergegeben.\n\nAber das alles kann eine Versorgungslücke nicht ausgleichen. Wir brauchen Waffen. Wir brauchen Rüstungen.\n\nDie besten Rüstungen sind mit dem Leder der Flusskrokilisken aus dieser Gegend gefüttert. Helft uns, ein paar zu sammeln.", sourceObjective = "Sammelt 20 gehärtete Krokiliskenbälge.", progress = "Es freut mich, zu sehen, dass Ihr Euch nicht über diese Art von Aufgabe erhaben fühlt.", completion = "Gute Arbeit, {name}. Ihr glaubt vielleicht nicht, dass dies sonderlich nützlich ist, aber es kann für einen unserer Soldaten durchaus den Unterschied zwischen Leben und Tod ausmachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28201] = { id = 28201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pflugscharen zu Schwertern", description = "Wir haben eine beachtliche Armee, aber ich befürchte, dass das herannahende Kräftemessen mit den Tol'vir der Neferset es erforderlich macht, alle Tol'vir von Ramkahen und Orsis in den Kampf mit einzubinden.\n\nIch will, dass Ihr an der Spitze unserer Rekrutierungsbemühungen steht.\n\nBegebt Euch über den Fluss zu den Feldern von Akhenet und rekrutiert die Arbeiter, die dort ihrem Tagewerk nachgehen.", sourceObjective = "Rekrutiert 8 Arbeiter von Ramkahen.", completion = "Ihr seid ein geborener Anführer, {name}. Es wäre gut, Euch an unserer Seite zu wissen, wenn der Krieg diese Länder erreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28202] = { id = 28202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein perfektes Kostüm", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als einen Orc verkleiden. Ihre Armee besteht hauptsächlich aus Orcs, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.", sourceObjective = "Bringt die angemessene Menge an Gegenständen vom Schneidertisch zu Thelaron Düsternadel in Meißelgriff.", completion = "Das soll sie sein? Das ist Eure Verkleidung?\n\nIch habe das Gefühl, dass unsere Chancen rapide sinken. Es war schön, Euch kennengelernt zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28203] = { id = 28203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein perfektes Kostüm", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als Oger verkleiden. Die Oger der Feuermägen haben immer für die Schwarzfelsorcs gearbeitet, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.", sourceObjective = "Bringt die angemessene Menge an Gegenständen vom Schneidertisch zu Thelaron Düsternadel in Meißelgriff.", completion = "Das soll sie sein? Das ist Eure Verkleidung?\n\nIch habe das Gefühl, dass unsere Chancen rapide sinken. Es war schön, Euch kennengelernt zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28204] = { id = 28204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein perfektes Kostüm", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als Goblin verkleiden. Die Schwarzfelsorcs haben schon immer goblinische Söldner angeheuert, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.", sourceObjective = "Bringt die angemessene Menge an Gegenständen vom Schneidertisch zu Thelaron Düsternadel in Meißelgriff.", completion = "Das soll sie sein? Das ist Eure Verkleidung?\n\nIch habe das Gefühl, dass unsere Chancen rapide sinken. Es war schön, Euch kennengelernt zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28205] = { id = 28205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein perfektes Kostüm", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als Troll verkleiden. Die Gluthauertrolle haben stets mit den Schwarzfelsorcs zusammengearbeitet, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.", sourceObjective = "Bringt die angemessene Menge an Gegenständen vom Schneidertisch zu Thelaron Düsternadel in Meißelgriff.", completion = "Das soll sie sein? Das ist Eure Verkleidung?\n\nIch habe das Gefühl, dass unsere Chancen rapide sinken. Es war schön, Euch kennengelernt zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28206] = { id = 28206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schönling auf Abwegen", description = "Es war erst gestern, dass ich ihn losschickte, um den Bauernhof östlich von hier zu untersuchen, aber es fühlt sich an wie eine Ewigkeit!\n\nWahre Perfektion. Wie seine blonden Locken sein makelloses Elfengesicht umrahmen... Und erst diese Stärke. Ich wollte ihn gar nicht gehen lassen, aber er hat darauf bestanden! Und wie könnte ich ihm einen Wunsch abschlagen, wenn er mich mit seinen strahlenden Augen ansieht...\n\nAber jetzt ist Johnny Imba nicht zurückgekehrt! Ich befürchte das Schlimmste, {name}. Findet ihn!", sourceObjective = "Findet Johnny Imba in den Schlickfeldern im Vorgebirge des Hügellands.", completion = "<Johnny schluchzt laut.>\n\nGl... Glitzer!!! Di... Er hat sie getötet!\n\n<Johnny heult weiter.>", sourceObjectiveStatus = "unverified-source-field" }
quests[28207] = { id = 28207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schleimige Angelegenheit", description = "Dieser arme Tauren hier ist bei der Flucht aus dem Blutgiftposten nur knapp mit dem Leben davon gekommen! Wenn wir verhindern wollen, dass er sich, wie all die anderen, in eine Schleimkreatur verwandelt, werden wir die Infektion behandeln müssen.\n\nIn der Nähe der hellen, grünen Gewässer in dieser Gegend wachsen viele Pilze. Zum Beispiel am Teich im Osten, zwischen den Wasserfällen. Die meisten von ihnen sind zu nichts zu gebrauchen... Aber die hellgrün leuchtenden müsst Ihr für mich sammeln!\n\nAus ihnen kann ich etwas Schmackhaftes zubereiten, das dem Armen hilft. Lasst Euch nicht zu viel Zeit!", sourceObjective = "Sammelt 7 smaragdgrüne Schimmerkappen.", progress = "Denkt daran, die hellgrün leuchtenden Pilze!", completion = "Die meisten Leute denken, dass das grüne Leuchten auf dämonische Verderbnis hinweist... aber wenn man ein Auge für Farben und Schattierungen hat, dann kann man sehen, dass dies die Energien des Smaragdgrünen Traums sind! Diese kleinen Pilze werden nicht durch die Gewässer verdorben, sondern sie tun ihr Bestes, um sie zu läutern!\n\nJetzt pürieren wir sie und machen einen leckeren Brei für den Herrn Tauren. Wenn er die gegessen hat, wird er sich besser fühlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28208] = { id = 28208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winnas Kätzchen", description = "Herr Tauren hat mir viel darüber berichet, was am Blutgiftposten geschehen ist. Er sagte Winna Hazzard ist noch immer dort!\n\nSie ist nicht mehr zu retten, aber was von ihr übrig ist, produziert reichlich neuen Schleim. Wir müssen ihn aufhalten!\n\nGlücklicherweise habe ich einen Plan. Herr Tauren sagte, Winna hätte früher ein Kätzchen gehabt. Sie hat ihm verdorbenes Schleimwasser zu trinken gegeben. Daraufhin ist es in die Wälder gelaufen. Ich sah im Südwesten hinter dem Blutgiftturm etwas herumschleichen, aber es war größer als ein Kätzchen! Seht mal nach, ob das Miezekätzchen eine Ohrmarke trägt...", sourceObjective = "Beschafft Miezis Ohrmarke von Winnas Kätzchen.", progress = "Habt Ihr das Kätzchen gefunden?", completion = "Armes kleines Miezekätzchen, leidet schon so lange dort draußen in den Wäldern! Ihr habt dem armen Ding etwas Gutes getan, {name}. Und auch all den Reisenden, die es noch gefressen hätte.\n\nDiese Ohrmarke wird sich als nützlich erweisen...", sourceObjectiveStatus = "unverified-source-field" }
quests[28209] = { id = 28209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit für Lydon", description = "Das hier ist kein Hof! Stillwasser hat an den Menschen vom Hügellandhof Experimente durchgeführt. Diese Monstrositäten hier sind alles seine Schöpfungen.\n\nDas ist nicht das Schlimmste daran, {class}. Diese Entartungen, die den Schlüssel zu meinen Käfig haben, sind ehemalige Verlassene. Stillwassers Experimente haben die Nebenwirkung, Verlassene in hirnlose Zombies zu verwandeln. Warum glaubt Ihr, dass er so viel Angst davor hat, dass dies hier herauskommt? Er weiß, dass so ein Verbrechen mit dem endgültigen Tod bestraft wird.\n\nHolt mich hier raus! Die infizierten Schlickwachen dort draußen haben den Schlüssel!", sourceObjective = "Findet Lydons Käfigschlüssel.", progress = "Findet den Schlüssel!", completion = "<Lydon nimmt Euch den Schlüssel ab.>\n\nIch lasse mich selbst raus, danke.\n\nIch war noch nie so wütend! Stillwasser kommt damit nicht davon. Ich werde seinen Kopf persönlich der Bansheekönigin präsentieren.\n\nWir beide arbeiten zusammen, {name}.\n\nIch weiß ja nicht, was den Burschen da angeht, aber am liebsten wäre mir, wenn er zurückbleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28210] = { id = 28210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Form bringen", description = "Hochkommandant Kamses hat eine spezielle Aufgabe für mich?\n\nWartet... sagt es mir nicht. Es sind wieder die Hyänen, richtig?\n\nNun gut, ich werde mein Bestes geben.\n\nTrefft mich am Sonnenbehütergrat.\n\nIch werde Euch nicht enttäuschen.", sourceObjective = "Helft Salhet dabei, 8 Murrbluthyänen zu töten.", progress = "Wie viele haben wir?", completion = "Nun... Das war nicht so richtig gut, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[28211] = { id = 28211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Elementarflammen gehärtet", description = "Das Wichtigste zuerst: Wir werden Munition brauchen. Munition, die stark genug ist, die Panzerhaut eines Schwarzdrachen zu durchschlagen. \n\nWestlich von Donnermar ist eine Stadt des Wildhammerklans, die von unbändigen Feuerelementaren überrannt wurde. Jede Waffe, die in dem Großbrand zurückgelassen wurde, wird in den Elementarflammen gehärtet worden sein. Es ist jetzt härter als alles, was ich in dieser Schmiede auf die Schnelle herstellen könnte!\n\nBringt mir Speere aus der Humboldtfeuersbrunst, {name}. Je spitzer desto besser.", sourceObjective = "Sammelt 8 gehärtete Speere.", progress = "Speere, ja? Meine Schnellfeuerspeerharpune wäre ohne sie nutzlos.", completion = "Seht Euch das an – AUTSCH! Spitz! Heiß!\n\nDiese Speere sollten durch den Drachenpanzer schneiden wie ein elektrischer Käsehobel durch warme Butter.", sourceObjectiveStatus = "unverified-source-field" }
quests[28212] = { id = 28212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heißes Zeug", description = "Ich habe einen Plan, wie wir das empfohlene Drehmoment für eine Speerharpune dieser Größe vervierfachen könnten, aber meinen Berechnungen zufolge würde das Abfeuern dieser Waffe das Gehäuse zerspringen lassen. Und eventuell noch den Planeten in zwei Teile spalten.\n\nIch kann ein Gehäuse zusammenschweißen, das hundertmal stärker ist, wenn ich eine zuverlässige Quelle reiner Elementarflammen für die Verhüttung hätte.\n\nUngebundene Glutbiesten wüten in der Gegend westlich von hier in der Humboldtfeuersbrunst. Wenn man sie tötet, sollten sie auf die Größe von Kügelchen glühenden Zorns schmelzen. Bringt mir ein paar!", sourceObjective = "Sammelt 5 Kügelchen glühenden Zorn.", progress = "Habt Ihr den glühenden Zorn? Nein, nein, gebt sie mir nicht in die Hand. Hier, verwendet die Zangen!", completion = "Wunderbar! Ich werde dieses Erz zu einer köstlichen Suppe verschmelzen. Eine glühende Suppe. Aus flüssigem Metall.", sourceObjectiveStatus = "unverified-source-field" }
quests[28213] = { id = 28213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giftmüllbeseitigung", description = "Winna ist in die Quelle des Schleims am hinteren Ende des Blutgiftpostens im Westen eingeklinkt. Sie sorgt dafür, dass der Schleim weiter fließt und der Brunnen sorgt für ihren Schutz! Aber wenn Ihr ihre Aufmerksamkeit erregen könnt...\n\nNehmt die Ohrmarke und zeigt sie Winna. Wenn nur ein kleines bisschen von der alten Winna in ihr übrig ist, kommt es vielleicht zum Vorschein. Vielleicht wird ihr Bedauern für ihre arme, verlorene Miezi Oberhand gewinnen, vielleicht wird sie noch einmal Mitleid haben und sie wird vielleicht aus dem Schleim herauskommen!\n\nUnd dann könnt Ihr sie vielleicht töten und den Schleim aufhalten. Juhu!", sourceObjective = "Verwendet Miezis Ohrmarke, um Winna Hazzards Aufmerksamkeit zu erregen und dann vernichtet sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[28214] = { id = 28214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Blutgiftposten säubern", description = "Hurg...\n\nKönntet Ihr... uh... Könntet Ihr bitte... HUÄRG!\n\nEntschuldigt, mir ist ein wenig... uh, mein Magen. Wenn Ihr Euch zum Blutgiftposten im Westen begebt, könntet Ihr bitte HUURG...\n\nBe... Befreit einfach das, was von meinen Freunden übrig ist, von ihrem Elend. Und geht JETZT. In Eurem eigenen Interesse. Uuuuurg...", sourceObjective = "Tötet 6 Schleimsklaven des Blutgiftpostens.", completion = "Habt Dank, {class}. Ich fühle mich viel besser und es ist gut, dass diese Monstrositäten fort sind.\n\nIhr solltet Euch vielleicht trotzdem ein wenig von mir fernhalten. Sicherheitshalber...", sourceObjectiveStatus = "unverified-source-field" }
quests[28215] = { id = 28215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Potentielle Energie", description = "Wie Ihr wisst, ist die Menge an Energie, die in einer herkömmlichen Feder gespeichert ist, gleich der Hälfte der Elastizität der Feder multipliziert mit der Weggröße im Quadrat. Es sei denn, man verwendet eine Elementiumfeder. Dann werden die Zahlen irrsinnig groß! Mathematisch gesehen grotesk! \n\nIch brauche ein paar Elementiumkreise für meine Geheimwaffe und wie es nun mal so ist: Die Schattenhammerkultisten verwenden Spulen wie diese, um die Erdelementare zu binden.\n\nFindet sie an den Obsidiansteinsklaven östlich von hier in der schrecklichen Region, die Schwarzer Riss genannt wird.", sourceObjective = "Sammelt 10 gewundene Spulen aus Elementium.", progress = "Wenn Ihr jetzt haufenweise Elementiumspulen aus Eurem Rucksack zieht, dann macht Ihr mich zu einem sehr glücklichen Gnom!", completion = "Ausgezeichnet! Diese Schätzchen werden sich mit der Kraft von tausend Sonnen entspannen!\n\nDas ist natürlich nur eine grobe Schätzung. Macht mich ja nicht für diese Zahlen verantwortlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[28216] = { id = 28216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magmalord Falthazar", description = "Ich habe gerade die schlimmen Nachrichten aus dem Westen gehört. Wir haben Humboldts Siedlung verloren. Sie wurde einfach von einer Feuerwand von dieser Welt getilgt!\n\nSchuld daran ist der Schattenhammer. Die Überlebenden sagen, es wäre das Werk eines gewissen Magmalord Falthazar. Er ist einer der Aszendenten. So nennen sie den höchsten Rang unter den Schattenhammerkultisten, die eins mit den Elementen werden. Er ist ein Wesen aus reinem Feuer.\n\nUnd bald wird er ein Wesen aus reinem Tod sein! Tötet Falthazar bei der Humboldtfeuersbrunst und bringt mir seinen Kopf!", sourceObjective = "Sammelt den Kopf von Magmalord Falthazar.", progress = "All die Jahre dachte der alte Humboldt, Stopfwampes Oger auf dem Gebirgskamm wären sein größtes Problem. Doch dann kam der Schattenhammer.\n\nIn nur einem Wimpernschlag setzten sie das ganze Tal in Flammen, als wäre es eine Geburtstagstorte. Herzlos.", completion = "Jep, genau das ist er. Kaum vorzustellen, dass das hier einmal ein Mensch war.\n\nDa seht Ihr das wahre Gesicht des Schattenhammers. Was sie nicht vernichten, verderben sie.\n\nVielen Dank, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28217] = { id = 28217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesucht: Der Dämonenjäger", description = "Seit der Jadefeuerbach von den Dämonen zurückerobert wurde hat der Smaragdkreis viele Druiden geschickt, um die langwierige Läuterung der Ruinen zu beginnen. Letzte Nacht wurden gleich mehrere von ihnen ermordet... von einem Nachtelf!\n\nZeugen berichten, dass der Täter ein Dämonenjäger war, einer von Illidans geisteskranken Schülern. So etwas sieht man nicht alle Tage. Ohne Zweifel hat die Macht ihn wahnsinnig gemacht, genau wie seinen Meister.\n\nIch bezahle gutes Geld für einen Beweis dafür, dass dieser Mörder tot ist. Man hat ihn zuletzt abseits der Straße im Norden in einem Tal unter dem Jadefeuerbach gesehen.", sourceObjective = "Tötet Feronas Sündschwelger.", progress = "Haben sie jemand anderen geschickt?", completion = "Wie edel von Euch... einfach ohne zu fragen auf eine Mordmission zu gehen und meinen Kopf zu verlangen, nur weil ein anderer Euch darum bittet.\n\nZügelt Euren Zorn und hört Euch zuerst meine Geschichte an. Ihr werdet sehen, was edles Unwissen diesem Land angetan hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[28218] = { id = 28218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schicksal voll Feuer und Leid", description = "Meinesgleichen wurde schon immer für das gehasst, was wir tun... Verabscheute Ausgestoßenene, denen eine nicht mehr heilbare Verderbtheit vorgeworfen wurde.\n\nDoch es ist der Verdienst eines Dämonenjägers, dass diese Wälder hier nicht die größte Bastion der Brennenden Legion in Azeroth sind. Ich spreche von meinem Meister Illidan Sturmgrimm, dem \"Verräter\".\n\nSeht selbst. Seht, was hier geschehen ist, als Illidan befreit wurde und die dämonischen Mächte des Schreckenslords Tichondrius ohne Gegenwehr über diesen Wald herrschten...", sourceObjective = "Nehmt an Illidans Schlacht gegen Arthas teil.", completion = "Und so machte sich mein Meister auf, um den Schädel zu suchen... Er riskierte erneut sein Leben im Kampf gegen eine Armee von Dämonen, um den Quell der Verderbnis des Teufelswalds zu finden. Stellt Euch nur vor, er hätte es nicht getan! Stellt Euch vor, wie es hier aussehen würde, wenn der Schädel von Gul'dan sein Werk ungehindert fortgesetzt hätte...", sourceObjectiveStatus = "unverified-source-field" }
quests[28219] = { id = 28219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brummer fürs Baby", description = "<Der winzige Setzling breitet seine Blätter weit aus, wie ein Jungvogel, der gefüttert werden möchte. Er spricht mit sehr leiser Stimme:>\n\nHunger... will... Käfer...\n\n<Ihr könnt aus dem Süden das Summen von Wespen hören. Ob die sind, was der Kleine fressen möchte?>", sourceObjective = "Tötet 10 Eisenholzbrummer, um den Beschützersetzling zu füttern.", completion = "<Der Setzling reibt sich mit einem wurzeligen Arm den Stängel, als wäre er satt. Er scheint auch ein wenig gewachsen zu sein!>", sourceObjectiveStatus = "unverified-source-field" }
quests[28220] = { id = 28220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bodensuche", description = "<Der winzige Setzling tapst herum und lenkt eure Aufmerksamkeit nach Süden. Ihr könnt gerade so eine leise Stimme hören.>\n\nBoden...<Offenbar möchte er frischen Erdboden. Vielleicht solltet ihr ihn zu einem der Flecken begleiten, die am fruchtbarsten aussehen.>", sourceObjective = "Bringt den Beschützersetzling zu 7 Flecken fruchtbaren Bodens.", completion = "<Der Setzling kräuselt seine Wurzeln, offenbar entzückt.>\n\nWachsen... groß...", sourceObjectiveStatus = "unverified-source-field" }
quests[28221] = { id = 28221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wurzeln, wie zum Stampfen gewachsen", description = "Es gibt hier noch so viele andere Geister, die in verrottenden Körpern gefangen sind...\n\nSeht Ihr? Die Donnerstampfer der Eisenstämme im Norden. Die sind vor Dämonenzeug ganz krank und mit Pilzschlabber bewachsen. Die armen Geister in ihnen können nicht entkommen.\n\nIhr könnt helfen! Fällt sie und die Geister können raus. Ich stecke mir die Geister ein und wir können alle Freunde sein, wenn ich groß bin. Helft Ihr ihnen? Bitte?", sourceObjective = "Tötet 10 Donnerstampfer der Eisenstämme.", completion = "So glücklich! Könnt Ihr uns hören? Wir sind jetzt so viele Freunde.\n\nImmer größer und größer, mit Platz für alle Freunde...", sourceObjectiveStatus = "unverified-source-field" }
quests[28222] = { id = 28222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wochenend und Sonnenschein", description = "Wir wachsen immer großer... Zeit, dass wir strahlen! Zeit, unsere Blätter der Sonne entgegenzurecken!\n\nBringt mich zur Sonne! Die Sonne ist weit weg, aber ihre Strahlen kommen zu uns. Ihr Licht macht uns wieder groß und stark. Das Licht kommt die großen Äste hinunter zu den kleinen, wie unseren.\n\nDa drüben! Die Sonne kommt im Norden zu uns! Nehmt uns mit, nehmt uns zum Tanz!", sourceObjective = "Begleitet den Beschützersetzling zu 5 Sonnenstrahlen im Eisenwald.", completion = "So warm und frisch und voller Leben. Wir lieben die Sonne, sie macht uns stärker.\n\nBald nun, bald, ist die Zeit zum Wachsen...", sourceObjectiveStatus = "unverified-source-field" }
quests[28223] = { id = 28223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wärter", description = "Wir haben es fast geschafft, die aufständischen Gefangenen im Loch zu beseitigen, doch ein Problem bleibt: Der Wärter.\n\nWärter Silva ist ihr Meister. Für ihn tun sie alles. Wenn wir ihn ausschalten, schalten wir alle aus. Tötet ihn und bringt mir seine Schlüssel. Mit den Schlüsseln können wir den Zellenblock weiter erkunden und hoffentlich auch zur Wasserversorgung der Insel vordringen.", sourceObjective = "Tötet Wärter Silva im Loch und kehrt mit seinen Schlüsseln zurück. Das Loch ist südwestlich der Baradinfestung.", progress = "Ist der Wärter endlich tot?", completion = "Aah, die Schlüssel des Wärters. Wieder einmal habt Ihr gute Arbeit geleistet, {name}. Diese Schlüssel werden sich noch als nützlich erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28224] = { id = 28224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Beschützer", description = "Ahhh... ich danke Euch, <kleiner/kleine:r> {race}. Ich und andere haben schon so oft versucht, in diesem Wald zu wachsen, waren jedoch nie erfolgreich.\n\nDer siechende Beschützer, der im Norden sein Unwesen treibt, ist das einzige Urtum, der es seit der Verseuchung dieses Waldes zur Reife geschafft hat, aber sein Körper ist krank und sein Geist verrückt. So wie wir die Geister der Treants gerettet haben, möchte ich auch die Geister retten, die in ihm wohnen, anstatt sie ihrem Schicksal zu überlassen.\n\nBesiegt ihn und lasst seine Geister sich mir anschließen, bevor ich Wurzeln schlage.", sourceObjective = "Besiegt den siechenden Beschützer.", completion = "Ja... die Zeit ist gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28225] = { id = 28225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweist Eure Loyalität", description = "Ihr könnt gern für 'ne Weile hier in Meißelgriff bleiben, aber ich muss wissen, ob Ihr ein Freund seid.\n\nWir von der Thoriumbruderschaft sind nich' die einzigen Dunkeleisenzwerge hier in der Steppe. Ganz im Gegenteil. Wir sind ziemlich deutlich in der Unterzahl gegenüber den Dunkeleisenzwergen vom Schwarzfels. Unser Stützpunkt hier in Meißelgriff ist ausreichend sicher, aber sie stören uns noch immer aus den nahegelegenen Ruinen von Thaurissan im Norden.\n\nStellt Euch uns unter Beweis, {race}. Tötet sie für mich.", sourceObjective = "Tötet 10 Dunkeleisenzwerge in den Ruinen von Thaurissan.", completion = "Na, so was sieht man doch gern! Ihr seid in Ordnung, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28226] = { id = 28226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschrottete Golems", description = "Wir halten hier Wächtergolems. Die Zwerge nördlich von hier halten auch Golems, aber ich weiß nicht genau, warum.\n\nFürs Töten in erster Linie, denke ich zumindest.\n\nWir könnten Ersatzteile für unsere Golems brauchen, und ich habe auch schon einen Plan, wie wir sie bekommen können: Tötet deren Golems und sucht nach Teilen, die auf den Boden gefallen sind. Plündert alles, was nützlich ist. Ihr werdet nicht alles tragen können, also wählt die Teile mit Bedacht.", sourceObjective = "Tötet Kriegshäscher in den Ruinen von Thaurissan und sucht dann nach 3 Obsidiankolben, 3 Fluxausstoßsieben, 3 Thoriumgetriebewellen und nach einem steinernen Kraftkern unter den Kriegshäscherteilen, die zu Boden fallen.", progress = "Wir haben diese Golems selbst gebaut, wisst Ihr. Ein wenig mechanisches Handwerk, ein wenig elementares Handwerk... das Resultat ist gar nich' mal so schlecht, wenn Ihr mich fragt.", completion = "Das ist genau das, was wir brauchten. Ich lass die Jungs gleich mit der Arbeit am nächsten Schwung Golems anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28227] = { id = 28227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golemausbildung", description = "Ihr erweist Euch als ziemlich hilfreich, {race}. Ich hab' mir gedacht, Ihr könntet bei einer letzten Sache helfen.\n\nUnsere Wächter sind stark, aber nich' so stark, wie Ihr. Ich hab' mir gedacht, Ihr könntet, wenn Ihr nichts dagegen habt, ein paar unserer Golems bei ihrem Training helfen? Sprecht einfach einen an und kämpft ein paar mal mit ihm. Hoffentlich lernen sie was von Euren Kampfkünsten und werden besser.", sourceObjective = "Helft 4 gemeißelten Golems bei ihrer Kampfausbildung.", completion = "Ihr seid ein Lebensretter, {name}. Mit Golems wie diesen werden wir von den Dunkeleisenzwergen, den Schwarzfelsorcs... sogar von den Drachen nichts zu befürchten haben müssen!\n\nWenn Ihr jemals etwas von der Thoriumbruderschaft benötigen solltet, zögert nicht, uns zu fragen. Das gilt auch für Eure Freunde.", sourceObjectiveStatus = "unverified-source-field" }
quests[28228] = { id = 28228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in den Wald", description = "Es ist jetzt Zeit, Lebewohl zu sagen. Ihr habt mich von Setzlingswurzeln an begleitet, und so kurz die Zeit auch war, muss ich mich jetzt wieder dem Wald anschließen.\n\nBringt mich zurück auf den Hügel, auf dem Ihr mich gefunden habt. Dort werde ich meine Wurzeln schlagen und im Schatten der Urtume wachsen, die vor mir kamen.", sourceObjective = "Bringt den erblühenden Beschützer zurück zu dem Hügel in der Mitte des Eisenwaldes.", sourceObjectiveStatus = "unverified-source-field" }
quests[28229] = { id = 28229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veranlagung und Umwelt", description = "Die Urtumbeschützer des Eisenwalds im Norden sind schon seit Jahren tot und ihre leblosen Hüllen sind ein Mahnmal für den Schaden, der diesem Land zugefügt worden ist.\n\nVier Mal im Jahr tragen wir Wasser von diesem Mondbrunnen zu ihnen und bewässern den Boden dort - in der Hoffnung, dass daraus neues Leben entspringen wird. Wenn Ihr möchtet, könnt Ihr das Wasser selbst dorthin bringen.\n\nEs ist eine ausgezeichnete Gelegenheit, in sich zu gehen. Nehmt diese Phiole und füllt sie am Mondbrunnen, gießt sie dann auf der Spitze des kleinen Hügels zwischen den drei Urtumen aus.", sourceObjective = "Füllt die Phiole am Mondbrunnen im Wisperwindhain und gießt sie auf dem Boden zwischen den toten Urtumbeschützern im Eisenwald aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[28230] = { id = 28230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notfallregelung", description = "Bevor der Aufseher sein Fett weg kriegt, müssen wir uns um diesen Ausbruch kümmern. Wir können es nicht riskieren, diesen Erreger auf die Welt loszulassen.\n\nIm Arbeiterquartier direkt nördlich von hier treibt sich eine Monstrosität herum, die von Stillwasser aus drei Bauern zusammengeflickt wurde. Dieses Ungeheuer muss zerstört werden, wenn wir die Schlickfelder sichern wollen. Die Notfallregelungen verlangen es so.", sourceObjective = "Tötet die Ray-Getz-Kalaba-Monstrosität.", completion = "Sobald wir uns um die restlichen Untoten gekümmert haben, ziehen wir Stillwasser zur Rechenschaft!", sourceObjectiveStatus = "unverified-source-field" }
quests[28231] = { id = 28231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Glitzer", description = "Aufseher Stillwasser hat mich ins Feld geschickt, um diesen Ausbruch zu untersuchen. Als ich hier ankam, sind Glitzer und ich von dieser schwerfälligen Monstrosität namens Verringtan angegriffen worden. Ich fiel von Glitzers Rücken und rannte sofort um mein Leben. Glitzer hielt aber die Stellung und hielt das Biest auf. Leider wurde sie aber überwältigt und anschließend in den Boden gepflanzt, als wäre sie so eine Art glorreicher Sternenponysetzling.\n\nSie hat ihr Leben gegeben, um mich zu beschützen. Ich will Rache! Wenn Ihr es für nichts anderes tun wollt, dann tut es für Glitzer!", sourceObjective = "Tötet den Schmied Verringtan.", completion = "Sie kommt jetzt in den großen Pferdehimmel in den Sternen. Wir werden dich niemals vergessen, Glitzer. NIEMALS!", sourceObjectiveStatus = "unverified-source-field" }
quests[28232] = { id = 28232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essen von unten", description = "Uns gehen die Vorräte im Lager aus, {name}. Wir haben vor Kurzem von einem Zellenblock südwestlich von hier gehört, in dem nach jahrelangem Betrieb noch Rationen übrig sind. Wir brauchen so viele Rationen wie ihr tragen könnt hier im Lager.\n\nOh, und noch etwas: in dem Zellenblock wimmelt es von Gefangenen, also seid vorsichtig.", sourceObjective = "Ihr wurdet gebeten, 12 Rationen aus dem Zellenblock aus dem Loch südwestlich der Baradinfestung zu besorgen.", progress = "Konntet Ihr die Rationen ausfindig machen? Berichten zufolge kann man sie über den ganzen Ort verteilt finden.", completion = "Die Rationen werden unseren Truppen sehr helfen, {name}. Vielen Dank für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28233] = { id = 28233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Bruder", description = "Mein Bruder Bahrum ist verschwunden!\n\nEr war einer der ersten, die die Gegend ausgekundschaftet haben. Alle anderen sind zurückgekehrt, aber von ihm fehlt jegliche Spur. Papa meint, dass er nur irgendwo herumschlawenzelt, aber er ist mein einziger Bruder, und ich habe meiner Mutter versprochen, auf ihn aufzupassen. Könnt Ihr ihn finden?", sourceObjective = "Findet Bahrum Schmiedehammer.", completion = "He, nicht schauen! Ich hab keine Hosen an!", sourceObjectiveStatus = "unverified-source-field" }
quests[28234] = { id = 28234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine Hosen!", description = "Warum ich in der Kornkiste stehe? Mh, um es zusammenzufassen, da waren Hornissen und Anhänger des Drachenmalklans, die zu einem recht ungünstigen Zeitpunkt aufgeschlagen sind. Ich konnte mich in Sicherheit bringen, aber meine Beinschützer haben die Bastarde an sich genommen! Meine Schwester hat sie selbst für mich angefertigt und sogar meinen Namen eingearbeitet... Ich würde sterben vor Scham, wenn sie rausfindet, dass ich sie verloren habe.\n\nBitte, findet sie für mich. Ich habe gesehen, wie der Hosendieb in die Festung dort drüben gegangen ist. Ich werde mich hier weiterhin *räusper* bedeckt halten. Und fragt einen Wildhammer nie, was er unter seinem Kilt trägt!", sourceObjective = "Findet Bahrums Beinschützer.", progress = "Habt Ihr sie gefunden? Das Korn kratzt ganz schön.", completion = "Vielen Dank! Und jetzt dreht Euch um, damit ich sie anziehen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[28235] = { id = 28235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uferbach muss sterben", description = "Magistrat Uferbach war einst der Bürgermeister dieser Gegend. Zu Lebzeiten war er ein mächtiger Gegner in der Schlacht um das Hügelland. Im Untod wird er unsere Fähigkeiten sicher auf die Probe stellen.\n\nUferbach kanalisiert mächtige arkane Magie im nordwestlichen Teil der Schlickfelder. Führt uns dorthin und gemeinsam werden wir seiner Herrschaft ein für alle Mal ein Ende bereiten.", sourceObjective = "Tötet Magistrat Uferbach.", progress = "Verschwendet nicht meine Zeit, {name}.", completion = "Jetzt lassen wir Aufseher Stillwasser Gerechtigkeit erfahren!", sourceObjectiveStatus = "unverified-source-field" }
quests[28237] = { id = 28237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Seuche überzieht das Land", description = "Nun da der Ausbruch des Untodes eingedämmt wurde, ist es an der Zeit, Aufseher Stillwasser und seine Gefolgsleute zur Rechenschaft zu ziehen. Auch wenn wir eine Tragödie verhindert haben, deren Ausmaß dem der Invasion der Geißel geglichen hätte, müssen wir sicherstellen, dass so etwas nie wieder geschehen kann. Sie werden alle den wahren Tod erleiden!\n\nKommt, {name}! Ich will Stillwassers Kopf rollen sehen.", sourceObjective = "Schlagt Aufseher Stillwasser den Kopf ab.", progress = "Verschwendet nicht meine Zeit, {name}.", completion = "Ich werde diesen Kopf persönlich der Bansheekönigin überbringen. Natürlich werde ich Eure Rolle bei alldem erwähnen, {name}.\n\nWas Eure Belohnung betrifft - nehmt Euch aus Stillwassers Vorräten, was immer Ihr wollt. Ihr habt es Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[28238] = { id = 28238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtufer", description = "Die Zeit ist gekommen, {class}. Nun da Sturmwind sicher ist, werden wir die Schlacht zu unseren Feinden tragen. Auf ins Hochland!\n\nDer Großteil unserer Flotte ist schon unterwegs, dank Eurer Bemühungen. Aber Fargo Flintlocke hat ein Wasserflugzeug vorbereitet, in dem Ihr die Reise doppelt so schnell hinter Euch bringen könnt.\n\nSprecht unten am Hafen mit Flintlocke, und sagt ihm, dass Ihr bereit seid, ihn ins Hochland zu begleiten. Er wird sich am Wasser befinden. Gute Reise, {name}.", sourceObjective = "Sprecht mit Fargo Flintlocke im Hafen von Sturmwind.", completion = "Ein Flug ins Hochland soll's also sein? Da hab' ich genau das Richtige!\n\nIch mach' Euch mal ein bisschen Platz in meinem Wasserflugzeug. Ich werd' wohl das Katzenfutter wieder rauswerfen müssen - Ihr wisst schon, falls wir in den Bergen abstürzen und wochenlang keine Aussicht auf Rettung haben.\n\nWenn ich's mir so überlege, nehmt das Katzenfutter doch einfach auf den Schoß, aye.", sourceObjectiveStatus = "unverified-source-field" }
quests[28239] = { id = 28239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Schwarzzahnunterschlupf", description = "Das ist nicht unbedingt die... überzeugendste Verkleidung, die ich je gesehen habe, aber sie wird schon ausreichen. Bei verdeckten Ermittlungen geht es ja auch eigentlich fast nur um Wichtigtuerei. Verhaltet Euch einfach, als hättet Ihr alles Recht der Welt, dort zu sein und es wird schon klappen.\n\nEure Kontaktperson im Schwarzzahnunterschlupf ist ein Orc mit Namen Rüstmeister Kaoshin. Er weiß NICHT Bescheid, dass Ihr ein Spion seid, also haltet Euch bedeckt.\n\nErfüllt, worum auch immer Kaoshin Euch bittet. Oberst Trottmann wird mittels des Gnomcorders Kontakt mit Euch halten und Euch genauere Anweisungen geben.\n\nViel Glück da draußen, <Soldat/Soldatin>.", sourceObjective = "Sprecht mit Rüstmeister Kaoshin im Schwarzzahnunterschlupf in der Brennenden Steppe.\n\nBereitgestellter Gegenstand:", completion = "Wo bleibt Ihr denn, Grunzer? Ihr seid spät dran! Gebt mir auch nur einen Grund, warum ich Euch nicht auf der Stelle einen Kopf kürzer machen sollte!", sourceObjectiveStatus = "unverified-source-field" }
quests[28240] = { id = 28240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgebrannt", description = "Hört her, {name}. Ihr wisst ja, dass ich nur dafür da bin, Euch zu unterhalten und dass ich mir alle Mühe gebe, Euch angenehm beschäftigt zu halten und so weiter.\n\nAber wie es der zufall nun will sind mir völlig die Ideen ausgegangen.\n\nDas war's!\n\nNormalerweise fallen mir beim Questen mit Euch immer ein paar Dinge ein, die ich Euch als nächstes tun lassen kann, was mir wiederum Zeit verschafft, das nächste großartige Ziel auszudenken. Aber damit ist es jetzt vorbei.\n\nIch stehe mit leeren Händen da. Völlig eingebungslos. Könnte mir nicht mal etwas einfallen lassen, wenn mein Leben davon abhinge.\n\nOh, moment mal! Ich weiß, was wir machen können!\n\nSprecht noch einmal in ein bis zwei Wochen mit mir...", sourceObjective = "Harrison Jones möchte, dass Ihr in ein bis zwei Wochen noch einmal mit ihm sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28241] = { id = 28241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Vision des Zwielichts", description = "Cho'gall bleibt durch diese seltsamen magischen Kugeln über seine Diener informiert: die \"Augen des Zwielichts\".\n\nWenn Ihr eine davon beschaffen könntet, glaube ich, dass wir Cho'gall ausspionieren und sehen können, was seine Diener treiben. Besorgt mir eine!\n\nSucht im Schwarzen Riss östlich von hier, nördlich des Flusses. Findet ein Auge des Zwielichts und tut, was auch immer getan werden muss, um es zu mir zu bringen.", sourceObjective = "Findet ein Auge des Zwielichts im Schwarzen Riss.", completion = "<Das Auge liegt vor Euch und summt unheilvoll vor dunkler Energie.>\n\n<Ohne Warnung dreht sich die Kugel, als sehe sie Euch an. Ihr spürt die Anwesenheit des Bösen, als sei die Kugel lebendig.>", sourceObjectiveStatus = "unverified-source-field" }
quests[28242] = { id = 28242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir müssen alle Opfer bringen", description = "<Das Auge spricht mit Euch; seine 'Stimme' scheint aus allen Richtungen zugleich zu erschallen.>\n\nIhr wünscht einen Blick durch mich zu werfen, {race}? Meine Macht ist nur für einen bestimmten Preis zu haben. Diese Jünger des Zwielichts haben mich mit dem Blut der Wildhammerzwerge beehrt, aber ich verspüre immer noch Durst. Vielleicht könntet Ihr es besser machen.\n\nTötet meine alten Herren und meine Visionen gehören Euch. Ehrt mich, indem Ihr Schamanen der Schwärze tötet. Schließlich ist ein Blut so gut wie das andere.", sourceObjective = "Tötet 10 Schamanen der Schwärze.", progress = "Ich habe Euch beobachtet, {race}.", completion = "<Das Auge glänzt dunkel und Farben huschen über seine dunkle Oberfläche.>\n\nAh, die saftige Genugtuung eines erloschenen Lebens. Könnt Ihr es spüren, {class}? Genießt Ihr es so sehr wie ich?\n\nNein, wie ich sehe, ist dem nicht so. Ihr kämpft, um das Leben Anderer zu schützen. Wie schade.", sourceObjectiveStatus = "unverified-source-field" }
quests[28243] = { id = 28243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Auge des Betrachters", description = "Nun gut, {race}. Ihr habt Euch meine Dienste mit Blut erkauft. Bringt mich zum \"Unterschamanen\" von Donnermar.\n\nOh ja, ich weiß bereits, wohin Ihr mich bringen werdet. Blundys mittelmäßige, biergetränkte Fähigkeiten sind uninteressant. Ihr jedoch - Ihr fasziniert mich, {race}. Stellt Euch nur vor, welche Verwüstung wir in dieser erbärmlichen Welt mit meiner Sicht und Euren Fähigkeiten gemeinsam anrichten könnten...", sourceObjective = "Bringt das Auge des Zwielichts zum Unterschamanen Blundy in Donnermar im Schattenhochland.", progress = "Ihr wieder? Wat? Wat bringt'n Ihr mir da?", completion = "Ihr habt eins gefunden? Ein richtig echtes Auge des Zwielichts? Lasst mal sehen.\n\nIhr Götter. Es guckt mich an. Glotzt ja genau zurück!\n\nIch brauch 'nen Kurzen. Könnt Ihr das Ding zur Wand drehen, oder so?", sourceObjectiveStatus = "unverified-source-field" }
quests[28244] = { id = 28244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich sehe was, was Ihr nicht seht...", description = "Ich will ehrlich sein, {name}. Das Ding macht mich nervös. Aber wo Ihr Euch so viel Mühe gemacht habt, es hierher zu bringen, denke ich mal, wir sollten auch Gebrauch davon machen.\n\nIhr zuerst.\n\nSchaut in das Auge und lasst es Euch das Innere von Cho'galls Bastion des Zwielichts zeigen. Wir finden schon noch heraus, was der dicke, zweiköpfige Schlingel im Schilde führt und benutzen das dann gegen ihn.", sourceObjective = "Schaut in das Auge des Zwielichts für den Unterschamanen Blundy.", completion = "Was habt Ihr gesehen, {name}? Cho'gall? Moment - er hat EUCH gesehen?\n\nOh, aye. Dieses tückische kleine Auge! Das schaut in beide Richtungen. Dieser freche Glubscher! Wo is' mein Hammer!?", sourceObjectiveStatus = "unverified-source-field" }
quests[28245] = { id = 28245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grunzertreiberei", description = "Pah! Ihr habt Glück, dass mir heute die Arbeitskräfte fehlen. Sonst hätte ich Euch für diese Woche zu <meinem Prügelknaben/meinem Prügelmädchen> gemacht.\n\nDie Stiefel der Offiziere und hochrangigen Soldaten müssen gewienert werden. Sie stehen draußen vor ihren Hütten.\n\nIch möchte mich darin spiegeln können, Grunzer! An die Arbeit!", sourceObjective = "Poliert 7 Paar Schwarzfelsstiefel sehr gründlich.", completion = "Hmpf. Gute Arbeit, Grunzer.", sourceObjectiveStatus = "unverified-source-field" }
quests[28246] = { id = 28246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Personaleinsparungen", description = "<Rauschen> {name}... {name}, könnt Ihr mich hören? Hier spricht Trottmann.\n\nHört zu, wir haben gerade erst neue Informationen für Eure nächste Mission erhalten. Wir möchten, dass Ihr drei Personen unschädlich macht. Das erste Ziel ist Voodooist Timan, den Ihr oben auf der Aschensäule findet. Worgmeisterin Othana hält sich in den Worgzwingern in der Mitte des Lagers auf. Das letzte Ziel, Gorlop, befindet sich in der Nähe der Lavateiche im Süden.\n\nIhr findet die Skorpidstachel, die Ihr gesammelt habt, in Euren Habseligkeiten. Wendet die Stachel zur richtigen Zeit auf die Zielpersonen an.", sourceObjective = "Benutzt den rasiermesserscharfe Skorpidstachel, um Voodooist Timan auf der Aschensäule, Worgmeisterin Othana in den Worgzwingern und Gorlop bei den Lavateichen auszuschalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28247] = { id = 28247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte ihrer Art", description = "Obsidia ist eins der letzten ausgewachsenen Drachenweibchen, die die Blutlinie des schwarzen Drachenschwarms fortsetzen könnte. Sie muss getötet werden.\n\nWenn Ihr sie erfolgreich töten könnt, solltet Ihr Lirastrasza sofort von Eurem Sieg unterrichten. Sie arbeitet schon lang auf dieses Ziel hin.\n\nDanke, dass Ihr in diesen Schlachten unsere Speerspitze wart. Ihr habt Euch als <ein mächtiger Verbündeter/eine mächtige Verbündete> herausgestellt.", sourceObjective = "Tötet Obsidia.", completion = "Ihr habt Obsidia in ihrem eigenen Hort besiegt? Beeindruckend, {race}. Es tut mir leid, dass ich nicht dabeisein konnte.\n\nIhr steht zu Eurem Wort und Eure Versprechen sind nicht nur Schall und Rauch. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[28248] = { id = 28248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gipfel des Siegers", description = "Ihr habt Eure Absichten und Fähigkeiten mehr als bewiesen. Nun, da Grim Batol abgeschnitten und die Schwarzdrachen verjagt wurden, sitzen die Schattenhammerkultisten in ihrer Zitadelle in der Falle.\n\nSucht Eure Anführer auf. Sie sollten nordöstlich von hier am Gipfel des Siegers sein. Lasst sie wissen, dass zu Beginn des Angriffs auf die Schattenzitadelle die roten Drachen in den Himmeln kreisen werden. Ihr werdet nicht für all die Taten Eurer Verbündeten Buße tun können, aber in diesem einen Kampf werden wir an Eurer Seite sein.\n\nDer Schattenhammer wird fallen!", sourceObjective = "Sprecht mit Kurdran Wildhammer am Gipfel des Siegers.", completion = "Ihr habt gute Arbeit geleistet, {name}. Wir sind gerade dabei, den Angriff vorzubereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28249] = { id = 28249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmetterschlagposten", description = "Ihr habt Euren Willen und Eurer Können mehr als ausreichend bewiesen. Jetzt, da Grim Batol abgeschnitten ist und die schwarzen Drachen besiegt sind, sitzt der Schattenhammer in seiner Zitadelle in der Falle.\n\nGeht zu Euren Anführern. Ihr findet sie im Westen, im Schmetterschlagposten. Lasst sie wissen, dass der rote Drachenschwarm die Himmel zum Beben bringen wird, wenn der Angriff auf die Schattenzitadelle beginnt. Vielleicht könnt Ihr nicht für alle Sünden büßen, die Eure Verbündeten begangen haben, aber in dieser Schlacht werden wir Euch zur Seite stehen.\n\nDer Schattenhammer wird fallen.", sourceObjective = "Sprecht mit Kriegsfürstin Zaela im Schmetterschlagposten.", completion = "Ihr habt gute Arbeit geleistet, {name}. Wir sind gerade dabei, den Angriff vorzubereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28250] = { id = 28250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diebische Pflücker", description = "Ich habe nicht den glanzvollsten Beruf in der Welt.\n\nKriegsangelegenheiten und die tiefen Geheimnisse der Hallen von Uldum oder sonst was kümmern mich wenig.\n\nIch trage die Verantwortung über diesen Boden... und dieser Boden lässt Datteln wachsen.\n\nNun sind diese Dattelpflücker gefräßig genug geworden, sich gegenseitig auf die Schultern zu steigen und zu versuchen, meine kostbaren Früchte zu stehlen.\n\nDamit ist jetzt Schluss.\n\nNehmt diesen Hammer - er wurde von den Titanen gefertigt und trägt den Segen der Sonnenkönige und wer weiß was noch alles - und macht diese Kümmerlinge platt!", sourceObjective = "Vermöbelt 30 Sandpygmäen mit dem Hammer der Tahretdynastie", completion = "Ihr habt diesen diebischen Plagegeistern gezeigt, wo der Hammer hängt. Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[28251] = { id = 28251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in Süderstade", description = "Ich war in Süderstade stationiert, bevor man mich gefangen genommen und eingesperrt hat. Bei den Ruinen habe ich in erster Linie Schlammproben entnommen und sichergestellt, dass die Seuche, die wir freigesetzt hatten, sicher verbreitet wird. Das wäre ohne die ständigen Angriffe der Worgen eine leichte Arbeit gewesen.\n\nIch möchte, dass Ihr Euch nach Süderstade begebt und nach meinem Lehrling Serge Hinott sucht. Ich muss wissen, ob es ihm gut geht, und er muss wissen, dass ich zurückkommen werde, wenn meine Arbeit hier beendet ist.\n\nDie Ruinen von Süderstade sind in der Nähe der Küste, südöstlich von hier.", sourceObjective = "Sprecht mit Serge Hinott bei den Ruinen von Süderstade im Vorgebirge des Hügellands.", completion = "Die Situation mit den Worgen hat sich nicht verbessert und Helcular macht mir echt Angst.", sourceObjectiveStatus = "unverified-source-field" }
quests[28252] = { id = 28252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn des Kodorufers", description = "Nun gut, ich habe richtige, ehrliche und sogar wichtige Arbeit für Euch! Wir müssen die Kodos rufen, die in den Gebieten südlich von hier grasen. General Thorg'izog sagt, dass wir bald ins Rotkammgebirge aufbrechen, und ich kann nicht zulassen, dass wir ohne die Kodos aufbrechen.\n\nBenutzt dieses Horn in der Nähe eines Kodos. Sobald es den Ruf hört, wird es sich auf in Richtung Lager machen.\n\nIhr müsst aber aufpassen. Manchmal sind die Kodos ein bisschen angriffslustig, und es kann sein, dass Ihr ein bisschen mit ihnen 'spielen' müsst, bevor sie auf Euch hören.", sourceObjective = "Benutzt das Horn der Rufer, um 7 Kriegskodos des Schwarzfels zurück zum Lager zu rufen. Bekämpft feindselige Kodos, bis sie aufgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28253] = { id = 28253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir behalten das Horn", description = "{name}, Trottmann hier. Ich will, dass Ihr dieses Horn behaltet. Ich bin sicher, dass wir improvisieren können, um es in unseren Plan einzubinden.\n\nIch bin etwas besorgt über das, was Kaoshin zum Angriff auf das Rotkammgebirge gesagt hat. Wir wussten, dass ein neuer Angriff aussteht, aber wir haben uns um mehrere Tage verrechnet.\n\nKehrt mit dem Horn zu mir zurück. Wir werden hier in Meißelgriff weitersprechen. Versucht, Eure Verkleidung nicht zu verlieren. Ihr seid mit Eurer verdeckten Arbeit noch nicht fertig.", sourceObjective = "Bringt das Horn der Rufer zurück zu Oberst Trottmann in Meißelgriff in der Brennenden Steppe.", progress = "Willkommen zurück, Soldat.", completion = "Ich hatte nicht damit gerechnet, einen Gegenstand wie diesen erhalten zu können. Unsere Pläne werden dementsprechend geändert werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28254] = { id = 28254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nadel im Höllhaufen", description = "Ihr und ich können uns zu zweit keiner Armee stellen, {name}. Wir werden zahlenmäßig überwältigt werden. Deswegen müssen wir uns genau an Trottmanns Plan halten.\n\nFür den nächsten Schritt laut Plan bedarf es etwas Feingefühls... und darin bin ich nicht besonders gut. Hier kommt Ihr ins Spiel.\n\nSprecht mit Thelaron Düsternadel, dem Schneider hier vor Ort. Ich habe ihm bereits die Bälge und den Schlamm gegeben, die Ihr gesammelt habt. Er muss Eure Maße nehmen.\n\nGenau, {name}: Wir werden Euch als einen der Feinde verkleiden.", sourceObjective = "Sprecht mit Thelaron Düsternadel in Meißelgriff in der Brennenden Steppe.", completion = "Ihr braucht eine Verkleidung? Nun, da seid Ihr genau am richtigen Ort, Schätzchen.\n\nLasst mich mal sehen... mm-hmm. Ich weiß genau, was wir machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28255] = { id = 28255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was kommt als Nächstes?", description = "Wie wird das alles enden? Hmm?\n\nWerde ich mich gegen meinen dunklen Meister stellen, wer auch immer das sein mag?\n\nWerde ich zu einem einfühlsameren und teilnahmsvolleren Anführer werden?\n\nOder werde ich meine Ambitionen umsetzen, mit allen Mitteln voranstürmen und nicht ruhen, bis ganz Azeroth mir gehört?\n\nUnd was dann, hmm?\n\nVielleicht klärt sich ja alles nächste Woche...\n\n... oder vielleicht die Woche darauf...", sourceObjective = "Kommandant Schnottz will doch nur umarmt werden...", sourceObjectiveStatus = "unverified-source-field" }
quests[28256] = { id = 28256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schädel des Gul'dan", description = "Illidan ist aufgebrochen, um den Schädel des Gul'dan zu finden. Er hat ganze Armeen von Dämonen bekämpft und sie mit einer Kraft getötet, die ihn zu einem verhassten Ausgesetzten gemacht haben.\n\nStellt Euch ihm in der Schlacht, {name}. Werdet Zeuge vom stärksten Kämpfer gegen die Verderber Teufelwalds und erledigt ihn.", sourceObjective = "Erlebt Illidans Kampf um den Schädel des Gul'dan.", completion = "Nun werdet Ihr bald verstehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[28257] = { id = 28257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sturz von Tichondrius", description = "Ja, Illidan hat die Macht des Schädels von Gul'dan erlangt.\n\nAber ist er damit in die Dunkelheit geflohen? Hat er sie für seinen eigenen Ruhm genutzt? Nein... seine erste Tat mit der neuerlangten Macht war es, den Schreckenslord Tichondrius anzugreifen!\n\nWerdet Zeuge seines Triumphs, {name}. Werdet Zeuge davon, wie Illidan Teufelswald von den Dämonen befreite... und von dem Dank, den er dafür erhalten hat.", sourceObjective = "Erlebt Illidans Kampf mit Tichondrius.", completion = "Habt Ihr es gesehen? Mein Meister hat das getan, was getan werden musste, um die Dämonen aus diesen Ländern zu vertreiben, und zum Dank wurde er verbannt.\n\nDie Druiden richten nun alles und klopfen sich auf die Schultern, weil sie die Überreste der Streitmächte der Legion vertrieben haben.\n\nDas ist aber nicht der Grund, warum ich sie getötet habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28258] = { id = 28258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Ander Germaine", description = "Ander Germaine hat Euch eine Nachricht zukommen lassen. Er möchte, dass Ihr ihn in der Kommandozentrale in Sturmwinds Altstadt besucht, so schnell Ihr könnt. Es klang sehr wichtig, {name}.", sourceObjective = "Sprecht mit Ander Germaine in der Kommandozentrale südlich von Sturmwinds Altstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28259] = { id = 28259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Demisette Cloyce", description = "Soeben habe ich eine Nachricht von Demisette Cloyce in Sturmwind erhalten. Sie fordert Euch auf, sie im Gasthaus Zum Geschlachteten Lamm zu treffen. Genaueres zu diesem Treffen hat sie nicht angegeben, aber ich hatte den Eindruck, dass es sich um etwas Wichtiges handelt.", sourceObjective = "Sprecht mit Demisette Cloyce im Keller des Gasthauses Zum Geschlachteten Lamm im Magierviertel von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[28260] = { id = 28260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Wulf Hansreim", description = "Wulf Hansreim hat aus Sturmwind Kunde geschickt - er möchte Euch so bald wie möglich treffen. Ihr werdet ihn in der Kommandozentrale südlich der Altstadt von Sturmwind auffinden können.", sourceObjective = "Sprecht mit Wulf Hansreim in der Kommandozentrale südlich von Sturmwinds Altstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28261] = { id = 28261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betrüger in unserer Mitte", description = "Nun, da Ihr in der Unvoreingenommenheit unterrichtet wurdet, möchtet Ihr vielleicht erfahren, WARUM ich diese Druiden getötet habe.\n\nDie Antwort ist einfach: Sie sind keine Druiden.\n\nDämonen suchen die Ruinen noch immer heim und haben die Gestalt von friedlichen Hütern angenommen. Seht es Euch mit eigenen Augen an - diese Augenbinde hier ist von dem Blut eines Dämonen getränkt. Nehmt sie und geht zur Jadefeuerschlucht in den Hügeln nördlich von hier, und verbindet Euch dort die Augen damit. Sie ermöglicht es selbst dem nichtsahnendsten Narren, die wahre Natur eines Dämonen zu erkennen.", sourceObjective = "Tötet 12 Jadefeuerschleicher in der Jadefeuerschlucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28262] = { id = 28262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Lord Tony Romano", description = "Lord Tony Romano, einer der erfahrensten Schurkenlehrer von Sturmwinds SI:7, hat verlauten lassen, dass er Euch sprechen möchte. Begebt Euch so bald wie möglich nach Sturmwind und sucht ihn im Gebäude des SI:7 südlich von Sturmwinds Altstadt auf.", sourceObjective = "Sprecht mit Lord Tony Romano im Hauptquartier von SI:7 südlich von Sturmwinds Altstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28263] = { id = 28263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Maginor Dumas", description = "Soeben habe ich eine Nachricht von Maginor Dumas, dem führenden Magierlehrer in Sturmwind erhalten. Er bittet Euch, ihn im Magiersanktum in Sturmwind zu besuchen, sobald Euch die Reise möglich ist.", sourceObjective = "Sprecht mit Maginor Dumas im Magiersanktum im Magierviertel von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[28264] = { id = 28264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Navarax' Schachzug", description = "Ich habe diesen betrügerischen Dämonen lange aufgelauert und endlich den Standort ihres Anführers ausfindig gemacht. Es handelt sich dabei um keinen geringeren als den Erzdruiden Navarax, Anführer des Smaragdkreises.\n\nDer Dämon schützt sich selbst durch Unschuldige. Wenn ich den Wisperwindhain betreten würde, um ihn zu jagen, so würden mich seine unwissenden Beschützer abhalten... aber Ihr! Ihr könnt ihn unbemerkt erwischen.\n\nBegebt Euch erneut zum Wisperwindhain. Steigt den Druidenturm hinauf - ganz oben werdet Ihr Navarax finden, in seinem Raum inmitten der Zweige.", sourceObjective = "Tötet den Dämonen, der als Erzdruide Navarax erscheint.", progress = "Habt Ihr Neuigkeiten für mich?", completion = "Es fällt mir schwer, Euch das alles zu glauben, aber die Leiche des Dämons ist Beweis genug.\n\nIch werde umgehend eine Untersuchung der Druiden am Jadefeuerbach in die Wege leiten, und dafür sorgen, dass meine Vorgesetzten alle wissen, dass der Dämonenjäger wohl kein Problem damit hat, im Exil zu bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[28265] = { id = 28265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Thorg'izog", description = "Kaoshin hat sich als hilfreicher herausgestellt, als wir vermutet hatten, aber jetzt brauchen wir ihn nicht mehr. Es ist an der Zeit, mit dem General zu sprechen. Ich glaube, Ihr seid bereit.\n\nGeneral Thorg'izog ist einer der \"großen Drei\", die die Bodentruppen in der Brennenden Steppe anführen. Er befindet sich in der Schwarzfelsfestung im Nordwesten. Zieht Eure Verkleidung an und sprecht mit ihm. Versucht, sein Vertrauen zu gewinnen. Trottmann wird sich bei Euch melden, sollte ich noch etwas von Euch brauchen.", sourceObjective = "Sprecht mit General Thorg'izog.", completion = "Noch mehr Außenstehende? Was wollt Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[28266] = { id = 28266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magmataufe", description = "Ich muss aus dieser Situation das Beste machen. Diese Goblinsöldner haben mir diesen riesigen Feuerelementar als \"Dankeschön\" geschickt, weil ich sie angeheuert habe. Was soll ich denn hier in der Steppe mit einem Elementar anfangen? Das ist ja fast, wie Wasser zum Meer zu tragen.\n\nWenn Ihr nach Arbeit sucht, so könnt Ihr Euch nun beweisen. Sprecht mit diesem Goblin hier und fordert seinen Elementar zum Kampf heraus. Ich werde dem Sieger meinen Respekt zollen und meine Zeit geben.", sourceObjective = "Sprecht mit Würtl Sprillhuper und bittet ihn, Magmalord Kolob freizulassen. Besiegt danach Magmalord Kolob im Kampf.", progress = "Was ist los? Habt Ihr Angst?", completion = "Ich hatte fast damit gerechnet, dass Ihr als Sieger hervortreten würdet. Mir gefällt Eure Art, zweifellos.", sourceObjectiveStatus = "unverified-source-field" }
quests[28267] = { id = 28267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erschießungskommando", description = "Folgt mir nach draußen, {race}.\n\nIch möchte, dass Ihr etwas mit anseht.", sourceObjective = "Sprecht mit Kommandant Schnottz.", completion = "Schnottz arbeitet also für Todesschwinge?\n\nDas ist weitaus beunruhigender, als Ihr Euch vorstellen könnt...", sourceObjectiveStatus = "unverified-source-field" }
quests[28268] = { id = 28268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Lord Grayson Schattenbruch", description = "Lord Grayson Schattenbruch der Kathedrale des Lichts in Sturmwind hat Euch einen Nachricht geschickt. Er möchte, dass Ihr Euch bei ihm meldet, wenn Ihr das nächste Mal in der Stadt seid. Ihr könnt ihn im Kathedralenviertel finden.", sourceObjective = "Sprecht mit Lord Grayson Schattenbruch bei der Kathedrale des Lichts in Sturmwinds Kathedralenviertel.", completion = "Ich wünschte, Ich hätte gute Nachrichten für Euch, {name}, aber leider habe ich Euch hierher gebeten, weil wir Euer Talent brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28269] = { id = 28269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft mich in Vir'sar", description = "Hört mir gut zu, {name}.\n\nIch wusste, dass die Obelisken etwas mit der Lade der Verheißung zu tun haben, aber das ist noch nicht alles.\n\nEs scheint, dass es mit der Lade etwas sehr Wichtiges auf sich hat - etwas, das die Schöpfer die Hallen des Ursprungs nennen.\n\nNun, da wir wissen, dass dieser Schnottz und seine Truppe mit Todesschwinge im Bunde sind, ist es nur noch dringlicher, dass wir die Lade zuerst bekommen.\n\nIch werde nördlich von hier in der Oase Vir'sar auf Euch warten.\n\nBeeilt Euch! Sie haben bereits einen Vorsprung!", sourceObjective = "Sprecht mit Harrison Jones in der Oase Vir'sar.", completion = "Ahh, freut mich, dass Ihr es geschafft habt.\n\nIch könnte hier etwas Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28270] = { id = 28270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sozius", description = "In Ordnung, {name}, ich stehe kurz davor, den letzten Obelisken aktivieren zu können.\n\nMir fehlen nur noch ein paar Informationen, und mit ein bisschen Glück werden wir sie vor Ort finden können.\n\nDie Vorräte sind schon eingepackt. Sagt Bescheid, wenn Ihr bereit seid.", sourceObjective = "Begleitet Harrison zur Oase Vir'sar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28271] = { id = 28271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Produktivitätseinbußen", description = "Also, {name}. So viel konnte ich herausfinden.\n\nAn einem Ort namens Hallen des Ursprungs gibt es ein Gerät der Titanen. Es soll eine Art Notfallschalter sein, der alles Leben in Azeroth zurücksetzt. Wenn er aktiviert wird, wird jedes Lebewesen auf der ganzen Welt vernichtet!\n\nNatürlich ist es nur für den absoluten Notfall gedacht, aber wenn es Todesschwinge gelingt, die titanischen Wächter zu verderben, kann er den Inhalt der Lade benutzen, um das Gerät auszulösen.\n\nGeht zum Obelisken des Mondes, {name}. Haltet sie auf!", sourceObjective = "Tötet 15 Ausgräber von Schnottz oder Aufseher von Schnottz.", completion = "Schnottz' Männern habt Ihr es gezeigt.\n\nEure Lektion werden sie so schnell sicher nicht vergessen.\n\nHoffentlich hat uns das die nötige Zeit verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[28272] = { id = 28272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlende Stücke", description = "Mir fehlen nur noch ein paar spezielle Informationen.\n\nSobald diese Lücken geschlossen sind, werden wir bereit sein, den letzten Obelisken zu aktivieren. Dann beginnt der Wettlauf um die Lade der Verheißung gegen Schnottz und seine Handlanger.\n\nDie Narren graben diesen Ort so schnell sie können um. Sie richten mehr Schaden an, als sie finden.\n\nGeht zum Obelisken und durchsucht ihre Beute, {name}.\n\nSchaut, ob Ihr unsere fehlenden Puzzleteile finden könnt.", sourceObjective = "Sammelt 7 uralte Kupferschriftrollen.", progress = "Konntet Ihr etwas Interessantes finden, {name}?", completion = "<Harrison überfliegt die Rollen zügig.>\n\nJa... ja... Perfekt!\n\nIch werde etwas Zeit brauchen, um sie zu entschlüsseln, aber die Informationen sind darin enthalten.\n\nGute Arbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28273] = { id = 28273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Freund eines Freundes", description = "Ich muss auspacken und die Gegend ein wenig auskundschaften. In der Zwischenzeit möchte ich, dass Ihr einen alten Freund von mir trefft.\n\nSullah und ich kennen uns seit Ewigkeiten. Man kann ihm vertrauen, und das ist schon selten heutzutage.\n\nWarum geht Ihr nicht zu ihm und begrüßt ihn?", sourceObjective = "Harrison möchte, dass Ihr mit Sullah in der Oase Vir'sar sprecht.", completion = "Willkommen, {class}!\n\nWir beide werden uns gut verstehen! Das kann ich jetzt schon sagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28274] = { id = 28274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei Zelte", description = "Seht Euch an! Das Abenteuer steht Euch förmlich ins Gesicht geschrieben!\n\nIhr müsst Euch aber auch ein wenig erholen. Ihr seht angespannt aus und das macht einen schnell müde.\n\nVertraut mir, mit Erholung kenne ich mich aus!\n\nA propos Erholung: Jonesy hat mir anscheinend die Zelte gebracht, um die ich ihn gebeten habe.\n\nKommt. Reitet mit mir!", sourceObjective = "Begleitet Sullah zu Sullahs Fahrendem Zirkus", completion = "Da wären wir, {name}!\n\nGroßartige Dinge werden hier stattfinden... magische Dinge!", sourceObjectiveStatus = "unverified-source-field" }
quests[28275] = { id = 28275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bom-ben-los!", description = "Wellsons Werft empfängt dauernd Vorräte von den Küstengewässern aus und das muss aufhören. Sie haben Kanonen an den Docks aufgestellt, um sich zu verteidigen, aber wenn Ihr zu ihnen durchbrechen könnt, können wir mit ihnen die Versorgungsschiffe zerstören.\n\nBegebt Euch dorthin und seht mal, was Ihr tun könnt. Erstattet mir über Eure Fortschritte Bericht.", sourceObjective = "Zerstört 10 scheußliche Versorgungsboote.", completion = "Ausgezeichnete Arbeit mit den Versorgungsbooten, {name}! Wir wussten, dass Ihr was taugt!", sourceObjectiveStatus = "unverified-source-field" }
quests[28276] = { id = 28276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salhets Geheimnis", description = "Hört gut zu, {name}. Bevor Ihr Euer Vertrauen in mich verliert, würde ich Euch gerne noch etwas zeigen.\n\nWie Ihr wisst, bin ich kein Kämpfer. Meine Koordination ist nicht gut.\n\nIch sehe mich eher als Taktiker an.\n\nTrefft mich am südlichen Ende des Grats und ich werde Euch zeigen, was ich meine.", sourceObjective = "Findet Salhet am südlichen Ende des Sonnenbehütergrats in Uldum.", completion = "Sind sie nicht wunderschön?", sourceObjectiveStatus = "unverified-source-field" }
quests[28277] = { id = 28277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salhet der Taktiker", description = "Schon als ich ein Junges war, wollte ich unbedingt ein General werden.\n\nIch wollte unbedingt der Armee beitreten. Aber wie Ihr gesehen habt, ist es um meine Kampfkünste schlecht bestellt.\n\nIch wurde schon früher zum Hyänentöten geschickt. Ich wurde schon so oft hierher geschickt, dass ich mich inzwischen mit den Löwen angefreundet und sie trainiert habe, das zu machen, was ich will.\n\nSie sind meine Soldaten, folgen meinen Befehlen und töten massenweise Hyänen. Seht selbst!", sourceObjective = "Sprecht mit Salhet und tötet 30 Murrblutaasfresser", completion = "Nicht schlecht, was? Vielleicht könnt Ihr beim Hochkommandanten ein gutes Wort für mich einlegen?\n\nVielleicht erteilt er uns Zuständigkeit über unsere eigene Einheit!", sourceObjectiveStatus = "unverified-source-field" }
quests[28278] = { id = 28278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin das Gesetz und dessen starker Arm", description = "Ich war auf der Suche nach <einem starken Soldaten/einer starken Soldatin> wie Euch. Ich brauche jemanden, der dafür sorgt, dass meine Truppen sich benehmen.\n\nAußerhalb der Festung bereiten sich die Orcs, Oger und Trolle auf einen Angriff auf das Rotkammgebirge vor. Meine Unteroffiziere halten sie zwar auf Trab, aber sie brauchen Hilfe.\n\nNehmt diesen Knüppel und diszipliniert ein paar meiner Soldaten.\n\nEs ist mir egal, ob sie in Reih und Glied stehen oder sich fehlverhalten - ich will nur, dass sie eine Tracht Prügel bekommen. Ich will, dass sie sich konzentrieren, auf die Schlacht vorbereitet und abgehärtet sind, und gefolgsam.\n\nGeht nun.", sourceObjective = "Benutzt den Disziplinarknüppel des Schwarzfels bei 20 Einheiten in den Feldern der Ehre. Wenn jemand merkt, wer Ihr seid, so erschlagt ihn, bevor er Eure Maskierung aufheben kann.", completion = "Ich habe das Gefühl, dass wir von Euch noch viel hören werden, Soldat. Ich freue mich darauf, an Eurer Seite im Rotkammgebirge zu kämpfen.\n\nWegtreten!", sourceObjectiveStatus = "unverified-source-field" }
quests[28279] = { id = 28279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machtmissbrauch", description = "{name}? Trottmann hier.\n\nWie es scheint, habt Ihr Thorg'izogs Vertrauen gewonnen, denn er hat Euch für die Disziplinierung eingeteilt. Das ist ein Glück.\n\nWir müssen diese Feldwebel loswerden. Ihr findet sie außerhalb der Schwarzfelsfestung in den Feldern der Ehre auf Wölfen reitend. Benutzt den Knüppel so oft wie nötig, bis sie sterben. Ihr müsst schnell handeln, denn wenn sie merken, dass Ihr <keiner/keine> von ihnen seid, dann werden sie versuchen, Eure Maskierung aufzuheben. Seid schnell und zügellos, {name}.\n\nTrottmann aus.", sourceObjective = "Tötet 5 Feldwebel des Schwarzfels mit dem Disziplinarknüppel des Schwarzfels. Besiegt sie schnell, bevor sie Eure Maskierung aufheben können.", sourceObjectiveStatus = "unverified-source-field" }
quests[28280] = { id = 28280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reißt sie vom Himmel!", description = "Um Himmels Willen! Sie sind hier, {name}. Sie sind hier!\n\nIch hatte gehofft, eine ganze Armee mit meinen tragbaren Drachenfäusten ausrüsten zu können, aber ich habe nur einen einzigen, extrem teuren und viel zu wenig getesteten Prototypen. Hier, nehmt ihn!\n\nSchießt auf die Schwarzdrachen des Drachenmals, die um Donnermar kreisen, und lasst sie vom Himmel stürzen!", sourceObjective = "Benutzt den tragbaren Drachentöter, um 8 Schwarzdrachen des Drachenmals zu töten.", completion = "Ihr habt es geschafft, {name}! Wieder einmal hat die Genialität der Allianz den Tag gerettet.\n\nNatürlich habe ich jetzt nichts, mit dem Ihr die abgestiegenen Reiter auf dem Boden bekämpfen könntet. Aber Ihr seid ein {class}. Improvisiert!", sourceObjectiveStatus = "unverified-source-field" }
quests[28281] = { id = 28281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letztes Gefecht in Donnermar", description = "Ich überlasse es Euch und Euren Freunden von der Allianz. Ihr habt es dem Drachenmalklan bisher schon gut gezeigt!\n\nViele ihrer berittenen Kämpfer sind bereits ihre Reittiere los, aber sie kommen immer noch in unsere Richtung und meine Verteidiger kommen ohne Hilfe nicht zurecht.\n\nTötet die Himmelskrallen des Drachenmalklans ohne Reittiere und Donnermar wird für immer in Eurer Schuld stehen!", sourceObjective = "Tötet 8 Himmelskrallen des Drachenmalklans ohne Reittiere.", progress = "Wir sollten eine Kampfpause einlegen und die Feuer löschen, oder Donnermar wird aussehen wie der Rest der Welt, die in Trümmern liegt...", completion = "Ihr müsst Euch auf dem Schlachtfeld gut zurechtfinden können, {class}. Es scheint, als sei ein neuer Einfall geplant.\n\nWir brauchen nur noch einen entscheidenden Schlag...", sourceObjectiveStatus = "unverified-source-field" }
quests[28282] = { id = 28282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Narkrall, der Drachenzähmer", description = "Narkrall vom Drachenmalklan wird auch der \"Drachenzähmer\" genannt. Ich weiß nicht, wie er die Macht erlangt hat, diese Bestien zu befehligen, aber der schwarze Terror, den er reitet, ist der grausigste Drache, der in den ganzen Hochländern zu finden ist.\n\n{name}, Narkrall ist ein Feind, der das Leben meines Vaters genommen und Donnermars Schicksal in meine Hände gelegt hat.\n\nIch kann mich ihm nicht alleine stellen, aber ich habe gesehen, zu was Ihr in der Lage seid, {class}. Vielleicht können wir diesem Schrecken gemeinsam ein Ende bereiten.\n\nLasst mich wissen, wenn Ihr bereit seid, und wir werden Narkrall gemeinsam bekämpfen!", sourceObjective = "Tötet Narkrall Harkenklaue. Sprecht mit Colin Donnermar, wenn Ihr bereit seid.", completion = "Wir haben es geschafft, {name}! Narkrall Harkenklaue liegt tot zu meinen Füßen und Donnermar hat einen Sturm von Drachen abgewehrt!\n\nOhne die Hilfe der Allianz wäre das nicht möglich gewesen. Die Schuld, in der ich stehe werde ich wohl nie begleichen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[28283] = { id = 28283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist das für eine Rassel?", description = "Habt Ihr die leuchtende Rassel gesehen, die vor Ishas Hütte auf dem Boden liegt?", sourceObjective = "Untersucht die Rassel der Knochen in Düsterwolkengipfel in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[28284] = { id = 28284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist das für eine Rassel?", description = "Habt Ihr die leuchtende Rassel gesehen, die vor Ishas Hütte auf dem Boden liegt?", sourceObjective = "Untersucht die Rassel der Knochen in Düsterwolkengipfel in Tausend Nadeln.", completion = "Interessant...", sourceObjectiveStatus = "unverified-source-field" }
quests[28285] = { id = 28285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Hohepriesterin Laurena", description = "Ich habe eine Schriftrolle aus der Kathedrale des Lichts erhalten, {name}. Hohepriesterin Laurena schickt Kunde, dass sie Euch sprechen möchte. Ihr solltet sie so bald wie möglich treffen.", sourceObjective = "Sprecht mit Hohepriesterin Laurena bei der Kathedrale des Lichts im Kathedralenviertel von Sturmwind.", completion = "Das Licht hat meine Gebete erhört. Endlich seid Ihr hier.", sourceObjectiveStatus = "unverified-source-field" }
quests[28286] = { id = 28286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genug Schaden für einen Tag", description = "Wir haben keine weitere strategische Verwendung für Thorg'izog oder die Bodentruppen des Schwarzfels. Wir müssen nun die nächste Phase des Plans einläuten.\n\nWenn Ihr bei der Festung fertig seid, kehrt zurück zu uns in Meißelgriff.", sourceObjective = "Kehrt zu Oberst Trottmann in Meißelgriff zurück.", completion = "Alles in Ordnung?\n\nGut. Ihr habt gute Arbeit geleistet, {name}. Packt Eure Sachen zusammen. Wir ziehen ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[28287] = { id = 28287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Scharfseherin Umbrua", description = "Eine Nachricht von Scharfseherin Umbrua hat mich soeben erreicht, {name}. Es gibt ein wichtiges Anliegen, das sie mit Euch besprechen möchte, und sie bittet darum, dass Ihr sie im Gasthaus Zum Goldenen Fass im Zwergendistrikt in Sturmwind aufsucht, so bald Ihr könnt.", sourceObjective = "Sprecht mit Scharfseherin Umbrua im Gasthaus Zum Goldenen Fass im Zwergendistrikt von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[28288] = { id = 28288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Öffnet ihre Augen", description = "Bevor Ihr geht...\n\nIch habe meine Zeit allein mit Impsy hier genutzt, um ein paar interessante Fakten über Wichtel herauszufinden. Er hat mir nämlich von einer Sache erzählt, die alle Wichtel am meisten fürchten. Etwas, das sie regelrecht in Angst und Schrecken versetzt.\n\nIch fand das sowohl nützlich als auch interessant, also habe ich ein paar geringere Beschwörungen durchgeführt. Dieses Prisma wird ein Bild projizieren von... nun, von dem, was Impsy beschrieben hat.\n\nIm Schattenlauergrat wimmelt es immer noch nur so von Wichteln. Warum geht Ihr nicht dorthin und schaut für mich, wie sie darauf reagieren?", sourceObjective = "Benutzt Delaris' Prisma, um 20 Jadefeuerwichtel zu erschrecken.", completion = "Ich verstehe... Ihre Augen sind geöffnet.\n\n<Delaris lächelt amüsiert.>\n\nVielleicht behalte ich Impsy doch noch eine Weile bei mir. Er kann mir noch viel beibringen...", sourceObjectiveStatus = "unverified-source-field" }
quests[28289] = { id = 28289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondlichtung ruft", description = "Ich habe Nachrichten aus Mondlichtung erhalten. Unsere Brüder bitten um Eure Hilfe, {name}. Ihr solltet Euch auf die Reise machen und Loganaar in Nachthafen aufsuchen.", sourceObjective = "Reist nach Mondlichtung und sprecht mit Loganaar in Nachthafen.", completion = "Gut, Euch wieder zu sehen, {name}. Ich wünschte, ich könnte Euch gute Nachrichten überbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28290] = { id = 28290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Grezz Zornfaust", description = "Grezz Zornfaust hat Euch eine wichtige Nachricht geschickt, {name}. Er möchte, dass Ihr ihn umgehend im Tal der Ehre in Orgrimmar aufsucht. Er scheint ein wichtige Aufgabe für Euch zu haben.", sourceObjective = "Sprecht mit Grezz Zornfaust im Tal der Ehre in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28291] = { id = 28291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Lager zurückkehren", description = "Was meint Ihr, {name}? Vielleicht gibt mir der Hochkommandant ein paar Leute, die ich befehligen kann.\n\nVielleicht können wir zusammen ein Regiment aufstellen. Was meint Ihr?", sourceObjective = "Kehrt zu Hochkommandant Kamses am Außenposten der Legion von Ramkahen zurück.", completion = "Salhet? Ein Taktiker, sagt Ihr?\n\nHah! Na ja, wenn Ihr Euch für ihn verbürgt, können wir bestimmt etwas arrangieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[28292] = { id = 28292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist keine Pyramide!", description = "Die Pyramide bei der Terrasse des Schöpfers in Uldum ist nicht wirklich eine Pyramide im klassischen Sinne. Es ist eine große Maschine, die für unzählig viele Funktionen umprogrammiert werden kann.\n\nTodesschwinge wollte, dass der Schattenhammer sie in eine riesige Waffe umfunktioniert!\n\n{name}, Ihr müsst das Portal benutzen, um Harrison Jones in Sturmwind diese Information zukommen zu lassen. Er wird wissen, was zu tun ist.", sourceObjective = "Sprecht mit Harrison Jones in Burg Sturmwind in Sturmwind.", completion = "Uldum? Was ist damit?", sourceObjectiveStatus = "unverified-source-field" }
quests[28293] = { id = 28293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist keine Pyramide!", description = "Die Pyramide bei der Terrasse des Schöpfers in Uldum ist nicht wirklich eine Pyramide im klassischen Sinne. Es ist eine große Maschine, die für unzählig viele Funktionen umprogrammiert werden kann.\n\nTodesschwinge wollte, dass der Schattenhammer sie in eine riesige Waffe umfunktioniert!\n\n{name}, Ihr müsst das Portal benutzen, um Bellok Leuchtklinge in Orgrimmar diese Information zukommen zu lassen. Er wird wissen, was zu tun ist.", sourceObjective = "Sprecht mit Bellok Leuchtklinge in der Feste Grommash in Orgrimmar.", completion = "Uldum? Was ist mit Uldum? Sprecht, schnell!", sourceObjectiveStatus = "unverified-source-field" }
quests[28294] = { id = 28294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gipfeltreffen in Kirthafen", description = "Dank der Abreibung, die wir dem Drachenmal verpasst haben, werden ihre Angriffe auf Donnermar wohl aufhören. Vielleicht haben die Wildhämmer einen Platz in der Allianz - Donnermar steht in jedem Fall in Eurer Schuld.\n\nUnser großer Schamane, Lachlan MacGraff, hat versucht, ein Gipfeltreffen der Anführer der überlebenden Wildhammerfamilien zu veranstalten. Es ist keine leichte Aufgabe, alle zusammenwirken zu lassen, aber ich werde es zumindest versuchen.\n\nFliegt nach Kirthafen und sprecht mit Lachlan MacGraff. Ich werde Euch dort treffen!", sourceObjective = "Sprecht mit Lachlan MacGraff in Kirthafen im Schattenhochland.", completion = "Hallo, {class}! Keegan Feuerbart hier hat mir schon viel von Euren Heldentaten im Süden berichtet. Ich danke Euch für Eure Bemühungen, uns Wildhämmern zu helfen.\n\nWie ich sehe, ist auch Colin Donnermar eingetroffen. Unser Gipfeltreffen kann beginnen! Bitte, bleibt und seht, wie die Dinge sich entwickeln...", sourceObjectiveStatus = "unverified-source-field" }
quests[28295] = { id = 28295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Karawane treffen", description = "Die Pyramide in der Terrasse des Schöpfers in Uldum kann als eine Art Superwaffe benutzt werden, die alles Leben in Azeroth auslöschen wird.\n\n<Harrison denkt einen Augenblick lang nach.>\n\nIhr müsst Eure Untersuchungen zu Ende führen. Reist ans südliche Ende Kalimdors, zur Tanariswüste. Dort findet Ihr eine Karawane, die nach Uldum aufbrechen wird.\n\nVielleicht könnt Ihr Euch anschließen.", sourceObjective = "Sprecht mit Adarrah in Disteltal in Tanaris.", completion = "Harrison schickt Euch also?\n\nNa so ein Glück!", sourceObjectiveStatus = "unverified-source-field" }
quests[28296] = { id = 28296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Karawane treffen", description = "Die Pyramide in der Terrasse des Schöpfers in Uldum kann als eine Art Superwaffe benutzt werden, die alles Leben in Azeroth auslöschen wird.\n\n<Belloc denkt einen Augenblick lang nach.>\n\nIhr müsst also mit Euren Untersuchungen fortfahren. Reist nach Süden zur Tanariswüste. Dort findet Ihr eine Karawane, die nach Uldum aufbrechen wird.\n\nVielleicht könnt Ihr Euch anschließen.", sourceObjective = "Sprecht mit Adarrah in Disteltal in Tanaris.", completion = "Bellok schickt Euch also?\n\nNa so ein Glück!", sourceObjectiveStatus = "unverified-source-field" }
quests[28297] = { id = 28297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Ormak Grimmschlag", description = "Ich habe eine Schriftrolle von Ormak Grimmschlag aus Orgrimmar erhalten. Er möchte, dass Ihr Euch auf den Weg zum Tal der Ehre begebt und ihn so schnell wie möglich aufsucht. Es klang sehr dringlich, {name}.", sourceObjective = "Sprecht mit Ormak Grimmschlag im Tal der Ehre in Orgrimmar.", completion = "Die Horde benötigt Eure Fähigkeiten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28298] = { id = 28298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Gordul", description = "Gordul, der Anführer der Schurken der Zerschmetterten Hand, möchte Euch treffen. Begebt Euch so schnell wie möglich nach Orgrimmar, {name}, und sucht ihn der Kluft der Schatten auf. Er scheint eine wichtige Aufgabe für Euch zu haben.", sourceObjective = "Sprecht mit Gordul in der Kluft der Schatten in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28299] = { id = 28299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Zevrost", description = "Ich habe soeben eine Nachricht von Zevrost erhalten, dem mächtigsten Lehrer für Hexenmeister. Er wünscht, dass Ihr nach Orgrimmar reist und ihn in der Kluft der Schatten trefft. Es klang, als habe er eine wichtige Aufgabe für Euch.", sourceObjective = "Sprecht mit Zevrost in der Kluft der Schatten in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28300] = { id = 28300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Ureda", description = "Ich habe eine Schriftrolle aus Orgrimmar für Euch, {name}. Sie ist von Ureda, eine der Magierlehrerinnen. Sie möchte, dass Ihr Euch in der Kluft der Schatten mit ihr trefft, wenn Ihr das nächste Mal in der Stadt seid.", sourceObjective = "Sprecht mit Ureda in der Kluft der Schatten in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28301] = { id = 28301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Kardris Traumsucher", description = "Ich habe eine wichtige Nachricht für Euch erhalten, {name}. Sie ist von Kardris Traumsucher, einer Schamanenlehrerin aus Orgrimmar. Sie möchte, dass Ihr Euch so schnell wie möglich ins Tal der Weisheit in Orgrimmar begebt und dort mit ihr sprecht.", sourceObjective = "Sprecht mit Kardris Traumsucher im Tal der Weisheit in Orgrimmar.", completion = "Wir leben in gefährlichen Zeiten, {name}. Die Horde kann sich glücklich schätzen, dass eine {race} wie Ihr in ihren Reihen kämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[28302] = { id = 28302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Sonnenläufer Atohmo", description = "Ihr solltet so schnell wie möglich nach Orgrimmar aufbrechen, {name}. Sonnenläufer Atohmo hat Kunde geschickt, dass er Euch in einer wichtigen Angelegenheit der Horde sprechen möchte. Sucht ihn im Tal der Weisheit auf.", sourceObjective = "Sprecht mit Sonnenläufer Atohmo im Tal der Weisheit in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28303] = { id = 28303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Meister Pyreanor", description = "Meister Pyreanor hat Euch eine wichtige Nachricht zukommen lassen, {name}. Er bittet Euch, ihn in der Feste Grommash im Tal der Stärke aufzusuchen, wenn Ihr das nächste Mal in der Stadt seid. Es klang, als habe er eine wichtige Aufgabe für Euch.", sourceObjective = "Sprecht mit Meister Pyreanor in der Feste Grommash in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28304] = { id = 28304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft die dunkle Klerikerin Cecille", description = "Die dunkle Klerikerin Cecille, eine Angehörige der Delegation der Bansheekönigin in Orgrimmar, hat darum gebeten, dass Ihr sie bei Eurem nächsten Besuch in der Stadt trefft. Sie ist in der Feste Grommash im Tal der Stärke in Orgrimmar. Es muss sich um eine wichtige Angelegenheit handeln, wenn sie direkt nach Euch schickt.", sourceObjective = "Sprecht mit der dunklen Klerikerin Cecille in der Feste Grommash im Tal der Stärke in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28305] = { id = 28305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal Blutgiftpostens", description = "Während wir uns um Jaedenar gekümmert haben, ist eine Freundin von mir zum Blutgiftposten aufgebrochen. Wir hatten früher unregelmäßige Besuche von den Tauren von dort, aber in letzter Zeit haben wir von ihnen nichts mehr gehört.\n\nKelnir Blattlied ist noch nicht zurückgekehrt. Könntet Ihr nach Norden reisen, um nach ihr zu suchen und die Lage in Blutgiftposten erkunden?\n\nWenn Ihr Kelnir finden solltet, müsst Ihr achtsam sein... Dryaden wie sie werden von vielen anderen Völkern als seltsam empfunden.", sourceObjective = "Sprecht mit Kelnir Blattlied beim Blutgiftposten.", completion = "Oh, hi! Hat Farlus Euch geschickt? Wie schön, dass er sich daran erinnert hat!\n\nBlutgipfelposten ist voll und ganz von diesen furchtbaren Schleimdingern überfüllt und dieser arme Tauren hier ist der Einzige, der noch übrig ist! Wir müssen ihm helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28306] = { id = 28306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wisperwindhain", description = "Ihr wart hier so eine große Hilfe!\n\nIch werde hier bleiben und mich um den armen Herrn Tauren kümmen, bis er sich nicht mehr ganz so oft übergibt. Warum geht Ihr solange nicht nach Wisperwindhain? Da ist es wirklich schön, und alle Druiden sind richtig nett!\n\nBitte richtet Frau Purhain aus, dass es mir gut geht. Sie soll sich keine Sorgen machen, wenn ich mal länger weg bin. Vielleicht wird sie Euch bitten, ihr mit den Blumen zu helfen. Das macht soo viel Spaß!", sourceObjective = "Sprecht mit Hüterin Purhain in Wisperwindhain.", completion = "Kelnir? Hahaha...\n\nManchmal frage ich mich, ob ihr Geschwätz der Grund für das Verschwinden der anderen Dryaden war. Aber ich bin froh, dass es ihr gut geht.\n\nWillkommen in Wisperwindhain, {class}. Wenn Ihr Frieden im Herz habt, so kann Euch Wisperwindhain eine gute Heimat sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[28307] = { id = 28307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Tyelis", description = "Tyelis, ein Mitglied der Delegation Silbermonds in Orgrimmar, hat Euch zu einem Treffen aufgefordert, wenn Ihr das nächste Mal in der Stadt seid. Ihr könnt ihn in der Feste Grommash in Orgrimmars Tal der Stärke finden. Es muss eine wichtige Angelegenheit sein, wenn er Euch so direkt auffordert, {name}.", sourceObjective = "Sprecht mit Tyelis in der Feste Grommash im Tal der Stärke in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28308] = { id = 28308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Seherin Liwatha", description = "Seherin Liwatha schickt ihre Grüße aus dem Tal der Weisheit in Orgrimmar, {name}. Sie hat mich gebeten, eine Einladung für Euch auszusprechen. Sie möchte, dass Ihr sie besucht, wenn Ihr das nächste Mal in der Stadt seid. Es klang, als habe sie ein wichtiges Anliegen mit Euch zu besprechen.", sourceObjective = "Sprecht mit Seherin Liwatha im Tal der Weisheit in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28309] = { id = 28309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Schattenläufer Zuru", description = "Schattenläufer Zuru, ein angesehener Priesterlehrer, hat um ein Treffen mit Euch in Orgrimmar gebeten. Ihr könnt ihn im Tal der Geister bei den anderen Lehrern vom Stamm der Dunkelspeere finden. Es muss sehr wichtig sein, wenn sie so direkt nach Euch schickt, {name}.", sourceObjective = "Sprecht mit der dunklen Klerikerin Cecille in der Feste Grommash im Tal der Stärke in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28310] = { id = 28310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgans Wacht", description = "Unsere Arbeit hier in Meißelgriff ist abgeschlossen; in erster Linie, weil Ihr uns geholfen habt. Nun werden wir uns in Richtung Osten begeben, zu Morgans Wacht.\n\nWir wurden informiert, dass Morgans Wacht leersteht, weil die meisten Einwohner zum Schwarzfels gezogen sind, um ihren Kampf gegen die Orcs des Schwarzfelsklans zu führen. Morgans Wacht sollte ein guter Operationspunkt für die letzten Phasen unseres Vorhabens sein.\n\nNatürlich wird Keeshan Euch begleiten. Und ich auch.", sourceObjective = "Meldet Euch bei Oralius in Morgans Wacht in der Brennenden Steppe.", completion = "Ihr seid angekommen! Und gerade rechtzeitig zur Freundschaftszeremonie!\n\n<Oralius blickt wehmütig über seine Schulter zu dem Ogerkopf und verfällt in Panik.>\n\nHauptmann Winky! Wo ist Hauptmann Winky hin?\n\nOh, bitte, sagt nicht, dass er kalte Füße bekommen hat!", sourceObjectiveStatus = "unverified-source-field" }
quests[28311] = { id = 28311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschwärzte Asche", description = "Ihr müsst für mich noch etwas besorgen, bevor wir uns dem Rest der Schwarzfelsarmee annehmen können. Wenn wir das hier tun wollen, sollten wir es richtig tun, und das bedeutet, dass wir uns vorbereiten müssen.\n\nIch brauche Asche, {name}. Nicht irgendwelche Asche... Asche von den großen Obsidianelementaren, die sich in den Ebenen im Nordwesten aufhalten. Das Zeug ist tiefschwarz, und genau das brauchen wir für unsere nächste Verkleidung.\n\nKeine Sorge, Ihr habt schon eine Verkleidung. Diese ist für jemanden... naja, für ETWAS... anderes.", sourceObjective = "Sammelt 9 Haufen Obsidianasche.", progress = "Die Asche der Obsidianelementare ist besonders dunkel - und genau, was wir für unser Vorhaben benötigen.", completion = "Ja, die sind gut genug. Ich werde sie für Euch schön einpacken.", sourceObjectiveStatus = "unverified-source-field" }
quests[28312] = { id = 28312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlafende Dämonen des Landes", description = "Die Lavaseen westlich von hier sind die Heimat der Flammkin, eine besondere Art Feuerdämonen, die die Steppe schon lange beheimaten. In der Schwarzfelsarmee sieht es so aus, als könnten wir - wenn wir vorsichtig genug sind - ein paar der Flammkin hinter die feindlichen Linien schmuggeln, um für Verwüstung zu sorgen.\n\nBringt mir die Leichen von mehreren Flammkin. Als Dämonen kann man sie leicht wiederbeleben, und dann für seine eigenen Zwecke einsetzen.", sourceObjective = "Sammelt 18 gefallene Flammkin.", progress = "Die Flammkin sind schwach, aber sie reisen in Rudeln. Seid vorsichtig.", completion = "Für das ungeübte Auge sehen sie aus wie Wichtel.\n\nWir müssen sie nur diesem eben ungeübten Auge unterjubeln. Ich werde sie jetzt für den Einsatz vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28313] = { id = 28313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein köstlicher Haufen Worg", description = "Wir brauchen frisches Fleisch und deshalb werdet Ihr Euch auf die Worgjagd machen. Die Worgs auf dieser Seite der Steppe sollten die sein, auf die Ihr Euch bei der Jagd konzentriert.\n\n<Trottmann holt eine große Klinge hervor und händigt sie Euch aus.>\n\nMacht Jagd auf die riesigen Glutworgs. Benutzt diese Säge, um die besten Fleischstücke aus den frisch getöteten Worgs zu schneiden. Worgs sind überall in der Steppe zu finden; nordöstlich von hier ist gleich das erste Rudel.", sourceObjective = "Benutzt die Worgsäge, um aus den frisch getöteten riesigen Glutworgs 40 Worgschnitzel zu schneiden.", progress = "Glück bei der Jagd gehabt?", completion = "Das Fleisch sieht gut aus... aber ich glaube, wir müssen es noch ein bisschen \"würzen\". Ich werde sicherstellen, dass sich jemand darum kümmert.\n\nVielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28314] = { id = 28314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutrunde", description = "Meine Beine werden schon wieder ein wenig rastlos. Habt Ihr Lust, eine kleine Runde zu drehen, {name}?\n\nWir werden uns auf eine Reise um den Schreckensfels begeben. Ich möchte die Schwarzfelsarmee erst ein wenig unter die Lupe nehmen, bevor wir zuschlagen. Da dachte ich mir, wir könnten auch ein paar von ihnen töten, wenn wir schon auf dem Weg sind.", sourceObjective = "Tötet 25 schwarze Großdrachenbrut oder Schwarzwyrmkin.", completion = "<Keeshan trieft vor Blut und Schweiß.>\n\nGenau das hatte ich im Sinn!", sourceObjectiveStatus = "unverified-source-field" }
quests[28315] = { id = 28315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenvorhut", description = "Die Schwarzfelsorcs kommen nicht allein. Die Oger der Feuermägen und Trolle der Gluthauer, die an ihrer Seite kämpfen, habt Ihr bereits gesehen. Leider haben sie aber auch die schwarzen Großdrachen auf ihrer Seite.\n\nDie Orcs und Drachen haben bereits ihre Champions zu Sammelpunkten geschickt, um Wache zu stehen. Ihr könnt sie an den Drachenschädeln auf Piken erkennen, die herumstehen. Wir beide werden diese Sammelpunkte finden und die Vorposten ausschalten, bevor die Schlacht beginnt.\n\nSeid Ihr bereit?", sourceObjective = "Tötet Minyoth, Welpenbändigerin Akumi, Terromath den Versengten und Tugnar Blutschlund.", progress = "Kommt schon, {name}, es sind noch ein paar von ihnen übrig. Unsere Arbeit ist noch nicht erledigt.", completion = "Ihr werdet immer besser, {name}! Jetzt fallen sie, so wie wir es wollten.\n\nUnd wir werden siegen. Das Rotkammgebirge wird NIEMALS diesen Feiglingen gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[28316] = { id = 28316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Handel mit einem Drachen", description = "Auf unserer Reise um den Schreckensfels gibt es noch einen Zwischenstopp.\n\nErinnert Ihr Euch noch an die Brutlinge, die Ihr aus den Schlupfhügeln befreit habt? Trottmann hat sich um sie gekümmert. Jetzt werden wir sie zu jemandem bringen, der besser für sie sorgen kann als wir. Er hält sich am Schlitterfels auf, nordöstlich des Schreckensfels.\n\nSein Name ist Acride. Er ist vielleicht der Schlüssel zum Sieg in der bevorstehenden Schlacht.", sourceObjective = "Bringt die geretteten Welplinge zu Acride im Schlitterfels in der Brennenden Steppe.", progress = "Da seid Ihr ja, {name}.", completion = "Ja, die Welplinge. Ich werde mich um sie kümmern.\n\nUnd was die Vereinbarung angeht, die ich zuvor mit Eurem Oberst Trottmann getroffen habe, sagt ihm, dass ich meinen Teil des Handels erfüllen werde. Ich werde Euch Euren Drachen für die Schlacht gegen die Orcs schicken.\n\nWir hegen zwar keine Sympathien für das Rotkammgebirge, aber wir teilen Eure Verachtung dem Schwarzfelsklan gegenüber.", sourceObjectiveStatus = "unverified-source-field" }
quests[28317] = { id = 28317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lieferung für Thorg'izog", description = "General Thorg'izog ist bei den Ogern im Ofen der Feuermägen, eine Höhle in der Westwand des Schreckensfels. Bringt diese Lieferung zu ihm und den Ogern.\n\nDarin befinden sich die Worgschnitzel, die Ihr besorgt habt. Sie wurden in dem Teufelskarussellstöffsche mariniert, das wir vom Altar der Stürme erhalten haben.\n\nIhr solltet nichts davon essen, wenn es Euch irgendwie möglich ist.\n\nBringt die Schnitzel zu General Thorg'izog. Er wird sich darum kümmern, dass seine Streitmächte Essen im Magen haben und mit ein bisschen Glück isst er auch etwas davon.", sourceObjective = "Tragt Eure Schwarzfelsverkleidung und bringt die in Karussellstöffsche marinierten Schnitzel zu General Thorg'izog im Ofen der Feuermägen in der Brennenden Steppe. Sprecht mit Oberst Trottmann, wenn Ihr eine neue Schwarzfelsverkleidung braucht.", progress = "Was habt Ihr da, Soldat?", completion = "Nun seht Euch das an! Jetzt weiß ich, wer mein Lieblingssoldat ist!\n\nIch werde die Schnitzel unter den Ogern verteilen.\n\nIch werde Euch am Rotkamm wieder sehen, Soldat. Für die Ehre des Schwarzfels!", sourceObjectiveStatus = "unverified-source-field" }
quests[28318] = { id = 28318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lieferung für Neeralak", description = "Die Hexenmeister des Schwarzfelsklans üben ihre Magie oft in der Schädelhöhle östlich des Schreckensfels. Ihr Anführer Xi'lun ist gerade andernorts beschäftigt, sodass die Höhle derzeit von einem anderen der großen Drei beaufsichtigt wird: Drachenlord Neeralak. Neeralaks Fachgebiet sind Drachen, nicht die Totenbeschwörung.\n\nIch habe die Flammkin, die Ihr gefangen habt, mit dem Schlummersand bestreut. Überzeugt Neeralak davon, dass es sich dabei um Hexenmeisterwichtel handelt, nicht um Flammkin. Wenn sie aufwachen, werden sie alles andere als glücklich sein.", sourceObjective = "Legt Eure Schwarzfelsverkleidung an, schleicht Euch in die Schädelhöhle und überzeugt Drachenlord Neeralak, Eure Kiste voller schlafender Flammkin anzunehmen. Sprecht mit Oberst Trottmann, wenn Ihr eine neue Schwarzfelsverkleidung benötigt.", progress = "Was?", completion = "Was soll das sein? Aha, das sind also Wichtel?\n\nIch bin mir sicher, dass Wichtel nicht einfach so in Kisten schlafen!\n\nAber ich nehme Euch beim Wort. Ich verstehe nichts von diesem Hexenmeisterquatsch. Stellt sie in der Ecke ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[28319] = { id = 28319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lieferung für Xi'lun", description = "Man hat uns berichtet, dass der oberste Hexenmeister Xi'lun, das letzte Mitglied der großen Drei, sich in einer Höhle auf dem Gipfel des Schreckensfels aufhält und seinen großen Augenblick vorbereitet.\n\nEr erwartet eine Lieferung: eine Kugel der Herrschaft, mit der er ein mächtiges Beschwörungsritual durchführen kann. Ich möchte, dass Ihr ihm das hier gebt.\n\n<Trottmann reicht Euch eine Glaskugel.>\n\nDies ist die klare Glaskugel, die Ihr aus dem Altar der Stürme befreit habt. Sie ist machtlos. Gebt sie Xi'lun und betet, dass er den Unterschied nicht bemerkt.", sourceObjective = "Legt Eure Schwarzfelsverkleidung an und bringt die klare Glaskugel zum obersten Hexenmeister Xi'lun auf dem Schreckensfels in der Brennenden Steppe.", progress = "Ich habe keine Zeit für Spielchen, Narr. Geht mir aus den Augen.", completion = "Pff! Ihr seid spät dran! Wisst Ihr, wie lange ich schon warte, dass Ner'gosh mir endlich diese Kugel bringt?\n\n<Xi'lun schaut auf die Kugel, dann wieder zu Euch.>\n\nEtwas ist merkwürdig an dieser Kugel... Sie ist zu...\n\n<Xi'lun verstummt.>\n\nAch, schon gut. Meine Nerven liegen wohl einfach blank. Vielen Dank für die Lieferung. Für Blut und Donner!", sourceObjectiveStatus = "unverified-source-field" }
quests[28320] = { id = 28320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Schreckensfels", description = "Das ist es also, {name}! Hier soll es geschehen. Hier fügen sich alle Teile zusammen.\n\nSchnallt Euch an und kommt mit mir. Wir werden mit Acride sprechen und den Gefallen einfordern, den er uns schuldet. Dann werden wir die Invasion im Rotkammgebirge aufhalten, bevor sie überhaupt begonnen hat.", sourceObjective = "Tötet 200 Eindringlinge des Schwarzfels. Wenn Ihr Euer Fahrzeug verlieren solltet, benutzt das Horn der Rufer, um es herbeizurufen.", completion = "Habt Ihr gesehen, wie sie gerannt sind? Sie hatten keine Ahnung, wie ihnen geschieht! Wunderbar!\n\nUnsere Aufgabe ist fast erledigt, {name}. Es ist Zeit, ihnen den Todesstoß zu versetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28321] = { id = 28321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruhm im Chaos", description = "Ihr und Keeshan geht zurück zu diesem Berg. Drei Orcs haben den Angriff überlebt, und wir geben keine Ruhe, bis sie den Tod gefunden haben.\n\nGenau, ich spreche von den großen Drei.\n\nGeneral Thorg'izog ist in den Ofen der Feuermägen gekrochen und Drachenlord Neeralak hat sich in der Höhle auf dem Berggipfel verschanzt. Xi'lun hält sich im hinteren Teil der Schädelhöhle auf und schmiedet Pläne mit seinen Hexenmeisterfreunden.\n\nMacht Euch einen Namen, {name}. Jagt diese Jammerlappen des Schwarzfels und zeigt ihnen die Macht des Rotkammgebirges!", sourceObjective = "Tötet General Thorg'izog, Drachenlord Neeralak und oberster Hexenmeister Xi'lun.", progress = "Viel Glück, Soldat.", completion = "<Oberst Trottmann strahlt vor Freude.>\n\nWillkommen daheim, Jungs.", sourceObjectiveStatus = "unverified-source-field" }
quests[28322] = { id = 28322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsbeute", description = "Wir haben heute einen Riesen überwältigt, {name}. Die Schwarzfelsorcs schwirren zwar immer noch im Berg herum, aber ich bezweifle, dass ihre Pläne sie in nächster Zeit auch nur in die Nähe des Rotkammgebirges führen. Das habt Ihr und Keeshan ihnen sicher ausgetrieben.\n\nIch muss sagen, dass wir hier in der Brennenden Steppe nicht mit Einfallsreichtum gegeizt haben. Diese Hexenmeisterausrüstung, die wir gesammelt haben, war äußerst praktisch, und auch die Obsidianasche, mit der wir unseren Drachen versteckt haben, war ein cleverer Schachzug.\n\nWir haben jedoch noch ein paar Gegenstände übrig. Bitte, sucht Euch etwas aus, bevor Ihr die Steppe wieder verlasst und weiterzieht.", sourceObjective = "Untersucht die Kiste mit übriggebliebenen Vorräten in Morgans Wacht in der Brennenden Steppe.", completion = "Ihr schaut hinein und findet...", sourceObjectiveStatus = "unverified-source-field" }
quests[28323] = { id = 28323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Treffen mit Bruder Silberheil", description = "Bruder Silberheil wünscht Euch zu sprechen. Wenn Ihr das nächste Mal in Orgrimmar seid, sucht ihn in den Goblinslums auf. Es klang, als hätte er etwas Wichtiges mit Euch zu bereden.", sourceObjective = "Sprecht mit Bruder Silberheil in den Goblinslums von Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[28324] = { id = 28324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Studien der Tödlichkeit", description = "Wir haben einen ziemlich mächtigen Erregerstamm der Seuche gegen die Menschen in Süderstade eingesetzt. Und wie Ihr seht hat es wunderbar funktioniert. Das Problem beim Einsatz der Seuche ist jedoch, dass sie nachdem sie ihren Zweck erfüllt hat nicht so einfach verschwindet.\n\nIch möchte, dass Ihr diese Testausrüstung nehmt und eine Tödlichkeitsanalyse an dem Seuchenschlamm vornehmt, den wir in der Gegend ausgesetzt haben. Benutzt den Tödlichkeitsanalysator am Seuchenschlamm, der in den Schleimpfützen umherschleimt. Kehrt zu mir zurück, wenn Ihr ein paar handfeste Daten gesammelt habt.", sourceObjective = "Sammelt 250 Seuchenproben.", completion = "Oh je. 250? Dieses Ding zeigt maximal 250 an. Ihr habt Glück, dass Ihr noch steht. Ihr solltet eigentlich schon längst zu einer Schleimpfütze zerflossen sein. Diese Nachrichten werden Sylvanas gar nicht gefallen. Vielleicht können wir innerhalb von ein paar Jahrzehnten die Tödlichkeitswerte in dieser Gegend verringern, aber dann geraten wir immer noch etwa hundert Jahre ins Hintertreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28325] = { id = 28325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Denkt grün!", description = "Recycling! Das ist in letzter Zeit in aller Munde. Die Bansheekönigin hat befohlen, dass wir Ressourcen schützen müssen, wenn wir als Volk erblühen wollen. Und jeder muss schließlich seinen Teil beitragen, nicht wahr? Also werdet Ihr unseren Teil für uns erledigen.\n\nEs liegen bestimmt Tausende von Seuchenkanisterteilen in ganz Süderstade verstreut. Wir können diese Kanister gut für weitere aufregende Seuchenangriffe nutzen. Geht einfach in die Ruinen hier und nehmt alles mit, was Ihr finden könnt.", sourceObjective = "Sammelt 8 gebrauchte Seuchenkanister.", progress = "Bringt mir diese Kanister!", completion = "Ausgezeichnete Arbeit, {name}. Ihr seid unglaublich widerstandsfähig gegenüber dieser Seuche. Wir müssen bei Gelegenheit einmal ein paar Tests an Euch durchführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28326] = { id = 28326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstellung der Bauern", description = "{name}. Ihr und Keeshan scheint Eure Aufgaben erledigt zu haben. Ich bin ebenfalls mit meiner fertig.\n\nKehrt zu Morgans Wacht zurück. Ich habe ein paar Pakete für die großen Drei vorbereitet: Thorg'izog, Neeralak und Xi'lun. General Thorg'izog habt Ihr ja schon getroffen. Jetzt habt Ihr die Gelegenheit, auch den anderen beiden zu begegnen.\n\nBevor wir sie töten meine ich natürlich.", sourceObjective = "Kehrt zu Oberst Trottmann in Morgans Wacht in der Brennenden Steppe zurück.", completion = "Gut, Ihr seid zurück.\n\nIch hoffe, Ihr habt die Verkleidung noch. Ihr werdet Euch wieder mitten unter die Feinde begeben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28327] = { id = 28327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geladen und entsichert", description = "{name}, bitte melden. Könnt Ihr mich hören?\n\nDie Schlacht beginnt gleich. Ich hoffe, Ihr habt alle Pakete ausgeliefert.\n\nIch brauche Euch hier in Morgans Wacht, SOFORT.", sourceObjective = "Meldet Euch bei Oberst Trottmann in Morgans Wacht in der Brennenden Steppe.", completion = "{name} ist da! Wir können loslegen.\n\nDas ist der Moment, auf den wir gewartet haben, {name}. Ich hoffe, Ihr seid in Bestform.", sourceObjectiveStatus = "unverified-source-field" }
quests[28328] = { id = 28328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtränke", description = "Der Einfluss des Schattenhammers reicht weit. Sie sind unablässig auf der Suche nach Verbündeten in ihrer Schlacht gegen uns und rekrutieren jetzt sogar die Dunkeleisenzwerge der Schwarzfelstiefen für ihre Sache.\n\nMoira hat die Dunkeleisenzwerge nur dürftig im Griff. Jeden Tag wenden sich mehr und mehr ihrer Leute von ihrer Herrschaft ab. Wir müssen ihre Rekrutierung sabotieren.\n\nIch möchte, dass Ihr in das Domizil der Schwarzfelstiefen geht und diese Fackel benutzt, um die Bücher zu verbrennen, die der Schattenhammer dort verteilt.", sourceObjective = "Benutzt die leuchtende Fackel, um 8 Abschriften des Glaubensbekenntnisses des Schattenhammers im Domizil der Schwarzfelstiefen zu zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[28329] = { id = 28329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Böser Schlamm! Böser Schlamm!", description = "Dieser Seuchenschlamm scheint wirklich wütend zu sein. In seinem Ektoplasma kann man sogar ganz schwach die Konturen eines wütenden humanoiden Gesichts sehen. Hinott wäre sicher nicht allzu erfreut, wenn seine Schleimpfützen mit unkooperativem Schlamm übersät sind.\n\nTötet den wütenden Seuchenschlamm und versucht, einer ihrer Brutpfützen Herr zu werden.", sourceObjective = "Tötet 5 wütende Seuchenschlamme.", sourceObjectiveStatus = "unverified-source-field" }
quests[28330] = { id = 28330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreckige Spuren", description = "Die Spur aus Dreck und Wut führt in die Ruinen des Rathauses. Sicherlich befindet sich eine Brutpfütze in dem Gebäude. Kämpft Euch hinein und macht kurzen Prozess mit dem wütenden Schleimzüchter, den Ihr dort findet!\n\nWenn Ihr Erfolgt habt, solltet Ihr Serge Hinott in den Ruinen von Süderstade unbedingt davon berichten.", sourceObjective = "Tötet Chet den Schleimzüchter.", completion = "Jetzt, da Chet vernichtet ist, sinken die Tödlichkeitswerte an diesem Ort vielleicht schneller. Gute Arbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[28331] = { id = 28331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helculars Rute gibt...", description = "Kaum vorstellbar, dass ich, Meister der Totenbeschwörung und Schüler Kel'Thuzads selbst, nur noch eine Leiche in einem Grab sein sollte! Zum Glück fand mein geistreicher Novize Thaivand eine Gruppe von Helden, die das hier wiederbeschafft haben:\n\n<Helcular zieht seine Rute hervor.>\n\nDurch die Macht der Rute konnte ich wiedergeboren werden. Die Rute gibt und die Rute nimmt!\n\nNun benutzt sie, um unsere dunklen Waldläuferinnen zu stärken, die sich auf dem Feld nördlich von uns eine Schlacht mit den Worgen liefern. Erneuert ihre Lebenskraft mit meiner Rute.", sourceObjective = "Benutzt Helculars Rute, um 8 dunkle Waldläuferinnen zu stärken.", completion = "Wie ich sagte, die Rute gibt unseren dunklen Waldläuferinnen und nimmt von unseren Feinden!", sourceObjectiveStatus = "unverified-source-field" }
quests[28332] = { id = 28332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helculars Befehl", description = "Unsere dunklen Waldläuferinnen suchen die Felder nach Attentätern der Worgen ab. Diese Worgen wurden von ihren dunklen Meistern ausgesandt, um uns zu jagen und zu töten. Und obwohl unsere dunklen Waldläuferinnen ausgezeichnete Kämpferinnen sind, greifen die Worgen oft in Rudeln an, denen nicht einmal die stärkste Waldläuferin standhalten kann.\n\nDurchkämmt die Ruinen von Süderstade nach Blutfangverlassenenjägern. Tötet alle, die Ihr finden könnt! Für die Verlassenen und für Lordaeron!", sourceObjective = "Tötet 15 Blutfangverlassenenjäger.", completion = "Wir hätten Blutfang im Silberwald töten sollen. Es ist eine Schande, dass er noch am Leben ist. Und es ist noch eine größere Schande, dass wir bis jetzt noch keine Worgen in Untote verwandeln konnten. Es muss doch einen Weg geben...", sourceObjectiveStatus = "unverified-source-field" }
quests[28333] = { id = 28333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie geschmiert", description = "Aus der Eisenwaldlichtung kommen drei Dinge: Holz, Öl und müde Arbeiter. Die ersten beiden Dinge sind der Grund für Letzteres, aber ich möchte so effizient wie möglich arbeiten.\n\nUnsere Schredder machen dreifache unbezahlte Überstunden. Im Zeitplan ist einfach kein Platz für Wartungsarbeiten.\n\nBenutzt diesen Enterhaken, um Euch ein paar der schwebenden Ölkannen aus dem Lager zu beschaffen und die Schredder zu schmieren, ja?", sourceObjective = "Benutzt Darlas Enterhaken, um Ölkannen aus dem Eisenwald zu sammeln, und benutzt sie, um 7 Eisenwaldschredder zu schmieren.", completion = "Effiziente Arbeitskraft! Wunderbar.\n\nVielleicht sollte ich später mal nach den Goblins in den Schreddern sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28334] = { id = 28334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da geht Euch ein Licht auf", description = "Unser Werk hier erfreute sich bisher höchster Diskretion, aber die Worgen drüben in der Nachtlaublichtung sitzen uns im Nacken. Sie haben alles in ihrer Macht Stehende versucht, um uns den Hahn abzudrehen.\n\nEinige meiner Arbeiter haben berichtet, dass sie auf der Lichtung Worgen vorbeihuschen sahen. Nehmt diese übergroßen Megaleuchtfeuer. Sie sind hell genug, um alles in ihrer Nähe sichtbar zu machen.\n\nBenutzt die Leuchtfeuer, um streunende Worgen ausfindig zu machen. Stellt sicher, dass sie diesen Ort nicht lebend verlassen!", sourceObjective = "Benutzt Darlas Kiste mit Megaleuchtfeuern, um 8 Nachtlaubstreuner zu enttarnen, und tötet sie.", completion = "Diese verfilzten Köter denken, sie könnten einfach so hier hereinmarschieren und meine exakt geplante Unternehmung zunichtemachen. Hah!\n\nIch hab Euch doch gesagt, dass Ihr nicht direkt in das Leuchtfeuer schauen sollt, oder? Ups.", sourceObjectiveStatus = "unverified-source-field" }
quests[28335] = { id = 28335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausschalten! Ausschalten!", description = "Das waren diese verdammten Worgen! Sie sind direkt an mir vorbei in die Höhle geschossen.\n\nBestimmt haben sie sich an der Hauptkontrollpumpe zu schaffen gemacht. Wenn das Ding zu lange eingeschaltet bleibt, wird jedes einzelne Rohr unter unseren Füßen in die Luft fliegen! Ihr findet die Lecks schon schlimm? Na dann wartet mal ab!\n\nHört zu, wenn Ihr zur Hauptkontrollpumpe ganz hinten in der Höhle gelangt, könnt Ihr sie ausschalten und uns alle retten!", sourceObjective = "Schaltet die Hauptkontrollpumpe tief in der Eisenwaldhöhle aus.", completion = "Ihr legt den größten Hebel der Hauptkontrollpumpe um, den Ihr finden könnt, und das Klappern in den Rohrleitungen verstummt.\n\nIn dem Moment der Stille hört Ihr von draußen Flammen und eine vertraute Stimme, die aus einem blechernen, kratzenden Lautsprecher erklingt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28336] = { id = 28336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Backpfeifen für die Pfeifen", description = "Ach zum... nicht schon wieder! Wenn Ihr den Stellvertreter da draußen habt schreien hören, haben wir es mit einem ausgewachsenen Ölleck zu tun! Das waren schon wieder diese verdammten Worgen!\n\nHört zu, da draußen wird das reinste Chaos herrschen. Übermüdete Goblins werden schreiend durcheinander rennen und nicht wissen, was sie tun sollen. Ihr müsst die Arbeiter wieder zur Vernunft bringen.\n\nEine kräftige, schnelle Ohrfeige mitten ins Gesicht sollte Wunder wirken. Sobald sie wieder bei Sinnen sind, werden sie an die Arbeit gehen und die Ölspritzer abdichten.", sourceObjective = "Ohrfeigt 7 panische Arbeiter, damit sie die Ölspritzer abdichten.", completion = "Es funktioniert nicht! Wir müssen die Quelle ausschalten.\n\nSprecht sofort mit dem Stellvertreter. Er wird Euch alles erklären!", sourceObjectiveStatus = "unverified-source-field" }
quests[28337] = { id = 28337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Eisenwaldschredder", description = "Widerlich, oder? Schaut sie Euch nur an. Erbärmliche kleine Wesen, die nicht einmal mit ihrem eigenen Körper schuften können.\n\nSie walzen mit ihren massiven Metallschreddern einfach alles platt und verwandeln den Wald in Sägemehl. Bestimmt glauben sie, dass sie in den Dingern sicher sind, so warm und geborgen.\n\nBeweist ihnen das Gegensteil. Fegt nach Norden durch das Lager und zerstört so viele Schredder, wie Ihr könnt. Sobald Ihr ein wenig Blut vergossen habt, werden wir diesen Ort ein für alle Mal auseinandernehmen.", sourceObjective = "Zerstört 9 Eisenwaldschredder.", completion = "Das war nur unser erster Schlag.", sourceObjectiveStatus = "unverified-source-field" }
quests[28338] = { id = 28338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totenwaldfelle des Nordens", description = "Direkt südwestlich von hier befindet sich ein Lager der Furbolgs der Totenwaldfelle. Das Lager ist von der Verderbnis durchzogen, und ich möchte dem ein Ende setzen, bevor es noch zu einem echten Problem wird.\n\nDie Totenwaldfelle sind böse, doch es sind die Auswirkungen der Verderbnis, die ihren Geist vernebeln. Sie sind nicht von Geburt an so feindselig und dennoch gibt es kein Heilmittel für sie. Es schmerzt mich, dass wir unsere eigenen Brüder bekämpfen müssen.\n\nBitte, {name}. Ich verlange etwas von Euch, das getan werden muss. Erspart mir einfach die Einzelheiten. Diese schrecklichen Bilder würden mich zu sehr in Aufruhr versetzen.", sourceObjective = "Tötet 15 Furbolgs der Totenwaldfelle im Revier der Teufelspfoten.", completion = "Ich spüre, dass Ihr einen Sieg errungen habt. Sieg... Welch schalen Nachgeschmack hinterlässt dieses Wort in Anbetracht der grausamen Aufgabe, die Ihr erledigen musstet. Dennoch habt Ihr bewiesen, dass Ihr unseres Vertrauens würdig seid.\n\nEs mag vielleicht ein wenig dauern, bis die Furbolgs der Holzschlundfeste Euch mit Freundlichkeit willkommen heißen. Doch wenn Ihr Euch weiter bemüht, wird der Argwohn meiner Brüder Euch gegenüber sicher schnell dahinschmelzen. Solange Ihr uns nicht verratet oder die Waffen gegen uns erhebt, werden wir uns sicher einigen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[28339] = { id = 28339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das läuft weg wie Öl", description = "Das letzte Mal, als wir hier so ein schlimmes Ölleck hatten, hat das Öl selbst versucht auszubüxen.\n\nIch weiß nicht, was der Grund dafür ist. Vielleicht ist es der ganze Dämonenschlamm, der hier herumschleimt. Wenn wir ein großes Leck haben, rottet sich jedenfalls das halbe Öl zusammen und versucht zu flüchten.\n\nDas ist bares Gold, was da auszubrechen versucht! Verfolgt diesen öligen Schlick und bringt mir mein wundervolles, teures Öl zurück!", sourceObjective = "Sammelt 10 Rohteerklumpen von öligem Schlick.", progress = "Das Zeug sollte sich besser nicht mehr bewegen, wenn Ihr es hierher zurückbringt.", completion = "Welch ein Glück! Mein Öl ist in Sicherheit! Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28340] = { id = 28340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Bombengeschäft", description = "Alle meine Arbeiter wurden von diesen großen Sumpfdingern aus der Höhle vertrieben! Darla hat mich hierher geschickt, um die Reste aufzusammeln, aber habt Ihr gesehen, wie es da drin ausschaut? Ich gehe da nicht rein!\n\nWir haben eine Unmenge von Sprengstoff zurückgelassen, auf den wir einfach nicht verzichten können.\n\nIch schlage Euch ein Geschäft vor: Ihr begebt Euch dort hinein und sammelt den Sprengstoff und ich bleibe hier und werde nicht von den Sumpfdingern getötet. Und wenn Ihr es auch heil hinaus schafft, dann bezahle ich Euch! Wie findet Ihr das?", sourceObjective = "Sammelt 8 Stück Eisenwaldsprengstoff aus der Eisenwaldhöhle.", progress = "Wir hatten eine Abmachung, oder? Oder?", completion = "Hui, super! Ich nehme Euch das hier ab... vorsichtig...\n\nVerratet den Arbeitern ja nicht, dass ich nicht den Mumm hatte, selbst hineinzugehen, ja? Hier ist Eure Bezahlung... und noch ein bisschen obendrauf.", sourceObjectiveStatus = "unverified-source-field" }
quests[28341] = { id = 28341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis sammeln", description = "Obwohl wir Druiden die dämonischen Mächte scheuen, die dieses Land heimsuchen, müssen wir uns doch darum kümmern.\n\nDer Narbengrund im Süden ist ganz von der Verderbnis verseucht. Die Energien dort sind so chaotisch, dass sie sich als gewalttätige Wesen manifestieren, reine teuflische Magie, die nach allem Leben trachtet.\n\nIch habe diese chaotischen Wesen genau beobachtet und ihre Stärken untersucht. Ich muss sichergehen, dass sie immer noch mit der Zeit schwächer werden. Bringt mir ihre Essenzen, damit ich sicherstellen kann, dass ihre Zahl sich verringert.", sourceObjective = "Sammelt 8 entropische Essenzen von entropischen Schrecken im Narbengrund.", progress = "Seid vorsichtig mit der Essenz. Sie ist mindestens so gefährlich wie mächtig.", completion = "Allein schon an der Größe der Essenzen kann ich erkennen, dass die teuflische Verderbnis heilt. Langsam... aber merklich.\n\nVielen Dank, {name}. Ich werde sicherstellen, dass diese Exemplare ordnungsgemäß geläutert werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28342] = { id = 28342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fahrt zur Hölle", description = "Die im Narbengrund lauernden Höllenbestien sind stark, aber alles andere als unbesiegbar. Wir haben in letzter Zeit ihre Zahl schon erheblich gemindert.\n\nDoch sie zu vernichten ist nur ein kleiner Schritt zur Lösung des Problems. Ich habe herausgefunden, dass die Steine, aus denen die Höllenbestien bestehen, auch nach ihrem Tod noch große Mengen teuflischer Magie enthalten.\n\nDie Überreste vernichteter Höllenbestien bedecken den Narbengrund und ihre Verderbnis sickert zurück in die Erde. Wenn Ihr sie für mich einsammeln würdet, wäre ich sehr dankbar.", sourceObjective = "Sammelt 9 Einheiten Höllenbestienüberreste im Narbengrund.", progress = "Achtet darauf, auch die Überreste der von Euch besiegten Höllenbestien einzusammeln.", completion = "Schön zu sehen, dass sich jemand darum bemüht, den Wald rein zu halten. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28343] = { id = 28343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Atem des Cenarius", description = "{name}, wir haben erfahren, dass ein verlorengegangenes cenarisches Artefakt sich in den Händen eines Zwielichtpyromanten befindet. Pyromant Weisenkorn hat das Artefakt, den Atem des Cenarius, in die Schwarzfelstiefen gebracht und nutzt dort seine Macht, um Elementartore zu erschaffen.\n\nWir müssen handeln und Weisenkorn davon abhalten, Elementare zu beschwören, mit denen er die Reihen seiner Dunkeleisenverbündeten weiter verstärken kann. Holt das Artefakt von ihm zurück und nutzt seine Macht, um die von Weisenkorn benutzten Tore wieder zu verschließen.", sourceObjective = "Beschafft den Atem des Cenarius von Pyromant Weisenkorn in den Schwarzfelstiefen und benutzt das Artefakt, um 3 Elementartore zu schließen.", progress = "Wir können nicht zulassen, dass die Dunkeleisenzwerge sich mit dem Schattenhammer verbünden.", completion = "Es erfüllt mich mit Zufriedenheit, den Atem des Cenarius wieder dort zu wissen, wo er hingehört. Und ich bin mir sicher, dass der Zirkel von Euren Anstrengungen beeindruckt sein wird. Hinzu kommt, dass Ihr vermutlich sogar die Pläne des Schattenhammerkults ein wenig zurückgeworfen habt. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[28344] = { id = 28344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was zum Lok'tar geht hier ab?", description = "Kurz bevor Ihr hier ankamt traf ein Orc auf einem Frostwyrm ein und verlangte, dass ich ihm zeigen sollte \"wo die Neuen so abhängen\". Unsicher wegen seiner Ausdrucksweise sagte ich ihm, dass er seine Pflicht als Mitglied der Horde erfüllen und sich um die Worgenbedrohung in dieser Gegend kümmern solle. Er murmelte etwas davon, was zum Lok'tar eigentlich abginge und machte sich Richtung Süden zu den Docks auf.\n\nEigentlich kümmert es mich nicht besonders, wenn ein Orc plötzlich verschwindet, aber ich bin doch ziemlich neugierig, was das Abgehen und den Lok'tar betrifft. Findet es heraus.", sourceObjective = "Sucht Orkus den Königsmörder in den Ruinen von Süderstade im Vorgebirge vom Hügelland.", completion = "*KEUCH*\n\nHILFE!\n\nICH ERTRINKE!\n\n*GURGEL*", sourceObjectiveStatus = "unverified-source-field" }
quests[28345] = { id = 28345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "*Gurgel* HILFE! *GURGEL*", description = "*GURGEL*\n\nHILFE! *KEUCH*\n\nORKUS ERTRINKT! HELFT MIR, QUESTGEBER {name}!\n\n*BLUBB*\n\nZwerg hat Orkus ins Wasser geworfen! Darf nicht sterben!\n\n*GURGEL*\n\nDie Schande wäre zu groß.", sourceObjective = "Rettet Orkus den Königsmörder aus dem Wasser.", completion = "<Orkus' Gesicht färbt sich so rot wie seine Rüstung.>\n\nIch... äh... der Mensch muss irgendeinen Beeinflussungszauber auf Orkus gesprochen haben. Orkus erklärt es Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[28346] = { id = 28346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Junggeselle", description = "Das hier muss funktionieren, {name}. Die Antwort liegt im Blut! Familienbande haben die Wildhammerklans einander entfremdet. Ich werde die Familientreue dazu benutzen, um sie wieder zusammenzuschweißen. Es ist ein wagemutiger Versuch, aber wir werden uns als Kuppler betätigen!\n\nIch werde Colin Donnermar ausfindig machen und mit ihm sprechen. Ihr habt ein vertrauenserweckendes Wesen, daher solltet Ihr reingehen und mit Keegan Feuerbart sprechen. Er ist vernünftig genug, um den Wert einer politischen Ehe zu erkennen. Findet heraus, an wem sein Herz hängt!", sourceObjective = "Besprecht mit Keegan Feuerbart die Möglichkeit einer Heirat. Ihr findet ihn in Kirthafen im Schattenhochland.", completion = "Was? Kurdran spricht von Heirat!? Hat er etwa nicht gesehen, wie die alte Donnerfratze und ich uns gerade die Köppe eingeschlagen haben?\n\nDie einzige Donnermar, die in Frage käme, ist Fanny. Sie sieht ja schon gut aus, keine Frage. Alle Kurven am richtigen Platz, wenn Ihr wisst, was ich meine. Aber Ihr fehlt das gewisse Etwas, das ein Feuerbart in einer Frau sucht, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[28348] = { id = 28348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmlanzentreffen", description = "In der Hoffnung, etwas über die Truppenbewegungen der Allianz im Hügelland in Erfahrung zu bringen, habe ich den schwächlichen Nekromanten Helcular aufgesucht.\n\nHelcular hat mich mit dem Aufspüren und Töten von Worgen beauftragt. Normalerweise wäre das eine leichte Aufgabe für Orkus, doch hatte ich gerade mehrere Portionen Dirges abgefahrener Chimaerokkoteletts verschlungen. Das hatte mir ganz schöne Magenschmerzen bereitet. Damit fing der ganze Ärger an und ich endete im Wasser.\n\nHört Orkus an, {name}.", sourceObjective = "Erfahrt etwas über das Sturmlanzentreffen von Orkus.", completion = "Die Rache wird mein sein, doch zuerst müssen wir Kasha heilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28349] = { id = 28349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Megs vom Marketing", description = "Boss, während Ihr unten in den Minen wart, hat Megs Schredderschreck aus dem Marketing nach Euch gefragt. Es ging um ein neues Gefährt für Euch.\n\nSie hält sich außerhalb des Gebäudes auf der linken Seite auf.", sourceObjective = "Sprecht mit Megs Schredderschreck beim HGK-Hauptquartier in Kezan.", completion = "Da ist er ja! Ich glaube, das hier wird Euch gefallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28350] = { id = 28350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallenstellermeister", description = "Eine Sache, die Ihr vielleicht nicht wisst, {name}...\n\nIch stamme von einer langen Reihe von Fallenstellern ab. Mein Vater hat mir beigebracht, so wie sein Vater ihm, die Kunst des Fallenstellens in einer äußerst humanen Art und Weise auszuführen.\n\nWie Euch jeder Meisterfallensteller bestätigen wird, ist die wichtigste Komponente einer effektiven Falle der Köder.\n\nFangen wir also damit an.\n\nFüllt diesen Eimer mit Fleischfetzen von beinah jedem beliebigen Tier in Uldum.", sourceObjective = "Sullah möchte, dass Ihr 5 Fleischfetzen von den Tieren in Uldum sammelt.", progress = "Habt Ihr genug gesammelt, um meinen Eimer zu füllen, {name}?", completion = "Gute Arbeit, mein Junge!\n\nAuch Ihr werdet im Nu ein Meister des Fallenstellens sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[28351] = { id = 28351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbegrenztes Potenzial", description = "Einige sehen in den Sandpygmäen nicht mehr als eine Plage, Ungeziefer oder gar bösartige kleine Dämonen.\n\nIch finde, sie werden völlig missverstanden!\n\nVielleicht würden sich diese kleinen Racker mit der richtigen Pflege und Führung gar als Geschenk der Natur entpuppen.\n\nIch möchte, dass Ihr diese Käfige dazu benutzt, um einige von ihnen einzufangen, damit ich mit ihnen arbeiten kann.\n\nIhr werdet hart mit ihnen kämpfen müssen, bevor sie sich einfangen lassen. Letztlich ist es aber zu ihrem Besten.\n\nIhr werdet schon sehen!\n\nIm Süden findet Ihr Pygmäen.", sourceObjective = "Verwendet den verstärkten Käfig, um 5 hüpfende Pygmäen einzufangen.", completion = "Ganz vortrefflich!\n\nEs entwickelt sich viel besser, als ich es je zu träumen gewagt hätte!", sourceObjectiveStatus = "unverified-source-field" }
quests[28352] = { id = 28352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kamelraderie", description = "Grüße!\n\nIhr seid in meinem bescheidenen Zelt stets willkommen.\n\nSeid Ihr auf der Suche nach Arbeit? Sullah hat genau das Richtige für Euch!\n\nEs ist immer gut, Kamele zu besitzen! Doch wenn man wie ich eine solche Attraktion wie meinen fahrenden Zirkus betreibt, sind sie ein absolutes Muss!\n\nNehmt diesen Harnisch und bändigt mit seiner Hilfe ein umherziehendes Kamel.\n\nOh, und vergesst nicht, es erst ein wenig ruhigzustellen... wenn Ihr wisst, was ich meine.\n\nDie südliche Wüste ist voll von wilden Kamelen.", sourceObjective = "Benutzt Sullahs Kamelzaumzeug, um 3 Kamele zu zähmen.", completion = "Ihr habt es geschafft!\n\nJetzt habe ich massig Kamele. Vielleicht werden wir eines Tages mit unserer Schau auf Reisen gehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28353] = { id = 28353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jonesy sucht Euch", description = "Hört zu, {name}, Ihr solltet bei Gelegenheit zu Jonesy zurückkehren.\n\nWahrscheinlich ist das, worüber er mit Euch sprechen möchte, dringlicher als alles, womit ich Euch beauftragen könnte.", sourceObjective = "Sprecht mit Harrison Jones in der Oase Vir'sar.", completion = "Alles klar, Junge.\n\nMeine Nachforschungen sind abgeschlossen. Wir sind fast soweit, den letzten Obelisken zu aktivieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[28354] = { id = 28354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kasha wird wieder fliegen", description = "Kasha wird wieder fliegen, {name}. Sie muss, wenn wir unsere Rache einfordern wollen! Leider muss Orkus hier bei Kasha bleiben. Ihr müsst uns helfen. Ich flehe Euch an!\n\nHört mir genau zu, Questgeber. Als ich hier eintraf, flog ich einige Tage umher, um mir die Beschaffenheit der Umgebung einzuprägen. Östlich von hier liegt ein schon lange verlassener Hof, auf dem sich mittlerweile Gnolle eingenistet haben. Auf diesem Hof gedeiht eine besondere Pilzgattung, die Morastschnauze. Reist zum Bauernhof und sammelt Morastschnauzen für Kasha. Kehrt hierher zurück, wenn Eure Taschen voll sind.", sourceObjective = "Sammelt 8 Morastschnauzenkappen.", progress = "Habt Ihr Morastschnauzen mitgebracht?", completion = "Diese Pilzart ist tödlich für alles Lebende, aber wirkt regenerierend auf Untote. Lasst uns herausfinden, welche Wirkung sie auf Kasha hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[28355] = { id = 28355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreckliche kleine Kreaturen", description = "Gnolle! Diese schrecklichen kleinen Kreaturen sind wie eine Plage für jedes Land. Bedenkt man, dass das Hügelland zum Gebiet der Verlassenen gehört, soll das schon einiges heißen. Tötet nahe der Nethandersiedlung so viele Gnolle, wie Ihr nur könnt. Es ist zum Wohle der Welt!", sourceObjective = "Tötet 10 Gnolle bei der Nethandersiedlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[28356] = { id = 28356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Präventivschlag", description = "Diese Pläne sind der Beweis, dass ein Angriff auf Süderstade kurz bevor steht. Jetzt, wo die Allianz aus der Stadt vertrieben wurde, planen die Naga des Oststrandes, sie einzunehmen.\n\nDas heißt, sofern Ihr sie nicht aufhaltet!\n\nTötet alle Naga am Oststrand und meldet Euch mit den Angriffsplänen der Säbelflossen bei Helcular an den Ruinen von Süderstade.", sourceObjective = "Tötet 15 beliebige Naga am Oststrand.", completion = "HAH! Diese Naga haben vielleicht Vorstellungen! Zu glauben, sie könnten Süderstade innerhalb der Grenzen unseres eigenen Landes so einfach erobern. Ausgemachter Unsinn ist das.\n\n<Helcular lacht.>\n\nIhren Angriff zu vereiteln war ausgezeichnete Arbeit. Allerdings frage ich mich, ob sie in der Seuche auch nur eine Minute überlebt hätten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28357] = { id = 28357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter den Bäumen", description = "Diese räudigen Köter glauben doch tatsächlich, sie könnten einfach in meinem Revier herumschnüffeln! Denen werde ich es zeigen...\n\nUnd damit meinte ich natürlich, dass IHR es ihnen zeigen werdet! Ihr und diese kleine Armee axtschwingender Goblins, die ich angeheuert und zur Nachtlaublichtung geschickt habe.\n\nDort muss es mittlerweile vor Worgen nur so wimmeln. Sie sind jetzt genau dort, wo wir sie haben wollten. Macht Euch in den Südwesten auf! Trefft Euch dort mit dem Rest unserer Truppen und wirbelt etwas Fell auf.", sourceObjective = "Tötet 8 Nachtlaubverteidiger.", completion = "Hoffen wir mal, dass wir genügend von Ihresgleichen umgelegt haben, um ihnen eine klare Botschaft zu vermitteln.", sourceObjectiveStatus = "unverified-source-field" }
quests[28358] = { id = 28358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd auf die Verdammten", description = "Die ersten Dämonen, die einen Fuß in diesen Wald setzten, waren Höllenbestien. Vor langer Zeit fielen diese mächtigen Wesen aus Stein und dämonischem Feuer vom Himmel herab, um dieses Land im Namen der Brennenden Legion in Besitz zu nehmen.\n\nDie rußgeschwärzten Krater des Narbengrunds südlich von hier markieren den Ort, an dem diese Höllenbestien herniedergingen. Noch heute verweilen viele von ihnen dort. Sie sind mächtige Gegner. Einen von ihnen zu töten ist gleichermaßen nobel und eine Herausforderung.\n\nIch biete allen eine Belohnung, die sich der Jagd anschließen. Kehrt anschließend hierher zurück.", sourceObjective = "Tötet 6 Höllenbestienwachposten.", completion = "{class}, ich muss Euch dafür danken, dass Ihr in meinem Namen jagt.\n\nIch habe erkannt, dass ich mich zügeln muss... So sehr in der Dämonenjagd aufzugehen ist ein gefährlicher Weg.", sourceObjectiveStatus = "unverified-source-field" }
quests[28359] = { id = 28359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kern von Kroshius", description = "Der gefährlichste aller Dämonen im Narbengrund ist Kroshius. In all den Jahren haben viele ihn gejagt, doch seine vielfache Vernichtung hat ihn nur noch stärker gemacht.\n\nImmer und immer wieder suchten Hexenmeister diesen Wald auf, um Kroshius erneut zum Leben zu erwecken. Umgeben von dämonischen Flammen lauert er jetzt im Südosten all jenen auf, die versuchen, seine Macht an sich zu reißen.\n\nDieser verderbte Kreislauf darf nicht länger fortbestehen! Tötet Kroshius und bringt mir seinen Höllenbestienkern.", sourceObjective = "Besorgt Kroshius' Höllenbestienkern.", progress = "Der Kern darf nie wieder in den Narbengrund zurückkehren.", completion = "Dieser verderbte Brocken lockte Jahr um Jahr immer wieder Hexenmeister an. Ich werde ihn persönlich beschützen, oder wenn möglich vernichten, auf dass sich Kroshius niemals wieder erheben kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[28360] = { id = 28360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lauf der Dinge", description = "Gerne würde ich jede Kreatur des Waldes retten, doch wie Ihr sicherlich schon bemerkt habt, ist es für einige von ihnen bereits zu spät.\n\nAls wir uns am Wisperwindhain ansiedelten, waren die Wälder südlich von hier voller wunderschöner Renner, majestätische und friedfertige Lebewesen. Die Verderbnis an diesem Ort machte sie zwar nicht aggressiv, doch sind sie mittlerweile nur noch ein Schatten ihrer selbst.\n\nSelbst wenn man sie von der Verderbnis reinigen würde, müssten sie nur Schmerz und Leid ertragen. {class}, bitte helft mir, ihnen einen gnadenvollen Tod zu gewähren.", sourceObjective = "Tötet 8 Teufelsmoderrenner.", completion = "Vielen Dank, {name}. Sie werden die Verderbnis nicht mehr weiter verbreiten und auch keine Schmerzen mehr erdulden müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28361] = { id = 28361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eichhörnchenpflege", description = "Die großen Tiere sind der Verderbnis oft schon zu lange ausgesetzt, als das man sie noch retten könnte. Aber Ihr wärt überrascht, wie widerstandsfähig die kleinen Bewohner des Waldes sind.\n\nNehmen wir zum Beispiel die Eichhörnchen. Wenn sie in verderbtem Wasser gebadet haben, können sie die Verseuchung bis weit über die Grenzen ihrer Quelle hinweg verbreiten, doch selbst fallen sie nur langsam der Verderbnis zum Opfer. Tatsächlich muss man sie nur waschen und man hat ein gereinigtes Eichhörnchen und einen wesentlich sichereren Wald!\n\nHier, nehmt diese Flasche mit Reinigungslösung. Schnappt und reinigt jedes Eichhörnchen, das Euch in den Wäldern im Süden über den Weg läuft... Sie werden es Euch danken!", sourceObjective = "Reinigt 6 besudelte Eichhörnchen.", completion = "Sind sie nicht süß?\n\nEs sind diese kleinen Erfolge, die mich zum Weitermachen motivieren. Eichhörnchen um Eichhörnchen werden wir diesen Wald retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28362] = { id = 28362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dummer Drizle!", description = "Dummer, dummer Drizle! Ich hatte ihm gesagt, er solle nicht gehen!\n\nDrizle wollte noch mehr Honig aus dem Revier der Teufelspfoten stehlen... Ihr wisst schon, westlich von hier. Ihr könnt es vom Felsvorsprung aus sehen...\n\nJedenfalls... Ich sagte ihm, dass es eine dumme Idee sei, doch er ist dennoch losgezogen und dann haben ihn die Totenwaldfälle gefangen genommen und... und...\n\nSchnief...\n\nIch weiß nicht, was sie mit ihm anstellen werden! Bitte sucht ihn, <Herr/Frau:r> {race}! Auch wenn er ein Idiot ist! Ich will nicht, dass sie Drizle fressen!", sourceObjective = "Sucht Drizle im Revier der Teufelspfoten.", completion = "HILFE! Bitte helft mir!", sourceObjectiveStatus = "unverified-source-field" }
quests[28363] = { id = 28363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stich ins Hornissennest", description = "Wow!\n\nMir scheint, Ihr habt ihre volle Aufmerksamkeit, {name}. Wir werden es niemals dort hinein schaffen, solange sie derart in Alarmbereitschaft sind.\n\nEs muss doch einen Weg geben...\n\nEs ist nur noch eine Frage der Zeit, bis Schnottz' Leute den Obelisken aktivieren, und ich muss diese Schriftrollen erforschen, die Ihr gefunden habt. Ihr müsst diese Situation ohne mich lösen.\n\nSullah hat einige Verbindungen in dieser Gegend. Vielleicht weiß er einen Weg, wie wir hinein gelangen könnten.", sourceObjective = "Sprecht mit Sullah bei Sullahs Fahrendem Zirkus.", completion = "Wisst Ihr, ich glaube, ich habe genau das Richtige für Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[28364] = { id = 28364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel des Häuptlings", description = "Schnief... Es tut mir so leid! Ich wollte nicht, dass sie mich erwischen! Als sie mich gefangen nahmen, legten sie mir diese Kette an und ließen mich hier zurück. Ich kann mich nicht bewegen, meine Beine schlafen ein und ich habe Hunger!\n\nDer Häuptling besitzt den Schlüssel... Häuptling Blutmagen nannten die anderen ihn. Er befindet sich am nördlichen Ende des Lagers.\n\nAber beeilt Euch! Bitte! Lasst mich hier nicht zurück!", sourceObjective = "Besorgt Drizles Schlüssel von Häuptling Blutmagen.", progress = "Habt Ihr den Schlüssel?", completion = "Oh danke, ich danke Euch! Ich werde hier sofort verschwinden!\n\nFalls Euch Ferli geschickt hat, sagt ihr bitte nicht, dass ich geweint habe!!", sourceObjectiveStatus = "unverified-source-field" }
quests[28365] = { id = 28365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drizle sicher" }
quests[28366] = { id = 28366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bären entwaffnen", description = "Wir sollten tun, was wir können, um mein Volk vor dem Stamm der Totenwaldfelle zu beschützen, ohne gleich jeden einzelnen von ihnen zu töten. Wir haben bereits früher schon Schritte in diese Richtung unternommen. Wenn Ihr Euch also den Furbolgs der Holzschlundfeste beweisen wollt, schlage ich vor, dass Ihr dasselbe tut.\n\nHaltet nach Waffenstapeln Ausschau, die im Revier der Teufelspfoten im Südwesten gelagert werden. Nehmt so viele an Euch, wie Ihr könnt. Vielleicht können wir dem Blutvergießen ein Ende setzen, wenn wir den Stamm der Totenwaldfelle jetzt entwaffnen.", sourceObjective = "Sammelt 7 Waffen der Totenfelle im Revier der Teufelspfoten.", progress = "Habt Ihr die Waffen?", completion = "Ich danke Euch, {race}. Euer Handeln bringt Euch dem Ziel näher, Euch als wahrer Verbündeter der Holzschlundfeste zu beweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28367] = { id = 28367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tuch der Schöpfer", description = "Es ist schön, Freunde zu haben, {class}! Auch wenn Freundlichkeit unsere einzige Belohnung ist, können wir mitunter auch greifbarere Vorteile erlangen.\n\nEin paar Freunde von mir haben kürzlich eine Lieferung von Schnottz' Plunder abgefangen und etwas gefunden, das uns gute Dienste leisten könnte.\n\nEs handelt sich dabei um Titanentechnologie, die den Träger fast unsichtbar macht. Wenn Ihr sie im feindlichen Lager benutzt, könnt Ihr vielleicht ihren Sprengstoff neu verdrahten und ihre Machenschaften hier ins Chaos stürzen.\n\nDie Wirkdauer dieser Technologie ist begrenzt, also begebt Euch nicht zu tief in Gefahr!", sourceObjective = "Sabotiert 7 von Schnottz' Pulverfässern.", completion = "Hah!\n\nIch konnte es von hier aus hören! Wie gerne hätte ich es mit eigenen Augen gesehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28368] = { id = 28368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammenhölle", description = "Verdammich, Partner! Diese Ventile habt Ihr aber mal so richtig abgeschaltet.\n\nLeider hatten wir einen kritischen Durchbruch in unserem vermaledeiten Zentralbrennerregulator. Frau Darla hat so viele Arbeiter geschickt, wie sie entbehren kann, um ihn zu versiegeln, aber diese Flammen haben ihren ganz eigenen Kopf.\n\nUnd das mein' ich wörtlich! Die hüpfen durch die Gegend und schnappen sich jeden, der ihnen zu nahe kommt! Darla sagt, wenn Ihr aus der Höhle kommen und diesen Elementar vernichten könntet, hätte sie einen schönen Preis für Euch auf Lager!", sourceObjective = "Tötet Grolvitar den Ewigbrennenden.", completion = "Nun, mein gesamtes Vorhaben hier ist fast den Bach runter gegangen. Aber Ihr wart meine Rettung in letzter Sekunde, {name}.\n\nEs hätte schlimmer sein können! Ich muss den Hut vor Euch ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28369] = { id = 28369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine Schwester Fanny", description = "Bevor Ihr geht solltet Ihr in der Gaststätte hinter mir vorbeischauen. Meine Schwester Fanny hält sich dort auf.\n\nÜberall aus den verbrannten Wildhammersiedlungen um uns herum strömen Flüchtlinge nach Donnermar. Ich habe Fanny beauftragt, sich um sie zu kümmern. Sie ist hart im Nehmen. Aber dennoch könnte sie Eure Hilfe sicher gut brauchen.", sourceObjective = "Sprecht mit Fanny Donnermar in Donnermar im Schattenhochland.", completion = "Mein Bruder schickt Euch? Gut! Ich kann einen {class} wie Euch gut brauchen. Könnt Ihr Euch im Kampf behaupten?", sourceObjectiveStatus = "unverified-source-field" }
quests[28370] = { id = 28370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irrwischentführung", description = "Könnt Ihr glauben, dass diese Worgen hier Irrwische haben? Die Nachtelfen haben ihnen all diesen Druidenkram beigebracht. Jetzt haben sie auch ihre eigenen kleinen Irrwische, die ihnen ihr Baumaterial bringen, ohne ihre kostbaren Bäume zu beschädigen.\n\nWenn wir auch solche Schätzchen hätten, könnten wir noch mehr Holz aus jedem Baum in unserem Lager herausholen. Kostenloses Material, kostenloser Profit! Daher habe ich an dieser Einfangvorrichtung hier gearbeitet.\n\nGeht zur Nachtlaublichtung und stehlt uns ein paar Irrwische. Zielt einfach auf sie und drückt die Taste.", sourceObjective = "Benutzt Darlas Irrwischmagnet, um 5 Nachtlaubirrwische zu sammeln.", completion = "Hübsche kleine Dinger, oder? Ich frage mich, ob wir vielleicht herausfinden könnten, wie man mehr davon macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28372] = { id = 28372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Geschäft", description = "Dieses ganze \"Wir sind so tolle, glückliche Freunde\"-Getue ist super, oder? Alle arbeiten zusammen, um den Wald zu heilen. Aber was passiert mit dem Wald, wenn er geheilt ist? Steht er dann einfach nur so rum?\n\nWir brauchen dieses Holz. Die Horde braucht es. Ich habe Befehle, so viele treue Soldaten der Horde wie möglich zur Eisenwaldlichtung im Norden zu schicken - und ich bin mir sicher, dass Ihr besonders treu seid.\n\nIch habe Euch beim Flugmeister bereits einen kostenlosen Hippogryphenritt dorthin organisiert. Sprecht mit Darla Schürfraupe, sobald Ihr gelandet seid.", sourceObjective = "Fliegt zur Eisenwaldlichtung und sprecht mit Darla Schürfraupe.", completion = "Fez hat Euch also geschickt, hm? Dann taugt er also doch zu etwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[28373] = { id = 28373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Holzschlundfeste", description = "Es ist vielleicht ein Schuss ins Blaue, aber fragen kann ja nicht schaden.\n\nWährend ich mich um die Verstrahlung und diesen ganzen anderen lächerlichen Kram kümmere, der hier passiert ist, müsst Ihr für mich mit ein paar Bären sprechen. Die Furbolgs der Holzschundfeste kontrollieren die Wälder im Nordosten und mögen uns nicht besonders.\n\nIch brauche einfach jemanden, der ihnen klar macht, dass die Horde gar nicht so schlimm ist. Geht nach Nordosten zur Holzschlundfeste und fragt den Furbolg, den Ihr an ihrem Eingang finden werdet, ob wir ihnen einen Gefallen tun können. Macht aber einen großen Bogen um das Revier der Teufelspfoten!", sourceObjective = "Sprecht mit Nafien bei der Holzschlundfeste im Teufelswald. Die Holzschlundfeste liegt im Osten, hinter dem Revier der Teufelspfoten.", completion = "Wir Furbolgs sind keine Narren, {name}. Wir werden die Tore der Holzschlundfeste nicht einfach so öffnen, nur weil man uns darum bittet.\n\nJedoch sind auch wir dringend auf Hilfe angewiesen. Wenn Ihr uns helft, werdet Ihr unsere Gunst erlangen und Ihr könnt sie passieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[28374] = { id = 28374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unkraut jäten", description = "An einem Ort wie diesem kann sogar etwas so Einfaches wie Blumen pflanzen und Unkraut jäten zu einer Aufgabe für echte Helden werden.\n\nDie Orchideenpeitscher, die an allen Ecken des Hains wachsen, sind ein Zeichen für seine Heilung. Jedoch sind sie nicht makellos. Einige von ihnen verfallen hin und wieder der dämonischen Verderbnis.\n\nNach meiner Erfahrung überprüft man das am besten, indem man sie ausreißt. Wenn sie normal sind, wandern sie einfach ein wenig in der Gegend herum und verwurzeln sich dann wieder. Wenn nicht, dann... Nun, macht Euch lieber auf einen Kampf gefasst.", sourceObjective = "Reißt 7 Peitscher von Wisperwind heraus, um sie auf Verderbnis zu prüfen.", progress = "Es wäre mir wirklich eine große Hilfe, wenn Ihr die Peitscher untersuchen würdet.", completion = "Es ist harte Arbeit, aber wenn man sie zu großen, starken Pflanzen heranwachsen sieht, haben sich alle Mühen gelohnt.\n\nNatürlich nur, wenn sie nicht voller dämonischer Dornen sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[28375] = { id = 28375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg ins Fegefeuer", description = "Die Zeit der Rache ist gekommen, {name}. Dank Euch kann Kasha wieder fliegen. Sie wird uns zur Fegefeuerinsel bringen, damit wir uns dem General der Sturmlanzenzwerge Vanndar Sturmlanze und seinem Hauptmann Balinda Steinbruch in den Weg stellen können. BEIDE werden für ihre Taten bezahlen.\n\nSeid Ihr bereit? Orkus kann das nicht alleine tun.", sourceObjective = "Begleitet Orkus den Königsmörder auf die Fegefeuerinsel.", completion = "Dieser Ort ist düster... unheilsschwanger. Er stinkt nach Pisse und Fell. Hier gibt es ganz sicher Worgen und sehr wahrscheinlich auch Zwerge.", sourceObjectiveStatus = "unverified-source-field" }
quests[28376] = { id = 28376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myzerians Kopf", description = "Ihr haltet jetzt den Kopf eines der berüchtigtsten schwarzen Drachen Todesschwinges in Händen.\n\nViele in Azeroth würden sicher einen hohen Preis für solch ein Artefakt bezahlen, aber etwas sagt Euch, dass er in einem Museum ausgestellt werden sollte, damit alle ihn sehen und sich erinnern können.\n\nHarrison Jones hat dafür bestimmt die richtigen Verbindungen.\n\nSullah wäre sicher mehr als bereit, ihm den Kopf zu bringen.", sourceObjective = "Bringt Myzerians Kopf zu Sullah bei Sullahs Fahrendem Zirkus.", progress = "Ihr habt diesen Drachen erlegt?!\n\nBeeindruckend!", completion = "Eine reife Leistung, {name}.\n\nIch werde ihn Harrison geben, sobald seine Expedition hier abgeschlossen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[28377] = { id = 28377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettung auf Stopfwampes Anhöhe", description = "Wenn man vom Teufel im blauen Kleid redet. Fanny hat sich doch tatsächlich von Ogern entführen lassen!\n\nIch glaube nicht, dass die Donnermars alleine eine Rettungsaktion auf die Beine stellen können. Ich werde meine Greifenreiter versammeln und ihnen ein wenig Unterstützung aus der Luft bieten.\n\n{name}, ich bin sicher, dass sie jemand wie Euch dort unten gut brauchen können. Schnappt Euch Eure Ausrüstung und sucht nach Colin Donnermar im Lager von Stopfwampes Ogern. Es liegt südwestlich von hier, unterhalb der Klippen. Beeilt Euch!", sourceObjective = "Sucht nach Colin Donnermar auf Stopfwampes Anhöhe im Schattenhochland.", completion = "Schön, dass Ihr erneut an meiner Seite kämpft, {name}.\n\nUnd die Feuerbärte sind auch da! Sie sorgen sicher für Ablenkung, während meine Jungs und ich hier die Schwerstarbeit verrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28378] = { id = 28378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Fanny", description = "Wir nehmen dieses Lager Stein für Stein auseinander, {name}, aber immer noch keine Spur von Fanny. Vielleicht könnt Ihr sie finden.\n\nDie Höhle hinter mir im Nordwesten haben wir noch nicht überprüft. Schaut, ob Ihr Fanny in der Höhle finden könnt!", sourceObjective = "Sucht und rettet Fanny Donnermar.", completion = "Fanny ist in Sicherheit! Feuerbart war also mit Euch da drin? Wie schön, dass er endlich seinen Beitrag leistet.\n\nWartet, warum schaut Ihr mich so an, {name}? Wisst Ihr etwas, das ich nicht weiß?", sourceObjectiveStatus = "unverified-source-field" }
quests[28379] = { id = 28379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogergekloppe", description = "Stopfwampes Oger! Ich würde ja sagen, sie sind dumm wie ein Sack Hämmer, aber das wäre den Hämmern gegenüber nicht gerecht.\n\nWir haben ihre Beutezüge jahrelang abgewehrt, aber wenn sie frech genug sind, einen von uns zu entführen, dann müssen wir ihnen eine Lektion erteilen.\n\nHelft uns, ein paar von Stopfwampes Ogern eine ordentliche Tracht Prügel zu verabreichen! Tötet ihre Trommler, Schleuderer oder Schläger hier draußen oder noch besser in der Höhle. Das wird ihnen eine Lehre sein!", sourceObjective = "Tötet 10 von Stopfwampes Oger (entweder Stopfwampes Trommler, Stopfwampes Schleuderer oder Stopfwampes Schläger).", completion = "Hah! Meine Männer könnten echt noch etwas lernen, wenn sie Euch bei der Arbeit zusehen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28380] = { id = 28380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pikwik in Gefahr", description = "Was zum Teufel ist hier los? Großknecht Pikwik hätte die Ventile schon längst abgeschaltet haben sollen.\n\nWenn das Zentralventil ausgeschaltet ist, können wir diese Lecks den ganzen Tag lang abdichten und zögern doch nur eine gewaltige Explosion heraus.\n\nHört mal, wenn Euch was an Geld liegt oder Eurem Leben oder vielleicht sogar an beiden, dann solltet Ihr lieber nach Süden in die Eisenwaldhöhle gehen und nach Großknecht Pikwik suchen.", sourceObjective = "Sprecht mit Großknecht Pikwik in der Eisenwaldhöhle.", completion = "Es ist eine Katastrophe! Die Pumpe ist hinüber und all meine Männer da drin sind dahin...\n\nIhr müsst mir helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[28381] = { id = 28381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Höhlenmutter", description = "Nur einen Krähenflug entfernt im Norden verwüsten die Goblins den Wald. Sie roden jeden einzelnen Baum, um Kraftstoff für die Kriegsmaschinen der Horde zu gewinnen und sich selbst ein goldenen Näschen zu verdienen. Der da wickelt die Druiden hier mit seinen schmeichelnden Worten und geschickten Lügen ein, damit sie nicht hinsehen. Sie haben Angst, die angespannte Neutralität hier zu gefährden.\n\nDie Worgen der Nachtlaublichtung haben genug davon. Schließt Euch uns an! Der Hippogryphenmeister bringt Euch direkt in unser Zuhause. Höhlenmutter Ulrica heißt <jeden/jede:r> {race} willkommen, <der/die:r> kampfbereit ist.", sourceObjective = "Fliegt zur Nachtlaublichtung und sprecht mit Höhlenmutter Ulrica.", completion = "Willkommen im Zuhause meines Rudels, {class}. Bereitet Euch auf einen Krieg vor.", sourceObjectiveStatus = "unverified-source-field" }
quests[28382] = { id = 28382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind an unseren Wurzeln", description = "Die Goblins sitzen uns schon im Nacken!\n\nWir haben mit aller Kraft versucht, die Goblins aufzufordern, die Eisenwaldlichtung zu verlassen, bevor wir Gewalt anwenden. Doch sie wollten unseren Warnungen kein Gehör schenken, also haben wir zugeschlagen. Anstatt den Wald jetzt zu verschonen, geben sie lieber ihr Leben für ihre Gier.\n\nBald werden Sie das volle Ausmaß unseres Zorns kennenlernen! Die Schlacht tobt direkt hinter unserem nördlichen Tor. Schließt Euch unserem glorreichen Rudel an und tötet alle Goblins, die es wagen, uns gegenüberzutreten!", sourceObjective = "Tötet 8 Eisenwaldhacker.", completion = "Möge ihr Blut unseren Baum nähren. Ihr kämpft gut, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28383] = { id = 28383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irrwische der Wälder", description = "Ich bemühe mich zusammen mit der Höhlenmutter schon seit langem, die Lehren des Cenarius und die Wege der Natur zu verbreiten. Sie hat sich mein Vertrauen verdient, und im Gegenzug durfte ich ihren Schülern die Geister des Waldes vorstellen. Die Gesellschaft der Irrwische ist eine große Ehre und ein nützlicher Segen.\n\nDoch nun ist die Goblinplage über uns hereingebrochen. Sie versuchen, die Irrwische für ihre üblen Zwecke zu stehlen. Bitte, verhindert diese Lästerung!\n\nRuft die Irrwische aus den westlichen Wäldern mit diesem gesegneten Zweig hierher und beschützt sie.", sourceObjective = "Benutzt die Flinkwindgerte, um 5 Nachtlaubirrwische zu sammeln.", completion = "Vielen Dank, {name}. Jetzt kann die Horde diese armen Geister nicht mehr besudeln, um sie für ihre grausamen Taten einzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28384] = { id = 28384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die Lichtung", description = "Die Eisenwaldlichtung muss dem Erdboden gleichgemacht werden. Wir können uns kein Mitleid leisten, wenn wir die Goblins daran hindern wollen, ihre Zerstörungswut auf den gesamten Wald auszubreiten.\n\nAlton Redding, mein vertrauenswürdigster Beschützer, hat bereits ein Großteil des Rudels hinter die feindlichen Linien geführt, um zuzuschlagen, solange sie hier abgelenkt sind. Sucht im Westen nach ihm, in der Nähe der Eisenwaldhöhle.", sourceObjective = "Sprecht mit Alton Redding in der Nähe der Eisenwaldhöhle", completion = "Willkommen im Rudel, {race}. Hoffentlich habt Ihr nichts dagegen, wenn es etwas unzivilisierter hergeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28385] = { id = 28385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Öl und Ironie", description = "Ich habe vor, die Gier und die Verschmutzung der Goblins gegen sie selbst einzusetzen. Ihre weitere Ausbreitung zu verhindern rechtfertigt eine weitere Ausnutzung des Landes, das sie ohnehin schon gerodet haben.\n\nTief in der Eisenwaldhöhle, direkt unter uns, verlaufen unzählige Rohre, die Öl über die gesamte Lichtung durch den Boden pumpen. Diese Rohre sind an eine Hauptkontrollpumpe tief in der Höhle angeschlossen.\n\nBetretet die Höhle und sabotiert die Pumpe. Das daraus entstehende Chaos wird uns die Gelegenheit für unseren letzten Schlag geben.", sourceObjective = "Sabotiert die Hauptkontrollpumpe in der Eisenwaldhöhle.", completion = "Ihr legt ein paar Schalter an der Pumpe um und dreht den langen Hebel ganz nach rechts. Die Wände um Euch herum erzittern und rumpeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[28386] = { id = 28386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgeliehene Bomben", description = "Die Arbeiter in der Eisenwaldhöhle wurden bereits vertrieben. Etwas anderes hat die Höhle eingenommen.\n\nDas kommt uns gelegen. Ich habe gesehen, wie ein paar von ihnen auf der Flucht Sprengstoff fallen ließen... Sprengstoff, den wir für den nächsten Teil unseres Plans gut brauchen können.\n\nBegebt Euch in die Höhle und bergt alle zurückgelassenen Bomben, die Ihr finden könnt. Wenn Ihr damit und mit der Pumpe fertig seid, werden wir unseren letzten Angriff starten.", sourceObjective = "Sammelt 8 Stück Eisenwaldsprengstoff aus der Eisenwaldhöhle.", progress = "Hatte ich Recht? Wie viele habt Ihr gefunden?", completion = "Perfekt. Ich habe den Rest des Rudels weiteren Sprengstoff aus dem Lager sammeln lassen. Zusammen mit diesem hier haben wir genug, um die Sache ins Rollen zu bringen, sobald das Öl fließt.", sourceObjectiveStatus = "unverified-source-field" }
quests[28387] = { id = 28387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerfontäne", description = "Durch Eure Sabotage an der Pumpe sind die Rohre im gesamten Lager gebrochen. Die Goblins sind wegen der Geysire in Panik. Und es wird noch schlimmer!\n\nNehmt den gesammelten Sprengstoff und setzt die Geysire in Brand. Wir werden dem Lager so viel Schaden wie möglich zufügen und sie daran hindern, dieses Öl als Schreddertreibstoff zu verwenden... oder schlimmer noch, als Treibstoff für Kriegsschiffe der Horde.", sourceObjective = "Benutzt den gestohlenen Eisenwaldsprengstoff, um 7 Ölgeysire auf der Eisenwaldlichtung in Brand zu setzen.", completion = "Schaut nur, wie sie rennen... Die wenigen Überlebenden meine ich natürlich. Herrlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[28388] = { id = 28388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutiger Lohn", description = "Erbärmliche kleine Feiglinge... Schaut nur, wie sie in Panik fliehen!\n\nLasst Euch davon nicht beirren, {name}. Sobald sie wieder bei Verstand sind, werden diese Goblins jede freie Sekunde nutzen, um diesen Wald zu Kleinholz zu verarbeiten und die Ergebnisse der Horde zur Unterstützung ihres Krieges schicken.\n\nGebt ihnen keine Gelegenheit dazu. Tötet die Arbeiter auf der Eisenwaldlichtung. Habt kein Erbarmen... Zeigt ihnen, dass ihre Gier einen hohen Preis verlangt!", sourceObjective = "Tötet 7 panische Arbeiter.", completion = "Sie haben es verdient. Jeder einzelne. Hoffen wir nur, dass ihre Anführer den Rest dieser gierigen Plünderer woanders hin schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[28389] = { id = 28389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei der Höhlenmutter", description = "Jetzt, da die Goblins verstreut sind und ihre Ausrüstung zerstört ist, werden sie entweder die Botschaft verstehen und abziehen oder leichte Beute sein, wenn sie bleiben. Wir haben gewonnen.\n\nIhr habt so wild gekämpft, wie jedes Mitglied dieses Rudels, {name}. Kehrt zur Höhlenmutter zurück und berichtet ihr von unserem Erfolg. Ich halte hier weiter Wache.", sourceObjective = "Sprecht mit Höhlenmutter Ulrica auf der Nachtlaublichtung.", completion = "Lasst die Goblins und die gesamte Horde wissen, dass wir nicht zulassen, dass sie Friedensangebote und Ort der Zuflucht missbrauchen... vor allem nicht in unserem neuen Zuhause.\n\nIch bin dankbar, dass mein Volk solch mutige Verbündete wie Euch gefunden hat, {name}. Diese Belohnung ist ein Zeichen für das Band zu unserem Rudel. Ihr seid hier immer willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28390] = { id = 28390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glop, Sohn des Glop", description = "Glop hatte einen Sohn. In seiner unermesslichen Selbstherrlichkeit nannte er ihn Glop. Und so wird die Blutlinie der Fungumanten fortgeführt.\n\nIch möchte, dass Ihr diesen neuen Fungumanten tötet. Eure Schamanenverbündete ist bereits zurückgekehrt und erwartet Euch in seiner Höhle südwestlich der Wacht Verlok.", sourceObjective = "Sprecht mit Erdheilerin Norsala und tötet dann Fungumant Glop.", completion = "Eines Tages können wir diese Steintroggs vielleicht schneller töten, als sie sich fortpflanzen, und damit die Blutlinie der Fungumanten für immer ausrotten.\n\nAlles zu seiner Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[28391] = { id = 28391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die rastlose Brut", description = "Aeosera ist rastlos und stur. Sie spottet über unsere Herrschaft und muss ständig an ihre Position erinnert werden.\n\nIch habe noch immer den Schlaghammer, den Ihr für mich besorgt habt. Kehrt zum westlichen Rand des Bleichen Horts zurück und schlagt auf den Resonanzkristall.\n\nIch werde Euch dort treffen und Euch alle Hilfe zur Verfügung stellen, die ich Euch bieten kann. Verweist sie in ihre Schranken, {class}.", sourceObjective = "Besiegt Aeosera.", progress = "Und so setzt sich der Kreislauf der Steindrachen fort. Wilde Geister in stoischer Gestalt.", completion = "Ihr seid ganz schön geschickt darin, den Willen des Drachen zu brechen, {race}. Ich wäre ja neidisch auf Eure Gewandtheit, wenn Eure Hülle nicht so zerbrechlich wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[28392] = { id = 28392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Furbolgs der Holzschlundfeste", description = "Die Furbolgs der Holzschlundfeste sind der letzte bekannte Stamm unverderbter Furbolgs. Sie drängen sich am Rand dieses Landes zusammen und verteidigen ihre Heimat in der Holzschlundfeste mit aller Macht.\n\nObwohl sie stolze Wesen sind, brauchen sie dennoch Hilfe. Falls Ihr sie unterstützen wollt, folgt der Straße von hier aus nach Norden und sucht sie am Eingang zur Holzschlundfeste auf.", sourceObjective = "Sprecht mit Nafien am Eingang zur Holzschlundfeste.", completion = "Die Druiden der Nachtlaublichtung haben uns schon früher geholfen. Wir sind immer noch nicht an die \"freundlichen\" Worgen in diesen Wäldern gewöhnt, doch auch unser Volk kennt die Sorgen von Flüchen und Verderbnis...\n\nSorgen, bei denen Ihr uns hoffentlich helfen könnt, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28393] = { id = 28393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gefährliches Bündnis", description = "Die letzten Berichte des SI:7 über die Machenschaften des Schattenhammers und der Dunkeleisenzwerge machen mir Sorgen, {name}. Es gibt Beweise, dass sie im Schwarzfels einen gemeinsamen Angriff planen. Einer solchen geballten Macht zu widerstehen wird uns schwer fallen, aber wenn wir handeln, bevor sie zuschlagen können, können wir den Angriff vielleicht abwenden.\n\nIhr müsst in die Schwarzfelstiefen reisen und die Angriffspläne des Schattenhammers von General Zornesschmied in der Westgarnison beschaffen. Zögert nicht, die Elementare auszuschalten, die seine Streitmächte unterstützen.", sourceObjective = "Tötet 6 Brandwachenzerstörer und beschafft Euch die Angriffspläne des Generals von General Zornesschmied in der Westgarnison der Schwarzfelstiefen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28394] = { id = 28394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschöpfe des Golemlords", description = "Die neusten Informationen des SI:7 über die Schwarzfelstiefen sind beunruhigend, {name}. Wie es scheint arbeitet der Schattenhammer mit dem Ingenieur der Dunkeleisenzwerge Argelmach zusammen, um durch Elementare beseelte Kriegsgolems zu erschaffen. Diese Golems könnten sich als vernichtende Waffe gegen uns herausstellen.\n\nIhr müsst das verhindern, {name}. Findet die Manufaktur in den Schwarzfelstiefen, besorgt Euch die Blaupausen, mit denen er diese Golems erschafft, und beschafft die Module, die ihnen Leben einhauchen.", sourceObjective = "Beschafft 5 Elementarmodule von den Golems in der Manufaktur der Schwarzfelstiefen und stehlt die Baupläne für einen Elementargolem.", sourceObjectiveStatus = "unverified-source-field" }
quests[28395] = { id = 28395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federn für Nafien", progress = "Zwar habt Ihr Euch mir als würdig erwiesen, aber meine argwöhnischen Stammesbrüder werden Euch bestimmt noch nicht so ohne Weiteres akzeptieren. In dieser Hinsicht kann ich Euch weiterhin helfen.\n\nManche Furbolgs der Totenwaldfelle schmücken sich mit speziellen Federn, die als Beweis dafür herhalten könnten, dass Ihr ihre Reihen gelichtet habt. Bringt mir eine Feder von jedem Kopfschmuck, den Ihr bekommen könnt; jeweils fünf von ihnen erkauft Euch ein Stück Anerkennung bei der Holzschlundfeste.", completion = "gut gemacht, {name}! Ich werde mein Volk von Euren Taten in Kenntnis setzen.\n\nIhr könnt alle Federn, die Ihr findet, zu mir bringen. Ich werde sie weiterhin so lange wir nötig annehmen." }
quests[28396] = { id = 28396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federn für Grazle", progress = "Zwar habt Ihr Euch mir als würdig erwiesen, aber meine argwöhnischen Stammesbrüder werden Euch bestimmt noch nicht so ohne Weiteres akzeptieren. In dieser Hinsicht kann ich Euch weiterhin helfen.\n\nManche Furbolgs der Totenwaldfelle schmücken sich mit speziellen Federn, die als Beweis dafür herhalten könnten, dass Ihr ihre Reihen gelichtet habt. Bringt mir eine Feder von jedem Kopfschmuck, den Ihr bekommen könnt; jeweils fünf von ihnen erkauft Euch ein Stück Anerkennung bei der Holzschlundfeste.", completion = "gut gemacht, {name}! Ich werde mein Volk von Euren Taten in Kenntnis setzen.\n\nIhr könnt alle Federn, die Ihr findet, zu mir bringen. Ich werde sie weiterhin so lange wir nötig annehmen." }
quests[28397] = { id = 28397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Damit rechnen sie nie", description = "Sie haben einen Fehler gemacht, als sie mich nicht getötet haben, solange sie die Gelegenheit hatten. Vielleicht dachten sie, Orkus würde ertrinken. HAH! Jetzt werden sie für ihre Nachlässigkeit bezahlen.\n\nWir beide werden diese Insel in Stücke reißen, {name}. Damit rechnen sie nie! Sobald all ihre Soldaten tot sind, werden wir ihre Anführer stellen. Haltet nach den Angriffsplänen Ausschau. Wenn wir die Pläne in die Finger kriegen, werden wir ihrer ganzen Invasion ein Ende machen können!\n\nLos, {name}!", sourceObjective = "Tötet 8 Zwerge der Sturmlanzen und 8 Blutfangwachen auf der Fegefeuerinsel.", progress = "Wir werden sie alle töten!", completion = "Schaut Euch nur dieses Massaker an, {name}. Wir beide sind ein tolles Team!\n\nJetzt müssen wir ihre Pläne finden und ihre Anführer erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28398] = { id = 28398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zauberfoliant des Pyromanten", description = "Tief im Schwarzfels wächst die Macht der Dunkeleisenzwerge und ihrer Schattenhammerverbündeten. Pyromant Weisenkorn, ein hoch angesehener Magier, spielt bei der Anführung der Streitmächte des Schattenhammers dort eine große Rolle. Wenn wir seinen Zauberfolianten in die Finger bekommen, könnte ich mir vielleicht Gegenzauber oder andere Mittel ausdenken,mit denen wir ihre Macht einschränken können.\n\nIhr müsst in die Schwarzfelstiefen hinabsteigen, den Schrein von Thaurissan ausfindig machen und den Zauberfolianten besorgen. Zeigt Weisenkorn und seinen Zwielichtdienern keine Gnade!", sourceObjective = "Tötet 6 Zwielichtabgesandte und besorgt Weisenkorns Zauberfoliant von Pyromant Weisenkorn am Schrein von Thaurissan in den Schwarzfelstiefen.", progress = "Konntet Ihr den Zauberfolianten des Pyromanten besorgen?", completion = "<Der Magierlehrer blätter rasch durch den Folianten.>\n\nIch habe jetzt schon mindestens ein Dutzend Zauber gesehen, von deren Existenz ich bisher nichts wusste. Das hier wird mir gute Dienste leisten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28399] = { id = 28399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steine der Bindung", description = "Ich weiß aus sicherer Quelle, dass der SI:7 sich Sorgen wegen einer Zusammenarbeit zwischen dem Schattenhammer und den Dunkeleisenzwerge in den Schwarzfelstiefen macht. Wir können diese Information als Anlass nutzen, um zu handeln, der Allianz unseren Wert zu beweisen und gleichzeitig etwas für uns selbst zu erreichen.\n\nDer Bericht besagt, dass die Anhänger des Schattenhammers mehrere Steine der Elementarbindung in der Schattenschmiede, dem Domizil, dem Schrein von Thaurissan, der Westgarnison und der Ostgarnison aufgestellt haben. Findet und holt Euch diese Steine!", sourceObjective = "Besorgt 6 Steine der Elementarbindung aus den Schwarzfelstiefen. Ihr findet die Steine in der Schattenschmiede, dem Domizil, am Schrein von Thaurissan, in der Ostgarnison und in der Westgarnison.", sourceObjectiveStatus = "unverified-source-field" }
quests[28400] = { id = 28400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helden der Horde!", description = "Jetzt müssen wir ihre Schlachtpläne finden und ihre Anführer erledigen! Wenn wir Erfolg haben, gibt es da einen Obersten Kriegsfürsten der Orcs, der im Krieg im Silberwald gekämpft hat und nun in Tarrens Mühle stationiert ist, mitten im Herzen des Hügellands. Er wird uns beide dafür belobigen! Wir werden Helden der Horde sein, {name}!\n\nVorwärts! Gemeinsam besiegen wir diesen Abschaum der Allianz!", sourceObjective = "Stehlt die Schlachtpläne der Allianz und werdet Helden der Horde.", progress = "<Oberster Kriegsfürst Cromush schaut finster drein.>", completion = "<Oberster Kriegsfürst Cromush salutiert.>\n\nEr wird als Held der Horde geehrt werden, so wie er es sich immer gewünscht hat. Was Ihr und Orkus getan habt wird Hunderte von Leben retten und sicherstellen, dass wir unsere Position im Hügelland nicht verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[28401] = { id = 28401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sklaven des Feuerlords", description = "In den Hallen der Schwarzfelstiefen versammeln der Schattenhammerkult und die Dunkeleisenzwerge ihre Streitkräfte. Ihre Legionen werden von Horden aus Feuerelementaren unterstützt, die der Feuerlord Ragnaros als Diener an sich gebunden hat.\n\nWenn wir die Elementare aus ihrem Bund befreien, können wir sowohl unsere Feinde schwächen als auch den Elementen Ehre erweisen. Nehmt dieses Totem und wirkt es auf die unterworfenen Brandwachen. Das wird ihre Geister befreien und ihren natürlichen Zustand wiederherstellen.", sourceObjective = "Benutzt das Totem der Freiheit, um die Essenzen von 6 Brandwachen, Brandwachenzerstörern oder lodernden Brandwachen in den Schwarzfelstiefen zu befreien.", completion = "Ihr habt der Allianz und Eurer Berufung als {class} einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28402] = { id = 28402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnottz und Wasser", description = "Ich bin fast fertig, {name}.\n\nEure Rollen enthielten genügend Informationen, um ihre Verschlüsselungsmethode zu erkennen. Jetzt muss ich die Codes nur noch übersetzen.\n\nIhr müsst für mich die Kammer unter dem Obelisken des Mondes ausspähen. Wahrscheinlich halten sich dort unten ein paar von Schnottz' Truppen auf, die Eurer Explosion entkommen konnten.\n\nKümmert Euch um sie. Ich werde Euch dort treffen, wenn ich fertig bin.", sourceObjective = "Tötet 10 Elitesoldaten von Schnottz in der Kammer des Mondes.", completion = "In Ordnung, {name}.\n\nIch glaube, jetzt ist alles bereit. Dann mal los!", sourceObjectiveStatus = "unverified-source-field" }
quests[28403] = { id = 28403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungültige Daten", description = "In dieser Kammer müsste es zwei Kommunikationsgeräte der Titanen geben.\n\nWenn meine Berechnungen korrekt sind, ist eines davon eine Todesfalle und das andere nimmt die Codes an und aktiviert den Obelisken.\n\nIch hoffe, ich habe alles richtig verstanden.\n\nGebt mir Bescheid, wenn Ihr bereit seid.", sourceObjective = "Begleitet Harrison Jones in der Kammer des Mondes.", completion = "Gut, {name}.\n\nIch glaube, ich kann das manuell erledigen, aber ich brauche dazu Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28404] = { id = 28404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich mache das von Hand", description = "Ja, das kommt mir ziemlich bekannt vor.\n\nDank der Informationen, die Ihr für mich gesammelt habt, kann ich den Mechanismus bestimmt aktivieren. Ich muss mich jedoch eine Weile ganz genau konzentrieren können.\n\nSobald ich loslege wird dieses Titanenkonstrukt sicher versuchen, mich aufzuhalten.\n\nUnd genau da kommt Ihr ins Spiel.\n\nIch muss Euch sicher nicht daran erinnern, was auf dem Spiel steht. Schaltet diesen Wächter aus!", sourceObjective = "Besiegt den titanischen Wächter.", completion = "Das sollte genügen.\n\nBleibt zurück!", sourceObjectiveStatus = "unverified-source-field" }
quests[28405] = { id = 28405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen der Dunkelheit", description = "In den Schwarzfelstiefen hausen schon lange unsere Feinde, aber jetzt hat der SI:7 uns informiert, dass die Dunkeleisenzwerge und der Schattenhammer verstärkt zusammenarbeiten. Mit dem Wissen des Kultes verstärken die Dunkeleisenzwerge ihre Waffen mit elementaren Kräften. Sie haben die Legion der Zorneshämmer mit diesen schrecklichen neuen Waffen ausgerüstet.\n\nIch möchte, dass Ihr in die Schwarzfelstiefen reist und den Zwergen der Zorneshämmer ihre Waffen abnehmt. Zerbrecht sie auf dem Schwarzen Amboss im Herzen der Schattenschmiede.", sourceObjective = "Sammelt 5 elementarerfüllte Waffen von den Zwergen der Zorneshämmer in den Schwarzfelstiefen und zerbrecht sie auf dem Schwarzen Amboss in der Schattenschmiede.", completion = "Dank Eurer Bemühungen werden diese Waffen niemals das Blut der Allianz vergießen. Ausgezeichnete Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28406] = { id = 28406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Armee der Dunkeleisenzwerge", description = "So langsam werden die Dinge im Schwarzfels interessant, {name}. Unsere Quellen berichten, dass die Dunkeleisenzwerge sich immer enger an den Schattenhammer binden und gemeinsam einen bedeutenden Angriff planen.\n\nIch habe die wichtigsten Anführer in Sturmwind über den Inhalt dieser Berichte informiert und möchte, dass Ihr uns dabei helft, dieser wachsenden Bedrohung durch die Dunkeleisenzwerge Herr zu werden.\n\nDie Rationen für die Armeen der Dunkeleisenzwerge werden größtenteils in der Ostgarnison und Westgarnison der Schwarzfelstiefen aufbewahrt. Nehmt dieses Gift und gebt es auf ihre Getreidevorräte.", sourceObjective = "Benutzt das schnell wirksame Gift, um 6 Getreiderationen in der Westgarnison oder Ostgarnison der Schwarzfelstiefen zu vergiften.", sourceObjectiveStatus = "unverified-source-field" }
quests[28407] = { id = 28407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Junggesellin", description = "Feuerbart? Meine Schwester heiraten?! Ich schwöre Euch, die Welt ist verrückt geworden, {name}!\n\nAber vielleicht hat Kurdran Recht. Eine nette, ganz normale Hochzeit würde alle auf andere Gedanken bringen... und Feuerbart ein wenig abkühlen. Es hat mir eigentlich ganz schön Spaß gemacht, hier mit ihm gegen die Oger zu kämpfen.\n\nAlso gut! Fanny hat das letzte Wort. Irgendetwas sagt mir, dass sie sich nicht gern binden lassen möchte.\n\nFliegt zurück nach Kirthafen und fragt sie, ob sie einverstanden ist. Ich werde unsere schmutzige Aufgabe mit den Ogern hier erledigen.", sourceObjective = "Sprecht mit Fanny in Kirthafen im Schattenhochland.", completion = "<Fanny wirft verärgert die Arme in die Luft.>\n\nIhr, Kurdran, Feuerbart und jetzt auch noch mein Bruder. Anscheinend ist bei allen das Hochzeitsfieber ausgebrochen!\n\nGut, dann heirate ich Keegan Feuerbart eben. Aber nur weil er stark und gutaussehend ist und einen Kiefer hat, der Steine zerbeißen kann, und einen Hintern so hart wie ein Amboss. Nicht aus politischen Gründen.\n\nAber wir werden Eure Hilfe brauchen. Wir haben eine Mordshochzeit auszurichten und nicht viel Zeit dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[28408] = { id = 28408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Geballtes", description = "Traditionell tragen die Bräute der Wildhämmer weiß als Symbol ihrer Reinheit. Zusätzlich tragen sie eine Krone aus schwarzen Federn, um ihren geballten Mumm zu zeigen.\n\nAm besten zeigt man seinen Mumm mit Eulenfedern, und Fanny verdient nur das Beste. Im Hochland leben viele Waldeulen. Sie kreisen meist um die Bäume an den Klippen. Nehmt Euch ihre Federn.\n\nAm besten tötet ihr sie vorher.", sourceObjective = "Sammelt 12 makellose Eulenfedern.", progress = "Habt Ihr Fannys Federn?", completion = "Ah, Ihr arbeitet schnell. Eine geballte Ladung Federn für eine geballte Ladung Frau. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[28409] = { id = 28409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Gebrautes", description = "Eine Wildhammerhochzeit ohne standesgemäße Getränke wäre eine Beleidigung. Kurdran selbst hat ein paar Fässer des seltenen Donnerbräu Lagerbiers aus Hochstade angefordert, aber die Karawane konnte den Pass nicht überqueren.\n\nFolgt der Straße östlich von hier, die um die Südseite des Bergs Donnerschlag führt, und holt die Karawane ein. Sucht nach einem Kerl namens Hammerhand und helft ihm, das Gebräu über den Pass zu bringen!", sourceObjective = "Sprecht mit Hammerhand auf der Straße östlich von Kirthafen und begleitet die Versorgungskarawane sicher in die Stadt.", progress = "Ist die Straße frei? Oder macht das Drachenmal wieder Ärger?", completion = "Ah, Russell der Barde schwärmt immer von Donnerbräu Lagerbier. Es hat sicher nicht den Kick eines guten Wildhammerbräus, aber er hört gar nicht auf von seinem \"Körper\" und den \"Geschmacksnuancen\" zu reden. Schätze, wir werden es herausfinden, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[28410] = { id = 28410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Gestohlenes", description = "Für solch ein Ereignis will jeder natürlich besonders gut aussehen, aber feiner Zwirn ist im Hochland rar.\n\nSoweit ich weiß benutzen jedoch diese verdammten Goblins an der Küste feinste Seide, um die Ballons ihrer Zeppeline zu reparieren. Was für eine Verschwendung!\n\nFindet einen Zeppelin, der zwischen dem Hafen des Drachenmals und den Krazzwerken hin und her fliegt, und stibitzt ein wenig Seide aus dem Frachtraum in den unteren Decks.", sourceObjective = "Sammelt einen Ballen feinen dunklen Stoffs.", progress = "Wie lief der Raubzug in den Lüften?", completion = "Oh, genau! Kilts für die Herren, Roben für die Brautjungfern.\n\nSagt den Damen bloß nicht, dass sie Kleider tragen, die für ein Luftschiff gefertigt wurden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28411] = { id = 28411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Geschmortes", description = "Und schließlich brauchen wir noch ein Festmahl. Und bestimmt nicht solche modernen \"Häppchen\". Diese Menge will Fleisch und zwar viel davon.\n\nSammelt Wildbret von den Hochlandelchen und Hochlandrehen. Die Hochlandworgs sind auch ganz lecker. Bringt mir ein paar Rippchen. Wir werden Euch einen Schmaus auftischen, wie Ihr ihn in den ganzen Östlichen Königreichen noch nie gesehen habt, Freund.", sourceObjective = "Sammelt 8 Scheiben frisches Wildbret und 5 Worgrippchen.", progress = "Was gibt es Neues von der Nahrungsfront, {name}?", completion = "Da schau mal einer an! Ihr biegt Euch ja richtig unter dem Gewicht des ganzen Fleischs. Dann schicke ich meine Leute lieber mal an die Töpfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[28413] = { id = 28413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Text und Musik von...", description = "Ich habe in meinem Leben schon viele epische Melodien verfasst, {name}, aber diese nahende Hochzeit verdient eine ganz besondere Ballade. Und das schnell!\n\nSoll ich eine Ode an die Liebe schreiben? Eine scherzhafte Melodei? Ein anzügliches Trinklied?\n\nIch könnte ein wenig Hilfe mit dem Text brauchen, wenn Ihr Lust habt, Euch als Schreiber zu versuchen.\n\nSprecht mit mir, dann schreiben wir zusammen ein Lied!", sourceObjective = "Sprecht mit Russell Brower und helft ihm, ein Lied zu schreiben.", progress = "\"Text und Musik von Russell Brower, dem Barden, und {name}, dem {class}.\"\n\nKlingt fantastisch.", completion = "Ein echter Ohrwurm, so viel ist sicher.\n\nAber ist es auch ein Klassiker?", sourceObjectiveStatus = "unverified-source-field" }
quests[28414] = { id = 28414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drölfmeterschießen", description = "Jetzt liegt es an Euch, <Junge/Mädel>. Ihr habt die Dampfdruckhaie vernichtet, also müsst Ihr jetzt nur noch das Siegertor schießen.\n\n<Der Trainer beugt sich zu Euch hinüber und flüstert Euch ins Ohr.>\n\nNur unter uns... Ich finde, wir müssen jetzt aufs Ganze gehen. Ich möchte nicht, dass Ihr einfach nur ein Tor schießt... Ich möchte, dass Ihr so weit schießt, dass die Fußbombe zwischen den beiden Schornsteinen hinter dem Ziel hindurch fliegt!\n\nIch habe die Fußbombe ein wenig verändert, sodass sie die zusätzliche Leistung hat, die Ihr benötigt.\n\nUnd jetzt geht raus da und macht mich stolz!", sourceObjective = "Steigt in den Bilgewasserbukanier und schießt das Siegertor, indem Ihr die Fußbombe durch die beiden Schornsteine hinter dem gegnerischen Tor schießt.", completion = "Äh... Ihr habt es geschafft, Junge. Ihr habt es WIRKLICH geschafft! Wir haben das Spiel gewonnen und...\n\nHABT IHR DIESEN DRACHEN GESEHEN?!", sourceObjectiveStatus = "unverified-source-field" }
quests[28415] = { id = 28415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieben auf einen Streich", description = "Wir müssen handeln. Winky und Gor'tesh hatten sich gestritten, also habe ich diese Freundschaftszeremonie geplant, damit sie sich wieder versöhnen. Alles lief super, bis...\n\nNun, den Rest kennt Ihr ja.\n\nIch habe sogar Getränke besorgt!\n\nWinky liebt Flammenfliegen. Er schleicht sich fast jede Nacht davon, um sie zu jagen. Vielleicht ist er ja dorthin gegangen.\n\nIhr findet die Flammenfliegen im Westen und Norden, immer in der Nähe von Lava. Bringt mir sieben davon. Beeilt Euch!\n\nGor'tesh geht vielleicht als Nächster!", sourceObjective = "Sammelt 7 Feuerfliegen.", progress = "<Oralius schnappt in die Luft, hebt seine Faust und späht hoffnungsvoll zwischen seinen geschlossenen Fingern hindurch.>", completion = "Ihr werdet nie glauben, was passiert ist! Winky ist zurück! Wir haben gar keine Feuerfliegen gebraucht.\n\nBekommt ein Zwerg hier vielleicht einen Bauchkrauler zur Feier des Tages? Kommt schon! KRAULT MEIN BÄUCHLEIN!", sourceObjectiveStatus = "unverified-source-field" }
quests[28416] = { id = 28416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennende Rache", description = "{name}... seid Ihr das? Ich dachte, Ihr wärt tot, so wie der Rest!\n\nNein, Ihr wart schon immer stark. Schon damals im Rotkammgebirge.\n\nUnser Kampf ist noch nicht vorbei, {name}. Sie haben schon einmal unsere Heimat angegriffen. Ich bin hier, um sicherzustellen, dass das nicht noch einmal passiert.\n\nWenn Ihr immer noch so kämpfen könnt wie damals, dann schließt Euch mir an. Geht zunächst nach Süden in die Schlupfhügel und tötet ihre Jungdrachenbändiger und Schwarzdrachenbrutlinge.\n\nEs wird wie in alten Zeiten sein.", sourceObjective = "Tötet 5 Jungdrachenbändiger des Schwarzfels und 5 Flammenschuppenbrutlinge.", completion = "Ich bin froh, Euch an meiner Seite zu wissen, {name}. Die Kompanie Bravo wieder vereint, was?\n\nOh, habe ich erwähnt, dass Trottmann auch hier ist?", sourceObjectiveStatus = "unverified-source-field" }
quests[28417] = { id = 28417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unschuldig", description = "Die Schwarzfelsorcs in der Steppe dienen einem finsteren Meister, der abartige Experimente an lebenden Wesen durchführt, um seine eigene Menagerie der Monstrositäten zu schaffen. Viele seiner Testobjekte sind so verderbt wie ihr Meister, aber ein paar davon sind vollkommen unschuldig.\n\nIn den Schlupfhügeln im Süden ketten sie Jungdrachen am Boden fest, um sie für solche Experimente vorzubereiten. Das lasse ich nicht zu. Zerbrecht ihre Fesseln und bringt die Brutlinge zu mir... in Sicherheit.", sourceObjective = "Beschafft einen befreiten roten Welpling, einen befreiten grünen Welpling, einen befreiten blauen Welpling und einen befreiten bronzefarbenen Welpling.", progress = "Ich hoffe, wir kommen nicht zu spät.", completion = "Ich werde mich darum kümmern, dass diese Drachen versorgt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[28418] = { id = 28418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennende Rache", description = "Ich bin von Geburt an ein Schwarzfelsorc. Ich habe einen Großteil meiner Kindheit in diesem Berg verbracht.\n\n<Ariok zeigt auf den Schwarzfels im Norden.>\n\nAber auch wenn das gleiche Blut in unseren Adern fließt, teile ich ihre Ansichten nicht. Ich suche nach einem Verbündeten, der mir dabei hilft, ihren kommenden Angriff aufzuhalten.\n\nAlso beweist Euch. Reist nach Süden in die Schlupfhügel und tötet ihre Jungdrachenbändiger und Schwarzdrachenbrutlinge. Zeigt mir, dass Ihr für diesen Krieg bereit seid.", sourceObjective = "Tötet 5 Jungdrachenbändiger des Schwarzfels und 5 Flammenschuppenbrutlinge.", completion = "Ihr seid also dabei?\n\nGut.", sourceObjectiveStatus = "unverified-source-field" }
quests[28419] = { id = 28419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstockung", description = "Wenn wir einen Krieg gegen den Schwarzfelsklan führen wollen, müssen wir vorausplanen. Mein Vater hat bereits einen Plan geschmiedet - jetzt wird es Zeit, ihn in die Tat umzusetzen.\n\nIch brauche Skorpidstachel... die schärfsten, die Ihr finden könnt. Skorpide befinden sich überall in der Steppe, aber die meisten befinden sich in der Schlucht im Westen.\n\nZerbrecht Euch nicht den Kopf darüber, wofür sie sind. Das werdet Ihr noch früh genug herausfinden.", sourceObjective = "Besorgt 5 rasiermesserscharfe Skorpidstachel.", progress = "Schon zurück?", completion = "Man kann diese Skorpiden leicht unterschätzen. Ihr habt Glück, dass Ihr nicht an einem dieser Stachel steckt. Oder vielleicht seid Ihr einfach nur gut.\n\nIch füge sie dem Vorratslager hinzu. Wir sind noch nicht fertig, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[28420] = { id = 28420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein zukünftiges Projekt", description = "Laut meinem Vater brauchen wir Worgbälge, und zwar viele. Es macht nichts, wenn sie zerrissen, versengt oder blutig sind. Hauptsache es sind genügend.\n\nEigentlich wäre es sogar besser, wenn sie ein wenig ramponiert aussehen.\n\nWorgs findet Ihr im Westen und im Osten.", sourceObjective = "Besorgt 11 Glutworgbälge.", progress = "Dann schauen wir uns die Bälge mal an.", completion = "Glaubt mir, {name}... Ich kann es genauso wenig wie Ihr abwarten, bis wir endlich zum Töten kommen. Aber wir müssen uns an den Plan halten. Das Jüngste Gericht kommt früh genug.\n\nIch werde diese Bälge hier aufbewahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[28421] = { id = 28421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlammschlacht", description = "Ich hoffe, Ihr habt keine Angst davor, Euch schmutzig zu machen. Aber wenn ich Euch so ansehe, dürfte das kein Problem sein.\n\nIm Norden am Rand der Lava findet Ihr dunkle Schlammhaufen. Den Schlamm brauche ich.\n\nAm besten stellt Ihr keine Fragen und konzentriert Eure Bemühungen darauf, Befehle zu befolgen, {name}.", sourceObjective = "Besorgt 9 Haufen obsidiandurchsetzten Schlamm.", progress = "Ihr solltet Euch vor den Obsidianelementaren hüten. Sie schleichen sich gerne an.", completion = "Genau das brauchen wir.\n\nKeine Sorge, {name}... Eure Klinge wird bald Blut zu schmecken bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[28422] = { id = 28422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sand, der Apfelwein und die Kugel", description = "Mein Vater wartet auf uns im Osten. Bevor wir aufbrechen müssen wir jedoch noch ein paar Vorräte sammeln. Diesmal werdet Ihr es einem Hexenmeister mit Namen Gorzeeki Wildaug abnehmen.\n\nWahrscheinlich findet Ihr ihn im Nordwesten in der Nähe des Altars der Stürme. Sagt ihm, dass er uns helfen wird. Wir brauchen den Sand, den Apfelwein und die Kugel.\n\nEr weiß schon, was das bedeutet.", sourceObjective = "Sprecht mit Gorzeeki Wildaug in der Nähe des Altars der Stürme.", completion = "Bah! Wer seid Ihr?\n\nOh, also hat Ariok Euch geschickt? Gut. Würde es Euch etwas ausmachen, wenn Ihr eine Weile hier bleibt? Nichts großes... Ihr müsst nur ein paar Hexenmeister für mich töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[28423] = { id = 28423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexenmeister haben das beste Zeug", description = "Ariok sagt, er braucht Vorräte? Ich habe haufenweise Vorräte! Das Problem ist nur, dass diese Hexenmeister mich aus meinem Zuhause geworfen haben und mich nicht wieder hineinlassen.\n\n<Gorzeeki mustert Euch.>\n\nIhr könntet vielleicht hineingelangen. Geht nach Norden und holt mir meinen Schlummersand, mein Teufelskarussellstöffsche und eine klare Glaskugel. Ich bin mir ziemlich sicher, dass es das ist, was er haben will.\n\nOh, und falls Ihr aus Versehen ein paar dieser Orcs tötet, während Ihr da oben seid, wäre ich bestimmt nicht traurig.", sourceObjective = "Besorgt eine Handvoll Schlummersand, einen Krug Teufelskarussellstöffsche und eine lupenreine Glaskugel.", progress = "Mal sehen, ob Ihr alles bekommen habt.", completion = "Ich hoffe, dass ist das, wonach Ariok gesucht hat. Im Moment kann ich jedenfalls nicht viel damit anfangen.", sourceObjectiveStatus = "unverified-source-field" }
